// Russian server-rendered tool explanations and FAQs.
export const ruPageCopy: Record<string, string> = {
  "pageText.494b4551": "Конфиденциальны ли мои данные?",
  "pageText.62172ab3": "Да, выполнение полностью происходит в вашем браузере.",
  "pageText.f60263be": "Что такое JSON?",
  "pageText.b285e12f": "JSON (JavaScript Object Notation) — компактный формат обмена данными, который легко читать и записывать людям, а компьютерам — разбирать и создавать.",
  "pageText.5fb110d7": "Как отформатировать JSON?",
  "pageText.3241bbe1": "Вставьте корректный JSON в поле ввода, выберите нужные отступы и параметры сортировки ключей, затем нажмите «Форматировать JSON».",
  "pageText.fd4a654d": "В безопасности ли мои данные?",
  "pageText.542fb6d3": "Да! Вся обработка происходит в браузере. Ваши данные никогда не покидают компьютер.",
  "pageText.d16ff7e1": "Что делает форматировщик JSON",
  "pageText.647c3353": "Форматировщик JSON разбирает текст JSON и сериализует полученное значение с единообразными пробелами. Этот инструмент форматирует данные с выбранными отступами, минифицирует результат и при необходимости рекурсивно сортирует ключи объектов. RFC 8259 требует двойных кавычек для имён полей и строк; комментарии, завершающие запятые, NaN и Infinity не входят в грамматику JSON. Форматирование меняет представление, но не предполагаемый смысл данных.",
  "pageText.c80fe1c6": "Применение и границы проверки",
  "pageText.b49ba2b3": "Используйте форматировщик, когда нужно изучить или нормализовать JSON при разработке:",
  "pageText.92e09088": "Сделать компактный ответ API, тело вебхука, конфигурацию или запись журнала удобнее для чтения.",
  "pageText.a1f30e1f": "Минифицировать корректный JSON перед копированием в запрос, тестовые данные или переменную окружения.",
  "pageText.57fc338e": "Отсортировать ключи для более предсказуемого ручного сравнения двух объектов.",
  "pageText.a199e1c3": "Найти ошибки разбора из-за пропущенных запятых, несовпадающих скобок или некорректных кавычек.",
  "pageText.bcfd24c3": "Успешный разбор означает только проверку синтаксиса. Он не применяет JSON Schema, контракты API, обязательные поля, предметные типы или бизнес-правила.",
  "pageText.0b90c1ae": "Пример форматирования",
  "pageText.52d27152": "Ввод {\"active\":true,\"user\":{\"id\":42,\"roles\":[\"admin\",\"editor\"]}} превращается в объект с отступами, где вложенное значение user и массив roles видны с первого взгляда. Минификация снова создаёт компактную форму. Если бы ввод содержал завершающую запятую, браузерный парсер отклонил бы его, а не незаметно исправил документ.",
  "pageText.97fb560b": "Ограничения и конфиденциальность",
  "pageText.57498e3b": "При разборе используются числа JavaScript, поэтому целые числа за пределами надёжно представимого диапазона могут терять точность.",
  "pageText.ff4c61d4": "Повторяющиеся имена полей могут объединяться при разборе; избегайте разбора с повторной сериализацией, если важно сохранить повторы.",
  "pageText.c4310853": "Отсортированный результат удобен, но не является форматом криптографической канонизации JSON и не должен использоваться для подготовки подписываемых данных.",
  "pageText.e01043b7": "Обработка выполняется в браузере. Конфиденциальный JSON всё ещё может раскрыться через историю буфера обмена, расширения браузера, демонстрацию экрана или общее устройство.",
  "pageText.7491abdf": "Что проверяет этот инструмент?",
  "pageText.000db4ab": "Он проверяет синтаксис JSON по RFC 8259: двойные кавычки у ключей и строк, запятые между элементами, совпадение скобок, корректность чисел и экранирования, а также единственное значение верхнего уровня.",
  "pageText.d5749034": "Какие ошибки JSON встречаются часто?",
  "pageText.5c93c394": "Пропущенные и завершающие запятые, одинарные кавычки вместо двойных, имена свойств без кавычек, комментарии, неэкранированные переводы строк внутри строк и пропущенные закрывающие скобки.",
  "pageText.e46fbe66": "Почему JSON с комментариями или завершающими запятыми не проходит проверку?",
  "pageText.716a4b48": "Стандартный JSON не допускает ни того, ни другого. Редакторы вроде VS Code принимают их в файлах настроек JSONC, а JSON5 тоже разрешает их, но JSON.parse и большинство API отклоняют. Удалите их перед передачей данных строгому парсеру.",
  "pageText.14469b94": "Почему ошибка указывает не на то место?",
  "pageText.7c657bf0": "Парсеры сообщают место, где разбор остановился, часто сразу после самой ошибки. Пропущенная запятая отмечается у следующего ключа, а незакрытая строка или скобка может обнаружиться лишь в конце ввода.",
  "pageText.40ba76d4": "Означает ли корректный JSON соответствие контракту API?",
  "pageText.10c910fb": "Нет. Проверка синтаксиса лишь доказывает, что текст разбирается. Чтобы проверить обязательные поля, типы и допустимые значения, проверьте документ по схеме в валидаторе JSON Schema.",
  "pageText.eb70ad1f": "Да. Проверка выполняется в браузере через JSON.parse, и вставленный JSON не загружается на сервер.",
  "pageText.c7264f74": "Что делает JSON корректным",
  "pageText.bc86098b": "JSON строже синтаксиса объектов JavaScript. Документ — одно значение: объект, массив, строка, число, true, false или null. Ключи и строки должны быть в двойных кавычках, а внутри строк допускается лишь небольшой набор escape-последовательностей с обратной косой чертой, например \\n, \\t, \\\" и \\uXXXX. Числа не могут иметь ведущие нули, знак + в начале или точку в конце; NaN и Infinity недопустимы. Комментарии и завершающие запятые не входят в стандарт, поэтому JSONC и JSON5 здесь не проходят проверку, даже если редактор их принимает.",
  "pageText.41041c7a": "Частые ошибки JSON и их исправление",
  "pageText.5e91d5ea": "Завершающая запятая: {\"a\": 1,} — удалите запятую после последнего элемента.",
  "pageText.c20c98a8": "Одинарные кавычки: {'a': 'b'} — замените их двойными.",
  "pageText.dcfdd19f": "Ключи без кавычек: {a: 1} — заключите каждый ключ в кавычки: {\"a\": 1}.",
  "pageText.544083f8": "Пропущенная запятая: {\"a\": 1 \"b\": 2} — ошибка обычно указывает на \"b\", начало следующего элемента.",
  "pageText.9cec3362": "Обычные переводы строк или табуляции внутри строки — записывайте их как \\n или \\t.",
  "pageText.7165deea": "Литералы языков: True, None, undefined и NaN не являются значениями JSON; используйте true, null или строку.",
  "pageText.02f2728d": "Как читать позицию ошибки",
  "pageText.e4c68e30": "Текст ошибки поступает из JSON-парсера браузера, поэтому формулировки в Chrome, Firefox и Safari различаются. Если сообщение содержит позицию символа, валидатор преобразует её в строку и столбец. Посмотрите на это место и перед ним: парсер останавливается на первом символе, который не может продолжить корректный документ, часто на один токен позже самой ошибки.",
  "pageText.21519e4a": "Статистика и ограничения парсера",
  "pageText.7a975d41": "Для корректного JSON инструмент подсчитывает объекты, массивы, строки, числа, логические значения, null и общее число ключей, а также максимальную глубину вложенности. Это помогает обнаружить неожиданно глубокие данные или изменение типов, например числа, пришедшие строками. У JSON.parse есть две особенности: повторяющиеся ключи принимаются с последним значением, а числа читаются как 64-битные числа с плавающей точкой, поэтому целые больше 2^53 - 1 теряют точность в разобранном значении и отформатированной копии.",
  "pageText.035fa382": "Чем это отличается от валидатора JSON?",
  "pageText.bab0a1c3": "Валидатор JSON проверяет корректность синтаксиса текста. Валидатор JSON Schema также проверяет разобранное значение по правилам обязательных свойств, типов, диапазонов и вложенных структур.",
  "pageText.c715893e": "Какую версию JSON Schema поддерживает инструмент?",
  "pageText.b987a2d9": "Инструмент использует Ajv v8 с валидатором по умолчанию, совместимым с Draft 7. Неизвестные расширенные ключевые слова игнорируются с видимым предупреждением; схемы, которым нужна другая метасхема, могут требовать настройки для конкретного черновика.",
  "pageText.7d800344": "Мой JSON загружается на сервер?",
  "pageText.0f050d2b": "Нет. Разбор, компиляция схемы и проверка выполняются в браузере. Избегайте конфиденциальных данных на общих устройствах: история буфера обмена и расширения браузера всё ещё могут их раскрыть.",
  "pageText.842ff766": "Что проверяет JSON Schema",
  "pageText.0cf82fa3": "Проверка синтаксиса JSON лишь доказывает, что текст можно разобрать. JSON Schema применяет контракт к разобранному значению: требует свойства, ограничивает типы и диапазоны, отклоняет неожиданные поля и проверяет вложенные массивы или объекты. Результат содержит путь к значению, путь в схеме, ключевое слово и сообщение для каждого обнаруженного нарушения правила.",
  "pageText.54bfa1e8": "Как использовать валидатор",
  "pageText.813839e9": "Вставьте проверяемое значение JSON в редактор документа.",
  "pageText.110b07c6": "Вставьте совместимую с Draft 7 схему JSON Schema в редактор схемы.",
  "pageText.f0234285": "Нажмите «Проверить», чтобы скомпилировать схему и получить все соответствующие ошибки.",
  "pageText.060913a1": "Используйте пути к значениям для поиска ошибочных данных, а пути в схеме — для поиска отклонившего их правила.",
  "pageText.2b1361d8": "Ограничения и конфиденциальность",
  "pageText.74eb328b": "Успешная проверка означает, что текущий документ соответствует всем распознанным правилам предоставленной схемы; она не доказывает, что схема выражает все бизнес-правила. Неизвестные расширенные ключевые слова игнорируются с видимым предупреждением. Внешние схемы не загружаются автоматически, а схемы для неподдерживаемых черновиков или удалённых ссылок могут требовать настройки приложения. Документ и схема разбираются с числами JavaScript, поэтому целые вне безопасного диапазона могут терять точность.",
  "pageText.e7bc2558": "Какие форматы поддерживаются?",
  "pageText.ffabae3c": "Массивы объектов JSON с одной стороны и текст с разделителями с другой: CSV с запятыми, CSV с точками с запятой, TSV с табуляцией или значения с вертикальными чертами.",
  "pageText.5e2ca3f9": "Как обрабатываются вложенные объекты?",
  "pageText.929320e9": "В режиме Flatten вложенные объекты превращаются в столбцы с точечной записью, например address.city, а массивы записываются как текст JSON. Режим JSON String записывает каждый вложенный объект или массив как текст JSON в одном столбце верхнего уровня.",
  "pageText.e74ea8dd": "Можно ли преобразовать один объект JSON в CSV?",
  "pageText.2de8fa13": "Сначала заключите его в квадратные скобки, например [{\"id\": 1}]. Конвертер ожидает непустой массив, в котором каждый объект становится одной строкой.",
  "pageText.16c231f7": "Почему после преобразования CSV в JSON все значения — строки?",
  "pageText.82993149": "CSV не содержит типов данных, поэтому каждая ячейка возвращается строкой (\"30\", а не 30), чтобы не ошибиться с почтовыми индексами или ID с ведущими нулями. Преобразуйте необходимые поля в своём коде.",
  "pageText.df332cb3": "Почему Excel показывает искажённые символы с диакритикой?",
  "pageText.af4d1154": "Скачанный файл — UTF-8 без метки порядка байтов, а некоторые версии Excel предполагают старую кодировку при открытии CSV двойным щелчком. Импортируйте через «Данные > Из текста/CSV» и выберите UTF-8.",
  "pageText.44ee1d3e": "Мои данные загружаются на сервер?",
  "pageText.3c70ccff": "Нет. Разбор и преобразование выполняются в браузере, а файл для скачивания создаётся локально.",
  "pageText.c0a1927b": "Какую структуру JSON можно преобразовать в CSV",
  "pageText.110e0569": "CSV — плоская таблица, поэтому ввод должен быть массивом объектов JSON, например [{\"id\": 1, \"name\": \"Ada\"}, {\"id\": 2, \"name\": \"Linus\"}]. Каждый объект становится строкой. Заголовок объединяет все ключи в порядке первого появления, поэтому отсутствующий ключ даёт пустую ячейку, а не сдвигает другие столбцы; null тоже записывается как пустая ячейка. Ввод, который не является непустым массивом, отклоняется; у массива простых значений вроде [1, 2, 3] нет ключей для столбцов.",
  "pageText.16c22164": "Обработка вложенных объектов и массивов",
  "pageText.2c00e178": "Flatten (по умолчанию): {\"address\": {\"city\": \"Paris\"}} становится столбцом address.city. Массивы записываются текстом JSON в одну ячейку, например [\"a\",\"b\"].",
  "pageText.98e451ad": "JSON String: сохраняет только столбцы верхнего уровня и записывает каждый вложенный объект или массив текстом JSON в его ячейку.",
  "pageText.e646f74d": "Expand: тоже сохраняет столбцы верхнего уровня, но не сериализует вложенные объекты, поэтому они выглядят как [object Object]. Для вложенных данных используйте Flatten или JSON String.",
  "pageText.869ce735": "Кавычки: поля с разделителем, двойной кавычкой или переводом строки заключаются в двойные кавычки, а внутренние кавычки удваиваются (\"\"), как описано в RFC 4180.",
  "pageText.73ca705a": "Преобразование CSV обратно в JSON",
  "pageText.cbff28ff": "Парсер CSV обрабатывает поля в кавычках, удвоенные кавычки и переводы строк внутри значений в кавычках, принимает окончания строк LF и CRLF. При включённом «Первая строка — заголовки» ячейки заголовка становятся именами свойств; иначе используются ключи column1, column2 и так далее. Пустые строки пропускаются, отсутствующие ячейки становятся пустыми строками, а ячейки сверх ширины заголовка отбрасываются. Заголовки с точками вроде address.city не восстанавливаются во вложенные объекты, и все значения остаются строками; дополнительно обработайте результат, если нужны числа, логические значения или вложенность.",
  "pageText.e37dc901": "Выбор разделителя",
  "pageText.1b5836ff": "Для большинства инструментов и API используйте запятую. Выберите точку с запятой для табличных программ с локалью, где запятая — десятичный разделитель; табуляцию — для TSV, удобного для вставки в таблицы; вертикальную черту — если значения часто содержат запятые. При обратном преобразовании используйте ту же настройку разделителя.",
  "pageText.3f419e1e": "Чем отличаются interface и type?",
  "pageText.2896a196": "Оба описывают структуру объектов. Интерфейсы можно расширять через extends и объединять между объявлениями, а псевдонимы типов также выражают объединения, пересечения и отображаемые типы. Для обычных моделей API подходит любой вариант; следуйте соглашениям кодовой базы.",
  "pageText.a76e5f0e": "Как обрабатываются массивы?",
  "pageText.9e602604": "Массивы одного типа становятся string[], number[] и так далее. Смешанные массивы становятся объединениями вроде (string | null)[]. Для массивов объектов ключи всех элементов объединяются в один тип элемента, а пустой массив становится unknown[].",
  "pageText.15efe178": "Почему свойство имеет тип null или unknown[]?",
  "pageText.e7edbada": "В образце недостаточно информации. Значение null можно определить только как null, а в пустом массиве нет элемента для анализа. Замените их реальными типами, например string | null или Order[].",
  "pageText.3f42cbef": "Проверяют ли созданные типы данные при выполнении?",
  "pageText.63a3aa5d": "Нет. Типы TypeScript удаляются при компиляции кода и не могут отклонить некорректный ответ API. Для недоверенного ввода используйте вместе с ними валидатор времени выполнения, например Zod, или проверку JSON Schema.",
  "pageText.dfbfc464": "Как использовать созданный интерфейс?",
  "pageText.ecad980d": "Сохраните его в файле .ts, импортируйте и укажите тип разобранных данных, например const user = (await response.json()) as Root; Приведение документирует ожидаемую структуру, но не проверяет её.",
  "pageText.f2cb618b": "Нет. JSON разбирается и преобразуется в браузере, а созданные типы никуда не отправляются.",
  "pageText.24604c50": "Как типы определяются по образцу JSON",
  "pageText.775e7460": "Конвертер разбирает JSON и сопоставляет каждое значение типу TypeScript: строки — string, числа — number (в JSON нет отдельного целого типа), true и false — boolean, null — null. Объекты становятся интерфейсами или псевдонимами типов, массивы — типом элемента с []. Например, {\"id\": 1, \"tags\": [\"a\", \"b\"], \"owner\": null} даёт id: number; tags: string[]; owner: null;. Ключи, которые не являются допустимыми идентификаторами, например \"first-name\", заключаются в кавычки.",
  "pageText.2a4f9a5c": "Параметры и их действие",
  "pageText.d80a13bc": "«Имя корневого типа» задаёт имя типа верхнего уровня с преобразованием в PascalCase.",
  "pageText.58ca8924": "«Использовать интерфейс» переключает между объявлениями interface и псевдонимами type.",
  "pageText.b2718dc0": "«Сделать свойства необязательными» добавляет ? к каждому свойству.",
  "pageText.7bc73d90": "«Добавить ключевое слово export» ставит export перед каждым объявлением.",
  "pageText.f1ea6f0b": "«Извлекать вложенные» создаёт именованный интерфейс для каждого вложенного объекта и объектов внутри массивов (orders становится OrdersItem[]) вместо встроенных типов объектов.",
  "pageText.e8492b19": "«Определять объединения» записывает смешанные массивы как объединения, например (string | null)[].",
  "pageText.f3ef2d66": "«Комментарии JSDoc» добавляет комментарий над каждым свойством; при включённом извлечении вложенных объектов комментарии содержат примеры значений.",
  "pageText.91b2ba93": "Ограничения определения типов по одному образцу",
  "pageText.962bd555": "Один документ JSON показывает лишь один ответ, а не все структуры, которые может вернуть API. Проверьте следующие случаи перед использованием результата:",
  "pageText.c04be53a": "Значения null в образце получают только тип null. При извлечении вложенных объектов они также отмечаются необязательными.",
  "pageText.65099d30": "В массивах объектов первое найденное значение ключа определяет его тип, а ключи, присутствующие лишь в части элементов, не отмечаются необязательными, если не включено «Сделать свойства необязательными».",
  "pageText.1eb094ba": "При извлечении вложенных объектов строки дат ISO вроде 2024-01-15 или 2024-01-15T00:00:00Z получают тип Date. JSON.parse возвращает строки, поэтому замените тип на string, если код их не преобразует.",
  "pageText.1effcea1": "Числовые строки остаются string, большие целые — number; генератор не угадывает bigint или брендированные типы ID.",
  "pageText.9f62e4a3": "Свойства сохраняют порядок образца, а объект без ключей становится {} для интерфейсов или Record<string, unknown> для псевдонимов типов.",
  "pageText.0a050da5": "Что такое YAML?",
  "pageText.521b34a0": "YAML (YAML Ain't Markup Language) — удобочитаемый формат сериализации данных с отступами вместо фигурных скобок. Он распространён в конфигурациях Kubernetes, Docker Compose, GitHub Actions и Ansible.",
  "pageText.758c1349": "Когда использовать YAML, а когда JSON?",
  "pageText.ed21d83b": "YAML удобнее читать и редактировать вручную, он поддерживает комментарии и подходит для конфигураций. JSON проще разбирать, у него нет правил отступов и он поддерживается повсеместно, поэтому удобен для API и обмена данными.",
  "pageText.e2958c4e": "Какой режим совместимости YAML используется?",
  "pageText.962cba8d": "Преобразование использует схему совместимости YAML 1.1 библиотеки js-yaml, поэтому якоря, псевдонимы, ключи слияния, явные теги и типизированные скаляры работают как в образце. YAML 1.1 может трактовать некоторые обычные скаляры иначе, чем YAML 1.2.",
  "pageText.d8137672": "Почему yes, no или NO превратились в true или false?",
  "pageText.a21ecd10": "В YAML 1.1 значения yes, no, on и off без кавычек — логические. Заключите значение в кавычки, например country: \"NO\", если оно должно остаться строкой.",
  "pageText.5403e57d": "Можно ли преобразовать YAML-файл с несколькими документами?",
  "pageText.69ba905b": "Не за один раз. Конвертер читает один документ и сообщает об ошибке при разделителях --- с последующим содержимым. Разделите файл и преобразуйте каждый документ отдельно.",
  "pageText.1368c99b": "Сохраняются ли комментарии YAML?",
  "pageText.311c9ca4": "Нет. В JSON нет синтаксиса комментариев, поэтому при преобразовании в JSON они удаляются и не восстанавливаются при преобразовании обратно в YAML.",
  "pageText.c261a8ae": "Как YAML преобразуется в JSON",
  "pageText.4bc6e145": "Отображения YAML становятся объектами JSON, последовательности — массивами, скаляры — строками, числами, логическими значениями или null. Комментарии удаляются, а якоря (&name), псевдонимы (*name) и ключи слияния (<<: *defaults) разворачиваются в полные копии, поэтому JSON может оказаться длиннее YAML. Преобразование JSON в YAML создаёт обычный блочный YAML: ключи сохраняют исходный порядок, длинные строки не переносятся, повторяющиеся объекты записываются полностью вместо якорей.",
  "pageText.8680939e": "Значения YAML 1.1, которые не являются строками",
  "pageText.28441e9f": "Схема YAML 1.1 соответствует многим существующим парсерам конфигураций, но назначает некоторые неожиданные типы значениям без кавычек:",
  "pageText.b9e6b5c4": "yes, no, on и off становятся true или false. Это классическая «проблема Норвегии»: country: NO превращается в false.",
  "pageText.195c972a": "Числа с ведущим нулём, например 010, читаются как восьмеричные (8), а 0x1F — как шестнадцатеричные (31).",
  "pageText.4683982b": "Цифры, разделённые двоеточиями, например 22:22, читаются как числа с основанием 60 (1342), что может нарушить сопоставления портов и время.",
  "pageText.bc57ba5f": "version: 1.10 становится числом 1.1, а даты вроде 2024-01-01 — временными метками (2024-01-01T00:00:00.000Z).",
  "pageText.b58f4598": "Кавычки и частые ошибки разбора",
  "pageText.f9b2a402": "Заключайте в кавычки значения, которые должны остаться текстом: version: \"1.10\", port: \"22:22\", country: \"NO\". Результат JSON в YAML автоматически заключает такие строки в кавычки.",
  "pageText.159243ab": "Табуляция в отступах запрещена. Сообщение ошибки указывает строку и столбец, например (2:1).",
  "pageText.cafe74b5": "Ошибка bad indentation of a mapping entry обычно означает, что один ключ имеет иной отступ в пробелах, чем соседние.",
  "pageText.249bfb43": "Обычные значения, начинающиеся с *, &, !, %, @ или обратной кавычки, имеют специальное значение в YAML и должны быть в кавычках.",
  "pageText.b07acd91": "Для JSON в YAML нужен строгий JSON: завершающие запятые, комментарии и строки в одинарных кавычках отклоняются.",
  "pageText.6ad0b0ed": "Проверка файлов Kubernetes и CI",
  "pageText.155c7fbc": "Манифесты Kubernetes, файлы Docker Compose и процессы GitHub Actions пишутся в YAML, а вывод kubectl get -o json и jq работают с JSON. Преобразование файла в JSON позволяет быстро увидеть назначенные парсером типы, например стал ли порт числом или версия осталась строкой, до ошибки развёртывания. При обратном преобразовании в YAML добавьте нужные комментарии вручную.",
  "pageText.ac46f1af": "JSON Pointer — это то же, что JSONPath?",
  "pageText.cac8f6a8": "Нет. JSON Pointer — компактный синтаксис RFC 6901 для указания одного значения. JSONPath — отдельный язык запросов с фильтрами, шаблонами и другими возможностями выбора.",
  "pageText.8f9cad79": "Как указать косую черту или тильду в ключе?",
  "pageText.de336765": "Кодируйте тильду как ~0, а косую черту как ~1 внутри каждого токена ссылки. Например, /a~1b выбирает поле объекта с именем a/b.",
  "pageText.3da5dc4a": "Что выбирает пустой указатель?",
  "pageText.354d9f94": "Пустой JSON Pointer выбирает весь документ JSON.",
  "pageText.57bcfda7": "Что делает вычислитель JSON Pointer",
  "pageText.f894f2e1": "JSON Pointer определяет одно значение, последовательно проходя по разделённым косыми чертами токенам документа JSON. Токены объектов точно совпадают с именами полей, токены массивов используют индексы с нуля. Вычислитель сообщает об отсутствующем поле, некорректном экранировании или индексе массива и попытке пройти через примитив вместо того, чтобы незаметно вернуть неверное значение.",
  "pageText.ab93ef77": "Синтаксис и границы",
  "pageText.ce9c3b21": "Используйте пустую строку для корня документа и / для поля объекта с пустым именем.",
  "pageText.3cde0e22": "Кодируйте ~ как ~0, а / как ~1 внутри токена. Сначала декодируйте ~1 в /, затем ~0 в ~, как требует RFC 6901.",
  "pageText.dcc291b6": "Индексы массивов — канонические неотрицательные десятичные целые числа. Особый токен - полезен для добавления в конец массива через JSON Patch, но не указывает на существующее значение.",
  "pageText.c2421fef": "Инструмент вычисляет только синтаксис JSON Pointer; он не реализует фильтры JSONPath, операции JSON Patch, декодирование фрагментов URI или проверку схемы.",
  "pageText.532a56fb": "Чем JSONPath отличается от JSON Pointer?",
  "pageText.ad67c7e7": "JSON Pointer определяет одно точное значение токенами, разделёнными косыми чертами. JSONPath — язык запросов, который может выбирать несколько значений с помощью шаблонов, срезов и рекурсивного обхода.",
  "pageText.f33ae85e": "Поддерживает ли тестер выражения фильтра?",
  "pageText.922825ba": "Нет. Он намеренно поддерживает безопасное основное подмножество RFC 9535 и отклоняет фильтры или скриптовые выражения вместо выполнения кода. Используйте имена дочерних полей, индексы, шаблоны, срезы или рекурсивный обход.",
  "pageText.37dcaef8": "Документ JSON загружается на сервер?",
  "pageText.b2396fff": "Нет. Разбор JSON и вычисление пути выполняются в браузере. История буфера обмена, расширения, скрипты страницы и общие устройства всё ещё могут раскрыть конфиденциальный ввод.",
  "pageText.926480c9": "Что выбирает тестер JSONPath",
  "pageText.6475775d": "Запрос JSONPath начинается с $ и проходит по полям объектов или элементам массивов. Однозначный путь вроде $.store.book[0].title выбирает одно значение, а шаблоны, срезы и рекурсивный обход могут дать упорядоченный список совпадений. Каждый результат содержит выбранное значение и нормализованный путь к его расположению во входном документе.",
  "pageText.0522c849": "Поддерживаемый синтаксис и границы безопасности",
  "pageText.167ce42e": "Используйте .name или ['name'] для полей объектов и [0] или [-1] для индексов массивов.",
  "pageText.325bdf69": "Используйте .* или [*] для шаблонов дочерних элементов, [start:end:step] для срезов массивов и ..name или ..* для рекурсивного обхода.",
  "pageText.0fa965f1": "Селекторы фильтра, встроенный JavaScript, функции и выражения в стиле оболочки отклоняются; инструмент никогда не выполняет текст запроса как код.",
  "pageText.0bd77a57": "Тестер проверяет синтаксис JSON до запроса. Он не применяет JSON Schema и не доказывает соответствие выбранных значений контракту API.",
  "pageText.86927e79": "Как понимать результаты JSONPath",
  "pageText.5564c402": "Ноль совпадений означает, что корректный запрос не выбрал значения в текущем документе; это отличается от выбора JSON null. Шаблоны и рекурсивный обход могут вернуть много значений, а одинаковые значения в разных местах остаются отдельными совпадениями, поскольку их нормализованные пути различаются.",
  "pageText.2a7811c2": "Может ли один образец JSON описать все допустимые данные?",
  "pageText.8aeafe2c": "Нет. Генератор определяет только значения и структуры, присутствующие в образце. Сверьте обязательные и необязательные поля, бизнес-ограничения, перечисления, значения по умолчанию, уточнения и преобразования с реальным контрактом API.",
  "pageText.9c0cad39": "Как обрабатываются массивы и отсутствующие свойства объектов?",
  "pageText.01ee6835": "Типы элементов массивов объединяются. Объекты в одном массиве имеют общую объединённую структуру, а свойство, отсутствующее хотя бы в одном объекте образца, становится необязательным. Смешанные массивы примитивов становятся объединениями Zod; пустые массивы используют элементы z.unknown().",
  "pageText.2decefae": "Нет. Разбор JSON и генерация схем выполняются в браузере. Конфиденциальные данные всё ещё могут раскрыться через историю буфера обмена, расширения браузера, демонстрацию экрана или общее устройство, поэтому по возможности используйте обезличенные примеры.",
  "pageText.a2131814": "Что создаёт генератор JSON в Zod",
  "pageText.843b2234": "Генератор разбирает одно значение JSON и сопоставляет строки, числа, целые числа, логические значения, null, массивы и объекты выражениям Zod. Корневое имя нормализуется в допустимый идентификатор схемы TypeScript. При включённых выводимых типах результат также содержит псевдоним z.infer, чтобы валидатор времени выполнения и тип времени компиляции происходили из одной схемы.",
  "pageText.9fdeb27b": "Правила вывода типов для проверки",
  "pageText.a373d436": "Целые числа становятся z.number().int(), а значения с дробной частью — z.number().",
  "pageText.7640c5c6": "Смешанные образцы массивов становятся объединениями. Массивы объектов объединяют наблюдаемые ключи и отмечают необязательными ключи, отсутствующие хотя бы в одном образце.",
  "pageText.51004b4a": "Необязательное определение формата распознаёт типичные строки UUID, даты-времени ISO, электронной почты и URL HTTP(S) с проверками строк Zod.",
  "pageText.297ff683": "Строгий режим объектов добавляет .strict(), чтобы неизвестные ключи отклонялись, а не незаметно удалялись созданными схемами объектов.",
  "pageText.373ed392": "Пустые массивы не раскрывают тип элементов и поэтому становятся z.array(z.unknown()).",
  "pageText.3733edff": "Вывод по образцу — отправная точка, а не контракт",
  "pageText.35b1bbc6": "Образец не доказывает минимальную длину, числовые диапазоны, допустимые значения перечислений, межполевые правила, значения по умолчанию, поведение приведения или обязательность случайно присутствующего поля. Сравните результат с документацией API и реальными граничными случаями, затем добавьте уточнения Zod и тесты перед приёмом недоверенного ввода. Инструмент создаёт только исходный текст; он не выполняет схему и не устанавливает Zod в проект.",
  "pageText.b12736d6": "Конфиденциальность и ограничения ввода",
  "pageText.ac6e0f5e": "Генерация локальна и детерминирована для одинаковых настроек и данных. Глубина вложенности ограничена для сохранения отзывчивости браузера. Не вставляйте рабочие токены или персональные данные даже в локальные инструменты, если обезличенный пример может описать ту же структуру.",
  "pageText.c12e919d": "Какие операции JSON Patch поддерживаются?",
  "pageText.f93d0eb6": "Применение поддерживает add, remove, replace, move, copy и test. Созданные патчи используют детерминированные операции add, remove и replace; изменённые массивы заменяются целиком вместо нестабильного поэлементного сравнения.",
  "pageText.9bcbf59a": "Как косая черта и тильда представлены в путях?",
  "pageText.153cbcc5": "Пути JSON Patch используют JSON Pointer по RFC 6901. Косая черта в ключе объекта становится ~1, а тильда — ~0, поэтому ключ a/b адресуется как /a~1b.",
  "pageText.9bd286e3": "Меняет ли применение патча исходный редактор?",
  "pageText.1e520c6e": "Нет. Исходный JSON клонируется перед операциями, а результат показывается отдельно. Удаление всего корня документа отклоняется, поскольку инструмент всегда возвращает корректное значение JSON.",
  "pageText.830d9198": "Как различия JSON становятся патчем",
  "pageText.27cb8257": "Ключи объектов сравниваются в отсортированном порядке, поэтому одинаковый ввод даёт одинаковую последовательность операций. Исчезнувшие ключи становятся remove, новые — add, изменённые примитивы или массивы — replace. Вложенные объекты обходятся рекурсивно, а каждый созданный путь экранируется как JSON Pointer по RFC 6901.",
  "pageText.7a310a1e": "Применение патча и поведение при ошибках",
  "pageText.afbc723e": "Индексы массивов проверяются строго, а особый токен - добавляет в конец только при операциях add.",
  "pageText.e8c8cf45": "Replace, remove, move, copy и test требуют существования исходных путей; ошибки указывают номер операции.",
  "pageText.3a420fd8": "Move не допускает помещение значения в его собственный дочерний элемент и применяет изменения индексов массива в порядке операций.",
  "pageText.b3c285ba": "Test использует структурное равенство JSON, а не идентичность объектов или порядок сериализованных ключей.",
  "pageText.7a08072a": "Особые имена объектов вроде __proto__ создаются как собственные свойства данных без изменения прототипов объектов.",
  "pageText.acc508bd": "Детерминированность, конфиденциальность и проверка",
  "pageText.39b818a8": "Генерация и применение полностью выполняются в этом браузере. Созданные различия намеренно предсказуемы, но не гарантированно минимальны, особенно для массивов. Перед применением патча к постоянным данным или API проверьте порядок операций, стоимость замены массивов, параллельные версии документа и права приложения.",
  "pageText.28d8aae9": "Какие языки программирования поддерживаются?",
  "pageText.b4757b15": "Сейчас генератор поддерживает Go (структуры Golang с тегами JSON), Python (Pydantic v2 BaseModel), Rust (структуры Serde), C# (записи с JsonPropertyName) и Kotlin (классы данных).",
  "pageText.294e643e": "Как обрабатываются вложенные объекты и массивы?",
  "pageText.850e01f2": "Вложенные объекты JSON извлекаются в отдельные типизированные структуры или классы с camelCase/PascalCase, а типы элементов массивов определяются автоматически.",
  "pageText.05225c44": "Мои данные JSON загружаются на какой-либо сервер?",
  "pageText.16c71e23": "Нет. Генерация кода полностью выполняется локально в браузере с помощью клиентского JavaScript.",
  "pageText.6bf4c146": "Как инструмент рассчитывает размер JSON в байтах?",
  "pageText.94825111": "Он вычисляет точное число байтов UTF-8 в отформатированных и минифицированных данных JSON через браузерный TextEncoder API.",
  "pageText.449785d1": "Какие показатели извлекаются?",
  "pageText.200cd0b4": "Исходный размер в байтах, минифицированный размер, процент уменьшения, общее число ключей, вложенных объектов и массивов, максимальная глубина и число полей null.",
  "pageText.6bafe4b9": "Да, вся обработка происходит локально в браузере.",
  "pageText.f9bc4fe7": "Что такое кодирование Quoted-Printable?",
  "pageText.b1f6a629": "Quoted-Printable — кодировка с печатными символами ASCII (RFC 2045), предназначенная для передачи не-ASCII символов по электронной почте.",
  "pageText.5c516685": "Защищены ли мои данные?",
  "pageText.ee52101e": "Да, всё кодирование и декодирование полностью выполняется локально в браузере.",
  "pageText.6c6f7098": "Что такое кодировщик и декодировщик Base64URL?",
  "pageText.f020a31f": "Кодирование и декодирование безопасного для URL Base64 без символов заполнения.",
  "pageText.16ca11a3": "Чем Base64url отличается от стандартного Base64?",
  "pageText.3b137bc0": "Base64url заменяет + на - и / на _, чтобы значение безопасно использовалось в URL, именах файлов и сегментах JWT, и обычно опускает заполнение =.",
  "pageText.06b202a5": "Можно ли преобразовать существующую строку Base64 вместо кодирования текста?",
  "pageText.59313335": "Да. Режим Base64 в Base64url меняет алфавит и удаляет заполнение, а Base64url в Base64 восстанавливает +, / и заполнение =. Байты не перекодируются.",
  "pageText.ad19a97c": "Обрабатываются ли мои данные безопасно?",
  "pageText.32092515": "Да, вся обработка и вычисления полностью выполняются локально в браузере для конфиденциальности и скорости.",
  "pageText.054c55ba": "Является ли Base64 шифрованием?",
  "pageText.040d6643": "Нет. Base64 — обратимая кодировка без ключа, которую может декодировать любой. Никогда не используйте её для сокрытия паролей, API-токенов или персональных данных; для этого нужно настоящее шифрование, например AES-GCM.",
  "pageText.c07235a3": "Как декодировать Base64 в JavaScript?",
  "pageText.190c8592": "В Node.js используйте Buffer.from(value, 'base64').toString('utf8'). В браузере atob(value) возвращает двоичную строку, поэтому для текста UTF-8 используйте new TextDecoder().decode(Uint8Array.from(atob(value), (c) => c.charCodeAt(0))).",
  "pageText.3d513a1d": "Как кодировать строку в Base64 в Python?",
  "pageText.5817c0f8": "Используйте base64.b64encode('text'.encode('utf-8')).decode('ascii') после import base64. Для безопасного для URL алфавита вызывайте base64.urlsafe_b64encode.",
  "pageText.43cf2c6b": "Почему Base64 заканчивается на = или ==?",
  "pageText.9dc050ab": "Base64 кодирует 3 байта в 4 символа. Если длина ввода не кратна 3, один или два символа = дополняют результат до кратного 4. Они не несут данных; этот декодировщик также принимает ввод вообще без заполнения.",
  "pageText.1e9e71cb": "Почему внешне корректный Base64 здесь не декодируется?",
  "pageText.2bfb36f5": "Либо строка содержит символы вне стандартного алфавита (часто - или _ из Base64URL), либо декодированные байты не являются текстом UTF-8. Изображения, PDF и другие двоичные данные не подходят этому текстовому декодировщику даже при корректном Base64; используйте Base64 в изображение или Base64 в PDF.",
  "pageText.1f843857": "Мои данные отправляются на сервер?",
  "pageText.5356631f": "Нет. Кодирование и декодирование используют встроенные функции браузера btoa и atob на вашем устройстве; ничего из вставленного не загружается на сервер.",
  "pageText.9673c683": "Как работает кодирование Base64",
  "pageText.6840df16": "Base64 читает по три байта ввода (24 бита) и делит их на четыре группы по 6 бит. Каждая группа выбирает символ из алфавита длиной 64 символа: A-Z, a-z, 0-9, + и /. Если длина ввода не кратна трём, результат дополняется одним или двумя знаками = для длины, кратной четырём. Например, Man кодируется в TWFu, Ma — в TWE=, M — в TQ==.",
  "pageText.376d85ff": "Перед кодированием инструмент преобразует текст в байты UTF-8, поэтому не-ASCII символы корректно восстанавливаются: é занимает два байта и кодируется в w6k=, а эмодзи 😀 — четыре байта и кодируется в 8J+YgA==.",
  "pageText.3144275a": "Почему результат Base64 примерно на 33% больше",
  "pageText.ce1baf42": "Каждые 3 байта ввода становятся 4 символами вывода, поэтому данные растут примерно на треть плюс до двух символов заполнения. Данные размером 30 КБ становятся примерно 40 КБ Base64. Это плата за представление любых байтов печатными символами, поэтому Base64 встречается в полях JSON, URI данных, вложениях электронной почты и заголовках HTTP Basic Auth. Это не сжатие и не шифрование.",
  "pageText.b3162ffd": "Base64 и Base64URL",
  "pageText.1a8a3497": "Стандартный Base64 (RFC 4648, раздел 4) использует + и / и дополняется =. Base64URL (раздел 5) заменяет + на - и / на _ и обычно опускает заполнение, чтобы значения использовались в URL, именах файлов и сегментах JWT без процентного кодирования. Этот инструмент использует стандартный алфавит. Для декодирования Base64URL здесь сначала замените - на + и _ на / либо используйте отдельный кодировщик Base64URL.",
  "pageText.92565596": "Частые ошибки декодирования и исправления",
  "pageText.a3f451e2": "Недопустимые символы: всё вне A-Z, a-z, 0-9, +, / и = отклоняется. Обычно виноваты - и _ из Base64URL или кавычки, скопированные вместе со значением.",
  "pageText.8245a36e": "Неверная длина: значение с остатком 1 при делении длины на 4 не может быть корректным, что обычно означает потерю символа при копировании. Полностью отсутствующее заполнение допускается.",
  "pageText.f0196a80": "Двоичное содержимое: декодированные байты должны быть корректным текстом UTF-8. Base64 изображений, PDF или сжатых данных здесь не проходит, хотя сама кодировка верна.",
  "pageText.016597d5": "Переводы строк: пробелы и переводы строк внутри одного значения, например MIME с переносом каждые 76 символов, игнорируются. Но в пакетном режиме каждая строка считается отдельным значением.",
  "pageText.49b68226": "Что такое URL-кодирование?",
  "pageText.5cd6b8f1": "Процентное кодирование представляет байт UTF-8 как % и две шестнадцатеричные цифры. Оно используется, когда символ нельзя безопасно поместить в определённую часть URI.",
  "pageText.a2c17b54": "Кодировать компонент или полный URL?",
  "pageText.5905cd6b": "Используйте режим компонента для одного значения запроса, сегмента пути или значения фрагмента, поскольку он также экранирует разделители &, =, / и ?. Используйте режим полного URL, если ввод уже содержит полный URL и его структурные разделители должны оставаться читаемыми.",
  "pageText.f176d778": "Почему декодирование иногда не удаётся?",
  "pageText.231a3849": "После знака процента должны идти две шестнадцатеричные цифры, а полученная последовательность байтов должна декодироваться. Незавершённые последовательности вроде %2 или некорректный UTF-8 отклоняются вместо незаметного изменения.",
  "pageText.a85f9468": "Что меняет URL-кодировщик",
  "pageText.62d7dab2": "Режим компонента использует поведение браузерных encodeURIComponent и decodeURIComponent. Он подходит для отдельного значения запроса или сегмента пути, поскольку зарезервированные разделители URL кодируются как данные. Режим полного URL использует encodeURI и decodeURI, которые сохраняют структурные символы :, /, ?, #, & и =, чтобы уже собранный URL сохранял структуру.",
  "pageText.e84e968c": "Пример процентного кодирования",
  "pageText.d6bede20": "Кодирование компонента \"hello world&role=admin\" даёт hello%20world%26role%3Dadmin. Если вставить этот текст в строку запроса без кодирования компонента, амперсанд и знак равенства могут стать новыми параметрами запроса вместо части значения. Пакетный режим независимо применяет выбранную операцию к каждой непустой входной строке.",
  "pageText.d69c3bf2": "Границы и конфиденциальность",
  "pageText.66960492": "Это процентное кодирование URI, а не сериализация application/x-www-form-urlencoded; кодировщики форм обычно представляют пробелы как + и применяют правила на уровне полей.",
  "pageText.fb49cce2": "Декодирование не проверяет безопасность, доступность или надёжность полученного URL. Отдельно проверяйте схемы, хосты и адреса перенаправления.",
  "pageText.7ebaf6d4": "Не кодируйте повторно уже кодированное значение, если двойное кодирование не задумано: % может стать %25.",
  "pageText.5bdbc315": "Преобразование выполняется в браузере. История буфера обмена, расширения, общие устройства и место вставки результата остаются отдельными путями раскрытия данных.",
  "pageText.d1225e2e": "Доказывает ли декодирование подлинность JWT?",
  "pageText.154670ea": "Нет. Любой может кодировать заголовок и полезную нагрузку в Base64URL. Подлинность устанавливается только после проверки разрешённым алгоритмом с правильным ключом и прохождения всех обязательных правил утверждений.",
  "pageText.06daf1d8": "Какие алгоритмы JWT эта страница может подписывать и проверять?",
  "pageText.50e5fffd": "Она поддерживает HMAC HS256, HS384 и HS512 с текстовым секретом. Она намеренно отклоняет alg:none и не принимает RSA, ECDSA, EdDSA, JWK, JWKS или ключи сертификатов.",
  "pageText.d4ee3edc": "Токены и секреты загружаются на сервер?",
  "pageText.f21783fe": "Нет. Декодирование, подпись HMAC через Web Crypto и проверка подписи выполняются в браузере. Токены Bearer и секреты остаются уязвимыми к истории буфера обмена, расширениям, демонстрации экрана и общим устройствам, поэтому используйте синтетические данные.",
  "pageText.e5b685cb": "Декодирование, проверка и подпись — разные операции",
  "pageText.d5099b0a": "Декодирование разделяет компактный токен на три части и читает JSON-заголовок и утверждения без доверия к ним. Проверка выбирает HS256, HS384 или HS512 из защищённого заголовка, проверяет точные подписанные данные через Web Crypto, затем оценивает exp, nbf, iat и необязательные ожидания issuer или audience. Подпись сериализует предоставленные JSON-объекты, заменяет header.alg выбранным алгоритмом HMAC и создаёт компактный JWS для тестирования.",
  "pageText.1305057d": "Правила проверки и признаки для отладки",
  "pageText.7576ed65": "Корректная подпись HMAC доказывает наличие того же секрета у подписанта; она не доказывает безопасное хранение или передачу секрета.",
  "pageText.6e0c0a9d": "Токен отклоняется, если заголовок не содержит alg, выбирает none или требует неподдерживаемый асимметричный алгоритм.",
  "pageText.caeba6bd": "Срок истечения, начало действия и время выдачи должны быть конечными значениями NumericDate в секундах; допуск расхождения часов настраивается от нуля до 300 секунд.",
  "pageText.b69c111a": "Необязательная проверка issuer требует точного совпадения. Проверка audience принимает ожидаемое значение как строку aud либо элемент массива aud.",
  "pageText.45928def": "Утверждения авторизации, например роли и области доступа, отображаются, но зависят от приложения и не оцениваются этой страницей.",
  "pageText.9f727ee8": "Границы безопасности и совместимости",
  "pageText.79b6492c": "Рабочий валидатор должен независимо задавать разрешённый алгоритм, выбирать ключи из доверенной конфигурации издателя, применять все утверждения приложения, менять секреты и обрабатывать повторное использование или отзыв. Эта страница не расшифровывает JWE, не разрешает документы JWK/JWKS, не проверяет сертификаты и не воспроизводит сериализацию JSON отдельных библиотек. Создавайте рабочие токены только в доверенной системе идентификации, которой принадлежит ключ.",
  "pageText.269f9532": "Что такое HTML-сущности?",
  "pageText.1998740e": "HTML-сущности — специальные коды для отображения зарезервированных символов в HTML. Например, &lt; представляет <, а &amp; — &.",
  "pageText.b89e0526": "Зачем кодировать HTML-сущности?",
  "pageText.1529343a": "Кодирование зарезервированных символов может предотвратить трактовку текста как разметки в текстовом контексте HTML. Это не полная защита от XSS: атрибуты, URL, CSS, JavaScript и недоверенный HTML требуют контекстного экранирования или очистки.",
  "pageText.047ad07a": "Какие форматы сущностей инструмент декодирует?",
  "pageText.8c48f80f": "Он декодирует распознаваемые браузером именованные ссылки вроде &amp;, десятичные числовые ссылки вроде &#169; и шестнадцатеричные ссылки вроде &#xA9;.",
  "pageText.1f92ff4e": "Это то же, что конвертер HTML-сущностей?",
  "pageText.2bce97a1": "Да. Один инструмент кодирует и декодирует HTML-сущности, поэтому отдельного конвертера HTML-сущностей в Unicode нет. Включите расширенную настройку для вывода десятичных ссылок символов для не-ASCII текста; декодирование также разрешает шестнадцатеричные ссылки.",
  "pageText.787f2f9a": "Что делает декодировщик и кодировщик HTML-сущностей",
  "pageText.a65d3d26": "Ссылки на символы HTML представляют символы, которые иначе неоднозначны в разметке. Кодировщик заменяет зарезервированные символы: амперсанд, знаки меньше и больше, кавычку и апостроф. Расширенная настройка также создаёт десятичные ссылки для не-ASCII символов. Декодировщик разрешает именованные, десятичные и шестнадцатеричные ссылки с помощью HTML-парсера браузера.",
  "pageText.a4c17b02": "Примеры HTML-сущностей",
  "pageText.6b1cb488": "&lt; становится знаком меньше, а &gt; — знаком больше.",
  "pageText.656db619": "&amp; становится амперсандом, а &quot; — кавычкой.",
  "pageText.b1f980f4": "&#169; и &#xA9; — десятичная и шестнадцатеричная ссылки на знак авторского права.",
  "pageText.4a4bcadc": "Кодирование <p>Research & Development</p> создаёт текст, который отображается как символы разметки, а не разбирается как тот же элемент.",
  "pageText.761ca2d4": "Границы безопасности и отображения",
  "pageText.b3511bac": "Кодирование сущностей зависит от контекста. Экранирование текста для текстового узла HTML не делает это значение безопасным в обработчике событий, URL, объявлении CSS, строке JavaScript или произвольном фрагменте HTML. По умолчанию используйте экранирование фреймворка и поддерживаемый очиститель, если нужно сохранить доверенное форматирование. Декодирование недоверенных сущностей должно давать текст для анализа, а не повод внедрять результат через innerHTML.",
  "pageText.29803de0": "Что такое шестнадцатеричное кодирование?",
  "pageText.debeda5a": "Шестнадцатеричное кодирование представляет байты UTF-8 в системе с основанием 16 (0-9, A-F).",
  "pageText.e26f9f25": "Как использовать этот инструмент?",
  "pageText.0eb45c63": "Введите текст в поле ввода, и он автоматически преобразуется в шестнадцатеричный вид. Также можно вставить шестнадцатеричное представление и декодировать его обратно в текст.",
  "pageText.8d56b3f0": "Что такое двоичное кодирование?",
  "pageText.1fefb654": "Двоичное кодирование представляет байты UTF-8 в системе с основанием 2, используя только 0 и 1.",
  "pageText.e0fbf5c5": "Сколько бит приходится на символ?",
  "pageText.a3c61b13": "Каждый байт UTF-8 представлен 8 битами. Символы ASCII используют один байт, а символы вроде букв с диакритикой и эмодзи могут использовать несколько байтов.",
  "pageText.6f9da256": "Можно ли преобразовать двоичный код обратно в текст?",
  "pageText.6e36ed1b": "Да. Режим декодирования принимает полные восьмибитные байты с необязательными пробелами между группами и преобразует корректные байты UTF-8 обратно в текст.",
  "pageText.a76ed5ae": "Что делает двоичный кодировщик и декодировщик?",
  "pageText.208a45fa": "Инструмент преобразует текст в двоичное представление его байтов UTF-8 и декодирует байты обратно в текст. Каждая группа вывода содержит восемь бит. Пробелы между группами байтов улучшают читаемость; при декодировании их можно убрать или оставить. Преобразование выполняется кодом браузера, поэтому текст не требуется загружать на сервер.",
  "pageText.f49b8901": "Примеры преобразования текста в двоичный код",
  "pageText.3a3355ac": "Буква A — байт UTF-8 65, поэтому она становится 01000001. Символ é использует два байта UTF-8 C3 и A9, поэтому его двоичная форма — 11000011 10101001. Это важно: инструмент представляет кодированные байты, а не одно фиксированное восьмибитное значение для каждого видимого символа.",
  "pageText.0288b438": "Двоичное кодирование текста отличается от перевода десятичного числа в систему с основанием 2. Ввод текста 10 кодирует символы 1 и 0 как два байта UTF-8. Для числового преобразования используйте конвертер систем счисления.",
  "pageText.19833ccd": "Проверка преобразования двоичного кода в текст",
  "pageText.58060cff": "Декодирование игнорирует пробелы между группами, но требует только цифры 0 и 1 и целое число восьмибитных байтов. Неполные байты, другие символы или последовательности байтов, не соответствующие UTF-8, вызывают ошибку вместо вводящего в заблуждение частичного результата.",
  "pageText.49543137": "Двоичное кодирование — представление, а не шифрование или сжатие. Любой, у кого есть двоичные байты, может их декодировать; битовая строка может быть длиннее исходного видимого текста.",
  "pageText.c90dd9ea": "Что такое URI данных Base64?",
  "pageText.39ff7dd5": "URI данных встраивает содержимое файла прямо в HTML или CSS в форме data:image/png;base64,<encoded bytes>. Браузер декодирует его на месте, поэтому изображению не нужен отдельный HTTP-запрос.",
  "pageText.bae37a7c": "Когда использовать изображения Base64?",
  "pageText.4baed32c": "Для небольших значков, маленьких заглушек и однофайловых демонстраций. Большие изображения лучше подавать обычными файлами: Base64 увеличивает размер примерно на 33%, а встроенные изображения нельзя кешировать отдельно.",
  "pageText.fd65cb89": "Почему строка Base64 больше файла изображения?",
  "pageText.dc1302a7": "Base64 представляет каждые 3 байта 4 символами, поэтому результат примерно на треть больше файла. Инструмент показывает исходный размер и размер Base64, чтобы оценить целесообразность встраивания.",
  "pageText.44cee614": "Какие форматы изображений поддерживаются?",
  "pageText.690da2e0": "Любой файл, которому браузер назначает MIME-тип image/*, включая PNG, JPEG, GIF, WebP и SVG. Другие форматы, например AVIF или ICO, работают, если браузер сообщает тип изображения. Файлы без типа изображения отклоняются.",
  "pageText.4f220e7a": "Как преобразовать Base64 обратно в изображение?",
  "pageText.86d8a616": "Используйте инструмент Base64 в изображение либо в Node.js запишите байты на диск через fs.writeFileSync('image.png', Buffer.from(base64String, 'base64')).",
  "pageText.0472d6fa": "Моё изображение загружается на сервер?",
  "pageText.b951075e": "Нет. Файл читается через браузерный FileReader API и кодируется на вашем устройстве. Ничего не отправляется на сервер.",
  "pageText.8d3141eb": "URI данных и Base64 без префикса",
  "pageText.441f0d6b": "URI данных упаковывает MIME-тип и кодированные байты в одну строку, которую браузеры принимают везде, где ожидается URL, например data:image/png;base64,iVBORw0KGgo... Вариант Base64 убирает префикс data:image/png;base64, и возвращает только кодированные байты — то, что ожидают большинство JSON API, баз данных и эндпоинтов загрузки, если тип содержимого хранится отдельным полем. MIME-тип URI берётся из типа выбранного файла, сообщённого браузером.",
  "pageText.9c060b5e": "Встраивание результата",
  "pageText.92456569": "HTML: <img src=\"data:image/png;base64,...\" alt=\"Logo\" width=\"32\" height=\"32\">. Сохраняйте осмысленный alt и явные размеры, как для любого изображения.",
  "pageText.56968f15": "CSS: background-image: url(\"data:image/png;base64,...\"); с URI данных в кавычках.",
  "pageText.d617fb16": "JSON: храните строку Base64 без префикса рядом с полем contentType и декодируйте на сервере.",
  "pageText.693f282c": "Markdown: ![alt](data:image/png;base64,...) работает в некоторых обработчиках, но многие размещённые платформы блокируют URI данных в Markdown, поэтому проверяйте место отображения.",
  "pageText.f8d06727": "Когда изображения Base64 полезны и когда мешают",
  "pageText.1e364f5e": "Кодирование увеличивает данные примерно на 33%. Встроенное изображение также нельзя кешировать отдельно: оно скачивается заново при изменении содержащего его HTML или CSS и замедляет разбор этого файла. Встраивание оправдано для очень маленьких ресурсов: значков, заглушек 1×1 или самостоятельных демостраниц. Для фотографий и всего крупнее нескольких килобайт обычный файл изображения с заголовками кеширования обычно быстрее. Для SVG URI с URL-кодированием часто короче Base64; его создаёт инструмент SVG в URI данных CSS.",
  "pageText.e43aa790": "Что происходит с файлом",
  "pageText.c4f14710": "Файл кодируется точно как сохранён. Размер не меняется, повторного сжатия или удаления метаданных нет, поэтому EXIF в JPEG — сведения о камере или координаты GPS — переходят в строку Base64. Если это важно, сначала сожмите изображение или удалите метаданные. За раз преобразуется один файл; очень большие изображения дают очень длинные строки, которые могут замедлять прокрутку и копирование.",
  "pageText.49b261c7": "Что такое экранирование Unicode?",
  "pageText.80d28e8d": "Экранирование Unicode представляет символы шестнадцатеричными кодовыми точками, например \\u0041 для «A».",
  "pageText.6d708618": "Можно ли декодировать escape-последовательности Unicode онлайн?",
  "pageText.a4bd1758": "Да. Вставьте текст с поддерживаемыми последовательностями \\uXXXX, \\u{XXXXX} или \\xFF, выберите декодирование, и инструмент заменит их символами локально в браузере.",
  "pageText.cb96dafd": "Это то же, что снятие экранирования строк JSON?",
  "pageText.e061f024": "Нет. Инструмент предназначен для шестнадцатеричных Unicode- и байтовых escape-последовательностей. Используйте экранирование строк JSON, если нужно обработать \\n, \\t, экранированные кавычки или обратные косые черты как полный фрагмент строки JSON.",
  "pageText.b78ece8c": "Что делает декодировщик escape-последовательностей Unicode?",
  "pageText.66907eae": "Декодировщик превращает распознанные шестнадцатеричные escape-последовательности в читаемые символы. Он поддерживает четырёхзначные значения в стиле JavaScript, например \\u0041, кодовые точки в фигурных скобках, например \\u{1F600}, и двухзначные байтовые значения, например \\x41. Остальной текст остаётся без изменений, чтобы результат было удобно проверить перед копированием.",
  "pageText.8b33e053": "Примеры экранирования Unicode",
  "pageText.2a71ff3b": "При включённом экранировании ASCII буква A становится \\u0041. Символы за пределами основной многоязычной плоскости используют запись кодовой точки в фигурных скобках: 😀 становится \\u{1F600}. Без экранирования ASCII обычный ASCII-текст остаётся читаемым, а не-ASCII символы экранируются.",
  "pageText.f75a70a6": "Экранирование Unicode меняет запись символов, а не их смысл. Это полезно при анализе журналов, исходного кода, данных API или скопированного текста с escape-записью вместо отображённых символов.",
  "pageText.715d4ec7": "Декодирование Unicode в JavaScript и Python",
  "pageText.25c67af7": "Для полного строкового значения JSON используйте JSON.parse() в JavaScript или json.loads() в Python. Оба обрабатывают четырёхзначные escape-последовательности Unicode JSON и суррогатные пары. JSON не принимает последовательности JavaScript в фигурных скобках или \\xXX; онлайн-декодировщик поддерживает эти отдельные текстовые представления.",
  "pageText.dfad767c": "Примеры сохраняют буквальные обратные косые черты до запуска разбора и выводят Aé😀. Не используйте eval() для декодирования внешнего ввода. Документ JSON следует разбирать один раз по исходному формату вместо повторяющихся замен escape-последовательностей.",
  "pageText.b78d8193": "Escape-последовательности Unicode, JSON и безопасность",
  "pageText.ec7ecc8b": "Этот конвертер не является полным парсером языка программирования. Он заменяет поддерживаемые шестнадцатеричные шаблоны, но не интерпретирует все правила экранирования JSON, JavaScript, регулярных выражений или оболочки. Для точной проверки документа используйте парсер конкретного формата.",
  "pageText.d400aec2": "Кодирование не является шифрованием: экранированное значение может декодировать любой. Обработка выполняется кодом браузера, но не помещайте секреты в онлайн-утилиты, если среда выполнения не подходит для этих данных.",
  "pageText.06d6ceab": "Что делает экранирование строк JSON?",
  "pageText.a236a523": "Оно преобразует специальные символы — переводы строк, табуляцию и кавычки — в экранированные формы \\n, \\t и \\\".",
  "pageText.b5b32ac6": "Когда это полезно?",
  "pageText.9758a1c9": "Когда нужно безопасно встроить строки в данные JSON, конфигурационные файлы или запросы API.",
  "pageText.23c25e0a": "Поддерживает ли инструмент Base64 без префикса и URI данных?",
  "pageText.47a7ae5b": "Да. Можно вставлять строки Base64 без префикса (начинающиеся с iVBORw0KGgo... или /9j/...) или полные URI data:image/png;base64,...",
  "pageText.3e22ce2a": "Мои изображения загружаются на какой-либо сервер?",
  "pageText.ff8327d4": "Нет. Декодирование и отображение полностью выполняются в браузере через клиентские URL данных и blob.",
  "pageText.b5c81ec6": "В каком формате должен быть шестнадцатеричный ввод?",
  "pageText.4df53de7": "Любая шестнадцатеричная строка чётной длины (например, 48656c6c6f), с пробелами и префиксами или без них.",
  "pageText.0d4f669a": "Преобразование двустороннее?",
  "pageText.448de195": "Да! Можно преобразовывать HEX в Base64 и Base64 в HEX без потери данных.",
  "pageText.5a849fdb": "Для чего используется Base32?",
  "pageText.300b948f": "Base32 использует алфавит из 32 символов (A-Z, 2-7), нечувствительный к регистру и избегающий визуально похожих символов; часто применяется для секретных ключей 2FA TOTP и вводимых вручную кодов проверки.",
  "pageText.11274fca": "Что такое структурированные данные JSON-LD?",
  "pageText.930ded68": "JSON-LD — стандартный формат, рекомендованный Google для явных сведений о странице и классификации содержимого для расширенных результатов поиска.",
  "pageText.c2c8dd70": "Как добавить созданную схему на сайт?",
  "pageText.beba7ce9": "Скопируйте созданный тег <script type=\"application/ld+json\"> и вставьте его в секцию HTML <head> или <body>.",
  "pageText.86ec75d3": "Конфиденциальны и защищены ли мои данные?",
  "pageText.b25ac842": "Да, вся обработка выполняется локально в браузере без хранения на сервере.",
  "pageText.687b5867": "Что такое генератор UUID v7 с порядком по времени?",
  "pageText.c8e48ee7": "Создавайте UUID v7 с порядком по времени и криптографически стойкой случайностью браузера, экспортируйте их текстом. Связанный инструмент извлечения времени UUID v7 читает встроенное время создания идентификатора.",
  "pageText.611de2a2": "Что такое UUID?",
  "pageText.e747103f": "UUID (Universally Unique Identifier) — 128-битный идентификатор, рассчитанный на глобальную уникальность без центрального органа выдачи.",
  "pageText.5e3c112b": "Что такое UUID v4?",
  "pageText.7697e800": "UUID версии 4 создаётся случайно. Он содержит 122 случайных бита и 6 бит сведений о версии и варианте.",
  "pageText.5e39d294": "Что такое UUID v7?",
  "pageText.66a6ed70": "UUID версии 7 начинается с 48-битной временной метки Unix в миллисекундах и содержит ещё 74 бита случайных данных. Значения с возрастающими временными метками сортируются хронологически, но значения одной миллисекунды случайны, а перевод системных часов назад может обратить порядок генерации.",
  "pageText.7a44e8ee": "Выбрать UUID v4 или v7?",
  "pageText.83965de1": "Выберите v4 для непрозрачного случайного идентификатора. Выберите v7, если полезны группировка по времени и хронологическое индексирование базы. Ни одну версию не следует считать секретом.",
  "pageText.9a6b439e": "Сгенерированные UUID криптографически случайны?",
  "pageText.4a129bc3": "Браузерный криптографический API обеспечивает 122 случайных бита UUID v4 и 74 случайных бита данных UUID v7. UUID v7 также раскрывает миллисекунду создания, поэтому UUID — идентификаторы, а не пароли или токены.",
  "pageText.35cc78ac": "Что делает генератор UUID v4 и v7",
  "pageText.361a3991": "Генератор полностью в браузере создаёт UUID версии 4 или 7 по RFC 9562. Версия 4 использует 122 криптографически случайных бита. Версия 7 хранит текущую миллисекунду Unix в первых 48 битах и заполняет оставшиеся 74 бита данных через crypto.getRandomValues(). Обе устанавливают поля версии и варианта RFC и используют каноническую HEX-запись 8-4-4-4-12.",
  "pageText.cf240c55": "Создание UUID в JavaScript и Python",
  "pageText.6ef9489b": "JavaScript crypto.randomUUID() создаёт UUID v4 в безопасных контекстах браузера. Python uuid.uuid4() тоже создаёт v4; uuid.uuid7() доступен в стандартной библиотеке начиная с Python 3.14. Примеры ниже проверяют поддержку Python v7, а не предполагают её.",
  "pageText.42f8fbc7": "Разные генераторы UUID v7 могут по-разному упорядочивать ID внутри одной миллисекунды. Этот браузерный инструмент использует случайный хвост, а реализация Python — счётчик. Сохраняйте ограничение уникальности в базе данных и не используйте идентификатор как данные авторизации.",
  "pageText.3368e346": "Выбор v4 или v7",
  "pageText.5b192e0e": "Используйте UUID v4 для непрозрачного случайного идентификатора без времени. Используйте UUID v7, если записи должны группироваться хронологически по миллисекунде создания: это может улучшить локальность индекса по сравнению со случайными v4. Порядок следует закодированному времени часов: случайные хвосты одной миллисекунды не строго упорядочены, а перевод системных часов назад может обратить порядок генерации.",
  "pageText.19989f5d": "Пакетное форматирование и экспорт",
  "pageText.d012108b": "Создавайте от 1 до 1000 значений, переводите HEX-буквы в верхний регистр, удаляйте дефисы или заключайте значения в фигурные скобки для процессов с GUID. Копируйте результат с разделением по строкам или скачивайте тот же пакет как текстовый файл UTF-8.",
  "pageText.4c38dc5a": "Создавайте идентификаторы базы данных или приложения без координации центрального счётчика.",
  "pageText.ce17c126": "Заполняйте тестовые данные, ответы тестового API и образцы записей.",
  "pageText.138b9843": "Добавляйте ID корреляции к запросам, заданиям, журналам или сообщениям.",
  "pageText.5d4cb8de": "Готовьте небольшие пакеты для импорта, прототипов и локальной разработки.",
  "pageText.1193c111": "Примеры форматов",
  "pageText.d40026dd": "Результат v4 может выглядеть как 3f2504e0-4f89-41d3-9a0c-0305e82c3301, а v7 содержит 7 в тетраде версии, например 0190b0cc-4f71-7a8e-9c9a-6a74fbb21a92. Верхний регистр, отсутствие дефисов и скобки меняют только представление; последующим парсерам может требоваться каноническая строчная форма с дефисами.",
  "pageText.9dbfc526": "Уникальность UUID вероятностна: генератор не проверяет реестр и не гарантирует уникальность. UUID v7 раскрывает миллисекунду создания, предполагает отсутствие движения системных часов назад для сортировки по генерации, а случайные значения одной миллисекунды не строго монотонны. UUID — идентификатор, а не автоматически пароль, API-ключ или токен сеанса. Генерация локальна в браузере; всё скопированное, вставленное, скачанное, переданное или сохранённое обрабатывается выбранным вами местом назначения.",
  "pageText.7a6710aa": "Насколько надёжным должен быть пароль?",
  "pageText.9be86c1e": "Предпочитайте уникальный пароль, созданный и сохранённый менеджером паролей. Шестнадцать и более случайных символов из широкого набора или случайная парольная фраза из шести и более слов — практичная основа, если сервис её принимает; требования отдельных аккаунтов могут различаться.",
  "pageText.0f3affb1": "Как создаётся случайность?",
  "pageText.e7090e3e": "Генератор использует crypto.getRandomValues с выборкой отбрасыванием, а не Math.random. Режим случайных символов включает хотя бы один символ каждого выбранного набора, если длина позволяет, затем криптографически перемешивает результат.",
  "pageText.db182e45": "Созданные пароли загружаются или сохраняются?",
  "pageText.7daed653": "Нет. Генерация и оценка энтропии локальны, приложение не сохраняет созданное значение. Копирование может поместить его в историю буфера обмена ОС, расширения могут видеть содержимое страницы, а общие устройства требуют осторожности.",
  "pageText.8c8e3b19": "Как работает безопасная генерация паролей",
  "pageText.567ac86d": "Режим случайных символов выбирает из включённых наборов строчных, прописных букв, цифр и символов через криптографический генератор браузера. Выборка отбрасыванием избегает смещения по модулю. Режим парольных фраз независимо выбирает каждое слово из длинного списка EFF и поддерживает от шести до двенадцати слов с заданным разделителем.",
  "pageText.296f3bc2": "Выбор пароля или парольной фразы",
  "pageText.926afe7a": "Используйте уникальное значение для каждого аккаунта; повторное использование превращает одну утечку в доступ к нескольким сервисам.",
  "pageText.f3d81905": "Предпочитайте максимальную длину, надёжно поддерживаемую сервисом. Длина обычно полезнее предсказуемых замен вроде a на @.",
  "pageText.01bfc425": "Используйте парольную фразу для ручного ввода или чтения вслух, а случайные символы — если менеджер паролей хранит и подставляет пароль.",
  "pageText.27fbadfc": "Включайте многофакторную аутентификацию, где доступно, особенно для почты, финансовых, облачных и административных аккаунтов.",
  "pageText.1bede603": "Оценка энтропии и пределы конфиденциальности",
  "pageText.23ca65c7": "Показанная энтропия — теоретическая оценка по независимому равномерному выбору из выбранного набора или списка слов. Это не обещание времени взлома; она не учитывает компрометацию браузера, устройства, буфера обмена, менеджера паролей, сервиса или восстановления доступа. Генератор не проверяет пароли по базам утечек, поскольку для этого нужна отдельная схема поиска с защитой конфиденциальности.",
  "pageText.293386a3": "Что такое Lorem Ipsum?",
  "pageText.e7e9a310": "Lorem ipsum — похожий на латынь текст-заглушка для графического дизайна, веб-дизайна и издательского дела, заполняющий место до появления настоящего содержимого.",
  "pageText.fc868312": "Зачем использовать Lorem Ipsum?",
  "pageText.fc0c8095": "В нём естественно выглядящее сочетание коротких и длинных слов, которое показывает работу макета с реальным текстом, не отвлекая читателей смыслом.",
  "pageText.fc9ee235": "Что означает lorem ipsum?",
  "pageText.42643988": "В таком виде — ничего. Это перемешанный отрывок из «De finibus bonorum et malorum» Цицерона, где «dolorem ipsum» означает «сама боль». Слова обрезаны и изменены, поэтому «Lorem» не является настоящим латинским словом.",
  "pageText.864e8e98": "Какова длина созданного абзаца?",
  "pageText.da65818f": "В каждом абзаце от 3 до 7 предложений, в каждом предложении от 5 до 15 слов, поэтому абзац содержит примерно 15–105 слов. Для точного числа слов используйте режим слов.",
  "pageText.e4695071": "Можно ли создать lorem ipsum с HTML-тегами?",
  "pageText.a44e126f": "Результат — обычный текст с пустой строкой между абзацами. При вставке в HTML самостоятельно заключите каждый абзац в теги <p>.",
  "pageText.2fc5f8d2": "Откуда происходит lorem ipsum",
  "pageText.372fc06e": "Lorem ipsum происходит из «De finibus bonorum et malorum», трактата об этике Цицерона, написанного в 45 году до н. э. Знакомое начало Lorem ipsum dolor sit amet, consectetur adipiscing elit взято из отрывка, начинающегося Neque porro quisquam est qui dolorem ipsum quia dolor sit amet. Слова обрезали, изменили и переставили, поэтому результат выглядит как латынь, но ничего не значит. Наборщики и дизайнеры десятилетиями используют его варианты как заполнитель благодаря реалистичному ритму длины слов без содержательного смысла.",
  "pageText.50efd43e": "Как генератор строит текст",
  "pageText.78c6a4d6": "Слова случайно выбираются из фиксированного словаря lorem ipsum, поэтому каждое нажатие генерации даёт другой результат.",
  "pageText.cdfdd915": "Предложения содержат 5–15 слов, начинаются с прописной буквы и заканчиваются точкой.",
  "pageText.8a5faad3": "Абзацы содержат 3–7 предложений и разделяются пустой строкой.",
  "pageText.5b9b38b3": "При включённом начале «Lorem ipsum...» результат абзацев и предложений начинается с Lorem ipsum dolor sit amet, consectetur adipiscing elit., а результат слов — с Lorem ipsum.",
  "pageText.d069a303": "Режим слов возвращает точно запрошенное число слов через пробел без пунктуации.",
  "pageText.cfa7bbd6": "Под результатом показаны общие количества слов, символов, предложений и абзацев.",
  "pageText.5fc47ebf": "Правильное использование текста-заглушки",
  "pageText.3a4e06f6": "Lorem ipsum подходит для проверки длины строк, переносов и вертикального ритма, но скрывает проблемы, которые выявляет настоящий текст. Перед выпуском дизайна:",
  "pageText.039ee6ef": "Проверьте реалистичный текст, включая самый длинный ожидаемый заголовок, имя или название товара.",
  "pageText.d1b357c8": "Проверьте переводы: немецкий или финский текст часто длиннее английского, а китайский или японский переносится иначе.",
  "pageText.016f7d53": "Перед выпуском ищите lorem и ipsum в кодовой базе, чтобы заглушки не попали в рабочую версию.",
  "pageText.e449bc7c": "Не используйте lorem ipsum в alt и доступных именах: программы чтения с экрана произнесут его вслух.",
  "pageText.2baf95ba": "Для макетов с большим количеством данных, например таблиц пользователей или карточек товаров, создавайте реалистичные фиктивные записи генератором тестовых данных. Lorem ipsum не проверяет имена, числа, даты или длинные неразрывные строки вроде URL.",
  "pageText.7ef81d93": "Что такое QR-код?",
  "pageText.95dfb03e": "QR (Quick Response) — двумерный штрихкод, хранящий текст, например URL, карточку контакта или настройки Wi-Fi. Камеры телефонов и сканеры декодируют его и предлагают действие, например открыть ссылку.",
  "pageText.94540be7": "Какие данные можно кодировать?",
  "pageText.62ffa087": "Любой текст. Шаблоны заполняют стандартные форматы URL, электронной почты (mailto:), телефона (tel:), SMS (sms:), Wi-Fi (WIFI:) и контактов vCard, которые телефоны распознают и обрабатывают.",
  "pageText.a6c7c2f4": "У этих QR-кодов истекает срок действия?",
  "pageText.6544ed40": "Нет. Это статические коды: содержимое хранится в самом узоре без сервиса перенаправления, который можно отключить. Код URL работает столько же, сколько сам URL.",
  "pageText.d7525538": "Можно ли отслеживать сканирования или менять ссылку позднее?",
  "pageText.6fb75242": "Не в статическом коде. Чтобы менять адрес после печати, закодируйте короткий URL своего домена и обновляйте перенаправление там; тогда ваши журналы сервера смогут считать посещения.",
  "pageText.3b2f43fc": "Скачивать PNG или SVG?",
  "pageText.034404ba": "Используйте SVG для печати и дизайнов с изменением размера: он масштабируется без размытия. PNG подходит документам, слайдам и инструментам без поддержки SVG; для увеличения выберите размер 1024 px.",
  "pageText.229bdf99": "Как сделать QR-код Wi-Fi?",
  "pageText.072a9bd1": "Выберите шаблон WiFi и отредактируйте WIFI:T:WPA;S:MyNetwork;P:MyPassword;; — T означает тип защиты (WPA, WEP или nopass), S — имя сети, P — пароль. Экранируйте ; , : и \\ в имени или пароле обратной косой чертой.",
  "pageText.af7b54ae": "Статические QR-коды без срока действия",
  "pageText.e1f656b0": "Генератор создаёт статические QR-коды: содержимое кодируется прямо в узоре, и между сканированием и адресом нет посредника. Код работает, пока содержимое корректно, а сканирования не отслеживаются и не подсчитываются. Компромисс: напечатанный статический код нельзя редактировать. Чтобы сохранять возможность менять адрес, направьте код на свой URL и самостоятельно задавайте перенаправление.",
  "pageText.49c87d45": "Форматы данных шаблонов",
  "pageText.9e3fedef": "URL: https://example.com. Укажите схему, чтобы сканеры считали его ссылкой.",
  "pageText.dfb00b58": "Почта: mailto:hello@example.com. Добавьте ?subject=Hello для заполнения темы.",
  "pageText.bd51c65e": "Телефон: tel:+1234567890 в международном формате с кодом страны.",
  "pageText.9df90887": "SMS: sms:+1234567890?body=Hello. Поддержка заранее заполненного текста различается между телефонами.",
  "pageText.3f10e94f": "Wi-Fi: WIFI:T:WPA;S:MyNetwork;P:MyPassword;; подключает к сети без ввода пароля.",
  "pageText.fb848228": "vCard: блок BEGIN:VCARD ... END:VCARD с полями FN, TEL и EMAIL сохраняет контакт.",
  "pageText.0945d9b3": "Выбор коррекции ошибок и размера",
  "pageText.a73ec8ff": "Коррекция ошибок добавляет избыточность для чтения кода, когда часть загрязнена, повреждена или закрыта. Четыре уровня восстанавливают примерно 7% (L), 15% (M, по умолчанию), 25% (Q) или 30% (H) символа. Более высокие уровни и длинное содержимое делают код плотнее, с большим числом маленьких модулей, которым для надёжного сканирования нужен больший размер печати. Абсолютный максимум — 2953 байта на уровне L, но короткое содержимое сканируется намного надёжнее, поэтому сокращайте URL. Для экранов и чистой печати используйте M, для изнашиваемых этикеток — Q или H.",
  "pageText.d601415e": "Цвета, контраст и свободная зона",
  "pageText.21c831a0": "Сканеры ожидают тёмные модули на светлом фоне с сильным контрастом, поэтому избегайте бледного переднего плана и светлых кодов на тёмном фоне: некоторые сканеры их не читают. Созданное изображение имеет поле в 1 модуль; спецификация QR требует свободную зону в 4 модуля, поэтому оставьте дополнительное пустое место вокруг кода в насыщенном или цветном дизайне. Перед публикацией проверяйте окончательный печатный или экспортированный код несколькими телефонами.",
  "pageText.b744dab3": "Что такое слаг URL?",
  "pageText.24831d41": "Слаг URL — часть URL, которая обозначает конкретную страницу в читаемой форме. Например, в /blog/my-first-post слаг — «my-first-post».",
  "pageText.afaa82d8": "Почему слаги важны для SEO?",
  "pageText.a7281b59": "Удобные для SEO слаги помогают поисковым системам понять содержимое и улучшают кликабельность, показывая пользователю тему страницы.",
  "pageText.95ac698b": "Какие виды градиентов поддерживаются?",
  "pageText.1f3e5ff6": "Инструмент поддерживает линейные градиенты с настраиваемым углом и радиальные в форме круга или эллипса.",
  "pageText.6593c0c4": "Можно ли экспортировать градиент изображением?",
  "pageText.09d7598c": "Да! Помимо копирования CSS-кода можно скачать градиент как изображение PNG.",
  "pageText.be1336e0": "Что такое метатеги?",
  "pageText.406252f6": "Метатеги — элементы HTML, предоставляющие метаданные страницы. Они помогают поисковым системам понять содержимое и управляют представлением страницы в результатах поиска.",
  "pageText.a60cca39": "Что такое теги Open Graph?",
  "pageText.f806060d": "Теги Open Graph управляют видом содержимого при публикации в соцсетях, например Facebook, LinkedIn и других.",
  "pageText.3c5f494e": "Как работают несколько слоёв box-shadow?",
  "pageText.0f2afa64": "CSS box-shadow принимает определения теней через запятую. Ранние слои списка рисуются поверх последующих.",
  "pageText.a5cd6aad": "Что такое glassmorphism в CSS?",
  "pageText.00c0cd52": "Glassmorphism сочетает полупрозрачные цвета фона с backdrop-filter: blur() и тонкими светлыми границами для имитации матового стекла.",
  "pageText.b6a562cf": "Каковы 5 частей стандартного выражения cron?",
  "pageText.4cdd4865": "Стандартный cron состоит из 5 полей: минута (0–59), час (0–23), день месяца (1–31), месяц (1–12) и день недели (0–6, где 0 — воскресенье).",
  "pageText.f069ffbc": "Что означает */15 в cron?",
  "pageText.44fd98aa": "Шаг */15 в поле минут означает «каждые 15 минут», например в :00, :15, :30 и :45.",
  "pageText.adadf25c": "Какие виды тестовых данных можно создать?",
  "pageText.4b6a1433": "Можно создавать реалистичные фиктивные записи пользователей (имена, почта, телефоны, роли), товаров (SKU, цены, рейтинги), заказов (валюты, состояния), компаний и публикаций блога.",
  "pageText.a0f6807f": "Можно ли скачать созданные тестовые данные?",
  "pageText.5a2779c7": "Да, можно скопировать JSON прямо в буфер обмена или скачать файл .json одним нажатием.",
  "pageText.a82a3ba7": "Какие размеры создаются?",
  "pageText.6ab32280": "Инструмент создаёт PNG-значки 16×16 (обычная вкладка), 32×32 (вкладка Retina), 48×48 (ярлык компьютера), 180×180 (iOS Apple Touch), 192×192 (приложение Android) и 512×512 (заставка PWA).",
  "pageText.1a11e506": "Загруженные изображения отправляются на какой-либо сервер?",
  "pageText.631bc8d7": "Нет. Изменение размеров и отрисовка целиком выполняются в браузере через HTML5 Canvas. Изображения никогда не покидают компьютер.",
  "pageText.6016f5b9": "Какие шаблоны включает генератор .gitignore?",
  "pageText.9a2e6ae1": "Генератор включает стандартные правила для Node.js/TypeScript, Python, Go, Rust, Java/Gradle/Maven, React/Next.js/Vite, Vue/Nuxt, macOS (.DS_Store), Windows, Linux, VSCode и IDE JetBrains.",
  "pageText.26b1e47a": "Можно ли добавить свои шаблоны исключений?",
  "pageText.b9bb3e9f": "Да, можно писать собственные строки правил в редакторе; они автоматически объединятся с выбранными шаблонами платформ.",
  "pageText.99c478a9": "Как работают плавные фигуры CSS без SVG?",
  "pageText.330806ef": "Они используют синтаксис border-radius с 8 значениями (горизонтальные радиусы / вертикальные радиусы), создавая асимметричные плавные органические формы только на CSS.",
  "pageText.4f7db90d": "Можно ли скачать фигуру как масштабируемую векторную графику SVG?",
  "pageText.cd8236b5": "Да, можно скопировать исходную векторную разметку SVG или скачать фигуру отдельным файлом .svg.",
  "pageText.15c7f36d": "Поддерживает ли инструмент выравнивание столбцов слева, по центру и справа?",
  "pageText.1f6c30ea": "Да. Выравнивание каждого столбца (:---, :---:, ---:) можно менять отдельно кнопками над ним.",
  "pageText.17171603": "Можно ли динамически добавлять и удалять строки и столбцы?",
  "pageText.81d98d62": "Да, нажмите «+ Добавить столбец» или «+ Добавить строку» для расширения таблицы либо используйте значки корзины для удаления отдельных строк и столбцов.",
  "pageText.a3b7c9aa": "Зачем использовать заглушки SVG вместо внешних URL изображений-заглушек?",
  "pageText.36e2f853": "Заглушки SVG не требуют сетевых HTTP-запросов, мгновенно загружаются без интернета и представляют собой лёгкие (~300 байтов) URI данных, встроенные в HTML/CSS.",
  "pageText.98afe7f8": "Можно ли изменить текст подписи внутри изображения?",
  "pageText.7156e33f": "Да. Можно указать любой текст, например «Главный баннер» или «Аватар 128×128», либо оставить поле пустым для автоматического отображения размеров.",
  "pageText.0ddadffc": "Можно ли использовать ASCII-баннеры в GitHub README?",
  "pageText.fa3ae5eb": "Да. Заключите результат в блок кода Markdown (```) в README.md для моноширинного выравнивания во всех браузерах.",
  "pageText.92b39fd3": "Какие стили шрифта поддерживаются?",
  "pageText.d1c00c5d": "Классический ASCII (косые и вертикальные черты, подчёркивания) и современные сплошные блоки Unicode (█) для чёткого отображения.",
  "pageText.a19cad93": "Почему выбирать ULID или UUID v7 вместо UUID v4?",
  "pageText.f6c311f2": "В отличие от случайного UUID v4, ULID и UUID v7 начинаются с префикса времени в миллисекундах, предотвращая фрагментацию индексов B-Tree и значительно ускоряя INSERT в базу данных.",
  "pageText.dbf5188e": "Защищены ли созданные ULID от коллизий?",
  "pageText.e4c22fd6": "Да. Каждый ULID содержит 80 бит криптографической случайности помимо 48-битного времени, обеспечивая практически нулевую вероятность коллизии.",
  "pageText.434b3c01": "Как рассчитываются уровни оттенков?",
  "pageText.fef3b562": "Генератор меняет кривые светлоты HSL под стандартное распределение Tailwind CSS: от 50 при ~96% светлоты до 950 при ~6%.",
  "pageText.6fd82787": "Какие стили записи доступны?",
  "pageText.64f57bec": "Стандартные двоеточия (00:1A:2B:3C:4D:5E), дефисы (00-1A-2B-3C-4D-5E), точки Cisco (001a.2b3c.4d5e) и непрерывный HEX.",
  "pageText.0665d60c": "Зачем удалять данные EXIF?",
  "pageText.4514458b": "Фотографии смартфонов часто содержат точные координаты GPS и идентификаторы устройства, раскрывающие конфиденциальные сведения при открытой публикации.",
  "pageText.42405f57": "Снижает ли удаление EXIF качество изображения?",
  "pageText.4d60a474": "Нет, удаляются только теги метаданных, а пиксели изображения сохраняются.",
  "pageText.21ef5814": "Как проверить контрольную сумму скачанного файла?",
  "pageText.224c058f": "Выберите файл и вставьте полную ожидаемую контрольную сумму от издателя или другого доверенного независимого источника. Дождитесь завершения хеширования и проверьте результат совпадения.",
  "pageText.ae63ea0f": "Мой файл загружается на сервер?",
  "pageText.eebc3c64": "Выбранные файлы читаются локально в память браузера и не загружаются на сервер для расчёта. SHA-1, SHA-256, SHA-384 и SHA-512 используют Web Crypto, а MD5 и CRC32 — реализации JavaScript.",
  "pageText.0096052f": "Означает ли совпадение контрольной суммы безопасность или подлинность файла?",
  "pageText.85e0eb7f": "Совпадение означает соответствие вычисленной суммы ожидаемому значению. Оно не доказывает безвредность файла и не подтверждает подлинность издателя. Получайте ожидаемую сумму из доверенного независимого источника. MD5 и SHA-1 неустойчивы к коллизиям, а CRC32 не является криптографическим; для проверки целостности предпочитайте SHA-256.",
  "pageText.e7ddf90b": "Можно ли хешировать очень большие файлы в браузере?",
  "pageText.5a7687ac": "Выбранный файл полностью читается в память. Практический размер ограничен доступной памятью и производительностью устройства. Для больших загрузок используйте локальную терминальную утилиту контрольных сумм или пример Python с чтением частями из руководства проверки SHA-256.",
  "pageText.36576d77": "Воспроизведение сравнения контрольной суммы abc",
  "pageText.c0f11add": "Выберите «Загрузить пример abc», чтобы хешировать ровно три байта UTF-8 abc без пробелов и завершающего перевода строки. Также можно выбрать локальный текстовый файл, содержащий точно эти байты.",
  "pageText.45f16187": "Контрольная сумма SHA-256 — ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad. Вставьте полное значение в поле ожидаемой суммы для совпадения. Измените одну HEX-цифру, чтобы увидеть несовпадение после завершения хеширования.",
  "pageText.38407fa7": "Тот же ввод даёт MD5 900150983cd24fb0d6963f7d28e17f72 и CRC32 352441c2. Результаты также содержат SHA-1, SHA-384 и SHA-512. Перевод строки или другая кодировка меняет байты и их контрольные суммы.",
  "pageText.a8f9e0fa": "Что такое MD5?",
  "pageText.197bb98c": "MD5 (Message Digest 5) — криптографическая хеш-функция, создающая 128-битное (16-байтное) хеш-значение.",
  "pageText.380ae33f": "Безопасен ли MD5?",
  "pageText.200b2951": "MD5 больше не считается безопасным для криптографических задач, но полезен для контрольных сумм и применений, не критичных к безопасности.",
  "pageText.eb024fef": "Можно ли преобразовать хеш MD5 обратно в текст?",
  "pageText.f3a4be7f": "Нет. MD5 — односторонний хеш, а не обратимое шифрование. Сервисы «декодирования MD5» обычно угадывают вероятный ввод и сравнивают хеши; этот инструмент создаёт хеши и не выполняет обратный поиск.",
  "pageText.de23ad8f": "Что делает генератор хешей MD5?",
  "pageText.71308743": "Генератор превращает текст или выбранный файл в 128-битный хеш по RFC 1321 и отображает его 32 шестнадцатеричными символами. Текст преобразуется в байты UTF-8; режим файла хеширует его байты. Нижний и верхний регистр — варианты отображения одного хеша. Вычисление выполняется кодом браузера и не требует загрузки на сервер.",
  "pageText.e043d2b7": "Пример MD5 и контрольная сумма файла",
  "pageText.00f057ca": "Для ввода ровно трёх символов abc без кавычек, пробелов или завершающего перевода строки результат — 900150983cd24fb0d6963f7d28e17f72. RFC 1321 публикует этот тестовый вектор. Верхний регистр меняет лишь представление, а не биты хеша.",
  "pageText.294638f4": "Для контрольной суммы файла выберите файл и сравните все 32 HEX-символа с ожидаемым значением. Несовпадение доказывает отличие байтов файла от использованных для ожидаемого хеша. Совпадение помогает обнаружить случайные ошибки, но источник ожидаемого значения важен, а совпадение MD5 не доказывает отсутствие намеренной подмены.",
  "pageText.bd0d278c": "Можно ли расшифровать MD5 и когда его применять?",
  "pageText.0962ea5c": "Это генератор MD5, а не сервис расшифрования или обратного поиска. Хеширование не является шифрованием; хеш фиксированного размера не содержит обратимой копии ввода. Попытки обратить хеш обычно угадывают варианты ввода и хешируют каждый для сравнения.",
  "pageText.cf9f06aa": "RFC 6151 указывает, что MD5 больше неприемлем там, где нужна устойчивость к коллизиям, включая цифровые подписи. Не полагайтесь на MD5 для обнаружения умышленного изменения. RFC допускает контрольную сумму MD5 исключительно для защиты от ошибок, но приложение должно указать, какую услугу безопасности, если вообще какую-либо, оно от неё ожидает.",
  "pageText.953bfb55": "Вычисление в браузере уменьшает необходимость передачи текста или файлов для хеширования, но не делает MD5 криптографически безопасным. Не вводите пароли или другие секреты на онлайн-странице хеширования.",
  "pageText.101f9c75": "Что такое SHA256?",
  "pageText.16259758": "SHA256 (Secure Hash Algorithm 256-bit) — криптографическая хеш-функция, создающая 256-битное (32-байтное) хеш-значение.",
  "pageText.9afb2ad2": "Безопасен ли SHA256?",
  "pageText.0af6e6d2": "SHA-256 подходит многим задачам целостности, но хеш без ключа не подтверждает источник и не является функцией хеширования паролей. Для файлов используйте доверенную ожидаемую сумму, а для паролей — специально предназначенный хеш.",
  "pageText.c16f7e5d": "Как проверить контрольную сумму файла?",
  "pageText.14edcc5a": "Выберите файл и введите 64-символьное значение SHA-256 из доверенного независимого источника в поле ожидаемой суммы. Инструмент сообщит, совпадают ли созданный и ожидаемый хеши.",
  "pageText.7490e417": "Можно ли декодировать хеш SHA-256 обратно в текст?",
  "pageText.74338944": "Нет. Хеширование SHA-256 не является обратимым шифрованием, поэтому хеш нельзя декодировать для восстановления ввода. Инструмент создаёт и сравнивает значения SHA-256; он не взламывает пароли и не выполняет обратный поиск хешей.",
  "pageText.cd1de6c5": "Что делает генератор SHA-256?",
  "pageText.a17f5535": "Генератор вычисляет 256-битный хеш текста или выбранного файла по NIST FIPS 180-4 и отображает его 64 HEX-символами. В текстовом режиме браузер преобразует символы в байты UTF-8; в файловом — хеширует выбранные байты. Нижний и верхний регистр — варианты отображения одного значения.",
  "pageText.d7c2f3d3": "SHA-256 необратим: хеш нельзя декодировать в исходный текст или файл. Введите текст или выберите файл для создания хеша; сравните хеш файла с доверенной ожидаемой суммой для проверки.",
  "pageText.40dc4945": "Пример SHA-256 и проверка файла",
  "pageText.59582d9c": "Для ввода ровно трёх символов abc без кавычек, пробелов или завершающего перевода строки результат — ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad. Перевод строки, иной регистр или другая кодировка меняют байты и результат вычисления.",
  "pageText.af255369": "Чтобы проверить файл, создайте его SHA-256 и введите ожидаемый 64-символьный хеш из доверенного источника. Сравнение сообщает совпадение или несовпадение. Несовпадение доказывает отличие байтов от использованных для ожидаемого хеша. Совпадение подтверждает сравнение, но источник ожидаемого значения всё ещё важен.",
  "pageText.57ea438c": "Расчёт SHA-256 в JavaScript и Python",
  "pageText.2f2bbf6b": "Функция Web Crypto digest в JavaScript работает с байтами. Используйте TextEncoder для текста UTF-8 или arrayBuffer() файла для точного содержимого. Пример хеширует abc обоими способами и выводит одинаковый хеш. Браузерный digest() требует безопасного контекста и читает ввод в память.",
  "pageText.a0a974f1": "Python hashlib может постепенно обновлять хеш. Файловый пример читает существующий download.zip в двоичном режиме частями по одному мегабайту. Замените путь своим файлом и сравните полный хеш с доверенным ожидаемым значением.",
  "pageText.5379ecfa": "Можно ли расшифровать SHA-256 и что он доказывает?",
  "pageText.43df41c5": "Это генератор SHA-256, а не сервис расшифрования или обратного поиска. Хеш сжимает ввод в фиксированный 256-битный результат; это не зашифрованная или без потерь копия для декодирования в оригинал. Поиск вероятного оригинала означает угадывание вариантов и их хеширование для сравнения.",
  "pageText.139d7ac4": "FIPS 180-4 определяет SHA-256 как безопасный хеш-алгоритм и описывает хеши как компоненты цифровых подписей и аутентификации сообщений с ключом. Этот генератор без ключа не подписывает данные, не подтверждает отправителя и не шифрует содержимое. Не считайте хеш рядом с недоверенным файлом независимым доказательством происхождения.",
  "pageText.a06060d1": "Хеширование текста и файлов выполняется кодом браузера без загрузки на сервер для расчёта. Эта конфиденциальность не делает хеш шифрованием; избегайте секретов в онлайн-утилитах, если среда выполнения не подходит для ваших данных.",
  "pageText.51a1b9be": "Что такое SHA512?",
  "pageText.84a4301e": "SHA512 (Secure Hash Algorithm 512-bit) — криптографическая хеш-функция, создающая 512-битное (64-байтное) значение, обычно отображаемое 128-значным шестнадцатеричным числом.",
  "pageText.790c6ec3": "Безопасен ли SHA512?",
  "pageText.6d855b6b": "Да, SHA512 сейчас считается очень надёжным для криптографических задач и рекомендуется для большинства применений.",
  "pageText.815e4dcd": "Что такое HMAC?",
  "pageText.ff3b2cf9": "HMAC — код аутентификации сообщения с ключом, сочетающий криптографическую хеш-функцию и общий секрет для проверки целостности и подлинности сообщения.",
  "pageText.09e2e0ba": "Является ли HMAC шифрованием?",
  "pageText.abec3974": "Нет. HMAC не скрывает сообщение. Он позволяет сторонам с общим секретом обнаруживать изменения и подтверждать источник сообщения.",
  "pageText.3c4deb2f": "Какие алгоритмы и форматы результата поддерживаются?",
  "pageText.b389a303": "Инструмент поддерживает HMAC с SHA-256, SHA-384 или SHA-512 и показывает или проверяет подписи в HEX либо стандартном Base64.",
  "pageText.8f405a3a": "Создание и проверка подписей HMAC",
  "pageText.b25fc0c3": "Введите точные байты сообщения, представленные текстом, общий секрет, ожидаемый вариант SHA-2 и кодировку подписи. Генерация создаёт подпись; проверка пересчитывает её с теми же данными и сравнивает декодированные байты. Иной перевод строки, кодировка, секрет, алгоритм или кодировка результата меняют результат.",
  "pageText.422f4458": "Типичные применения вебхуков и API",
  "pageText.f0d6dd20": "Воспроизвести подпись вебхука при отладке интеграции.",
  "pageText.d0483022": "Сравнить локально вычисленный HMAC с подписью доверенного отправителя.",
  "pageText.44fd46de": "Преобразовать одни байты HMAC между HEX и Base64.",
  "pageText.2cfc6b71": "Убедиться, что изменение сообщения приводит к ошибке проверки подписи.",
  "pageText.843858f3": "Границы безопасности",
  "pageText.ab6a34ae": "HMAC требует стойкого общего секрета, безопасно переданного и сохранённого. Браузерный инструмент полезен для тестовых данных, но рабочие секреты должны оставаться в контролируемых средах приложения. HMAC аутентифицирует данные, не шифрует их и не является схемой хранения паролей. Проверка подписи делегируется Web Crypto API браузера вместо сравнения байтов подписи в JavaScript приложения.",
  "pageText.cb69e8df": "Что такое PKCE?",
  "pageText.abc745c5": "PKCE — расширение OAuth, связывающее запрос авторизации с секретным code verifier у клиента и уменьшающее риск перехвата кода авторизации.",
  "pageText.bb3fb7f1": "Какой метод challenge использует инструмент?",
  "pageText.334f8104": "S256: SHA-256 от code verifier, кодированный как Base64url без заполнения. Метод plain намеренно не создаётся.",
  "pageText.c069d885": "Можно ли использовать созданное значение в рабочей среде?",
  "pageText.ddc8fb76": "Значения используют криптографическую случайность браузера и допустимые символы PKCE, но рабочие verifier следует создавать и сохранять внутри OAuth-клиента, который завершит обмен токеном.",
  "pageText.4c2764af": "Как создаётся пара PKCE S256",
  "pageText.71336ec6": "Клиент PKCE создаёт высокоэнтропийный code verifier, хеширует его точное ASCII-значение через SHA-256 и отправляет Base64url без заполнения как code challenge. Запрос авторизации содержит code_challenge и code_challenge_method=S256. Последующий запрос токена отправляет исходный code_verifier, чтобы сервер авторизации получил и сравнил тот же challenge.",
  "pageText.3d8fba00": "Правила verifier и проверка",
  "pageText.2aa00a1d": "Генерация создаёт 43–128 символов из незарезервированного набора RFC 7636 с помощью криптографически случайных байтов и выборки отбрасыванием.",
  "pageText.9cb7c772": "Получение challenge принимает существующий verifier, только если всё значение соответствует правилам длины и символов.",
  "pageText.ae7f5d42": "Проверка снова получает S256 и сравнивает его с точным 43-символьным challenge Base64url.",
  "pageText.587e6e12": "Пробелы значимы. Точно копируйте verifier и храните его только для соответствующего процесса авторизации.",
  "pageText.1fadc2f8": "PKCE защищает код авторизации от обмена без соответствующего verifier; он не заменяет проверку redirect URI, OAuth state или OIDC nonce, TLS, безопасное хранение токенов или проверку сервером авторизации. Генерация и хеширование локальны в браузере, но история буфера обмена, расширения, журналы и общие устройства всё ещё могут раскрыть скопированные значения.",
  "pageText.cc61fb43": "Почему один пароль каждый раз даёт другой хеш?",
  "pageText.47fdbb41": "Bcrypt создаёт новую случайную соль для каждого хеша и хранит соль и стоимость в кодированном результате. Поэтому разные хеши проверяют один пароль без отдельного столбца соли.",
  "pageText.fd8efc8a": "Чем управляет стоимость bcrypt?",
  "pageText.e24b8eb9": "Стоимость — коэффициент работы с основанием два. Увеличение на единицу примерно удваивает работу хеширования. Выбирайте рабочую стоимость по измерениям своей инфраструктуры аутентификации, а не по времени в браузере.",
  "pageText.c5646e46": "Почему пароли длиннее 72 байтов UTF-8 отклоняются?",
  "pageText.35d8cc67": "Bcrypt обрабатывает только первые 72 байта. Отклонение более длинного ввода предотвращает незаметную трактовку двух видимо разных паролей как одной обрезанной последовательности байтов.",
  "pageText.a3c91e25": "Что делают генератор и проверка bcrypt",
  "pageText.523e4066": "Генерация создаёт случайную соль, применяет bcrypt с выбранной стоимостью и возвращает стандартную модульную строку хеша с версией, стоимостью, солью и контрольной суммой. Проверка читает параметры существующего хеша и снова выполняет bcrypt, затем сообщает, совпадает ли тестовый пароль. Bcrypt намеренно медленен в отличие от быстрых контрольных хешей MD5 или SHA-256.",
  "pageText.52fbc8aa": "Стоимость, соль и предел 72 байта",
  "pageText.a94e797a": "Интерфейс предлагает безопасные для браузера стоимости от 8 до 14; высокие значения заметно дольше работают на медленных устройствах.",
  "pageText.3541abdb": "Каждый созданный хеш использует новую криптографически случайную соль, поэтому повторная генерация не должна давать одинаковые строки.",
  "pageText.8bd98451": "Хранить следует полную кодированную строку хеша. Соль и стоимость уже встроены и автоматически используются при проверке.",
  "pageText.107d624e": "Инструмент считает байты UTF-8, а не символы JavaScript, и отклоняет значения сверх предела bcrypt в 72 байта.",
  "pageText.4b0c23bf": "Границы безопасного применения",
  "pageText.e9f75848": "Используйте страницу с синтетическими данными разработки или QA. Рабочее хеширование паролей должно происходить в доверенном серверном процессе аутентификации с ограничением запросов, защищённой передачей, мониторингом утечек и документированной стратегией обновления. Успешное сравнение доказывает лишь соответствие одного пароля одному хешу; оно не оценивает стойкость пароля, безопасность аккаунта или пригодность стоимости для серверов.",
  "pageText.10893cde": "Локальная обработка и совместимость",
  "pageText.0f1e91b6": "Реализация bcrypt загружается только после начала операции, а хеширование или сравнение выполняется в браузере. Проверка принимает стандартные $2a$, $2b$ и $2y$ в пределах стоимости. Менеджеры буфера обмена, расширения, демонстрация экрана или уже взломанное устройство всё ещё могут раскрывать значения; не вставляйте реальные учётные данные пользователей.",
  "pageText.dfdb1834": "Доказывает ли декодирование доверие к сертификату?",
  "pageText.54a44265": "Нет. Разбор показывает кодированные поля и может проверить сертификат его собственным открытым ключом. Доверие также требует корректной цепочки к принятому корню, проверки назначения и имён, политики, времени и часто сведений об отзыве или прозрачности.",
  "pageText.5cbb68de": "Можно ли вставить полную цепочку сертификатов PEM?",
  "pageText.99a5e254": "Да. Инструмент извлекает и декодирует до десяти блоков CERTIFICATE в порядке ввода. Он не меняет их порядок и не доказывает, что каждый сертификат подписал следующий.",
  "pageText.00fb6a40": "Принимаются ли закрытые ключи?",
  "pageText.339287f5": "Нет. Принимаются блоки PEM CERTIFICATE или DER-сертификаты в Base64. Текст закрытого ключа и запроса сертификата отклоняется; не вставляйте закрытые ключи в браузерные инструменты.",
  "pageText.eac22252": "Поля, извлекаемые из сертификата X.509",
  "pageText.27c40514": "Декодировщик читает ASN.1 DER непосредственно в Base64 или внутри границ PEM по RFC 7468. Он сообщает отличительные имена субъекта и издателя, серийный номер, даты not-before и not-after, алгоритмы подписи и открытого ключа, поддерживаемые альтернативные имена, OID расширений, размер в байтах и хеш SHA-256 точных байтов сертификата.",
  "pageText.6739d969": "Срок действия и собственная подпись — узкие проверки",
  "pageText.020adbca": "«Сейчас действителен» означает, что часы браузера между notBefore и notAfter; это не устанавливает доверие или назначение.",
  "pageText.d1665ea2": "Самоизданный означает совпадение имён субъекта и издателя; криптографически самоподписанный также требует проверки подписи открытым ключом сертификата.",
  "pageText.75c63764": "Неподдерживаемая криптография браузера может оставить результат собственной подписи неизвестным, даже если структура сертификата декодируется.",
  "pageText.7a7b0159": "Отпечаток SHA-256 определяет точные байты DER для сравнения; признаком доверия он становится только при получении по независимому доверенному каналу.",
  "pageText.087c5028": "Проверки, остающиеся задачей валидатора TLS или PKI",
  "pageText.08a73601": "Страница не строит цепочку к корням ОС или браузера, не получает промежуточные сертификаты, не проверяет назначение ключа или политику для конкретной цели, не сопоставляет имя хоста, не запрашивает OCSP/CRL, не изучает журналы Certificate Transparency и не подключается к серверу. Эти решения требуют хранилища доверия, контекста соединения и политики реального клиента.",
  "pageText.314bab46": "Что такое BIP-39?",
  "pageText.9fba1f54": "BIP-39 (Bitcoin Improvement Proposal 39) описывает мнемоническое предложение — группу легко запоминаемых слов — для создания детерминированных криптокошельков.",
  "pageText.bc10db69": "Безопасно ли создавать здесь мнемонические фразы?",
  "pageText.6f73837c": "Генерация и расчёт энтропии используют window.crypto.getRandomValues() и полностью выполняются локально в браузере. Мнемонические фразы никогда не передаются по сети.",
  "pageText.6d97a1a7": "Закрытые ключи отправляются на ваш сервер?",
  "pageText.791c3f3c": "Нет. Пары ключей создаются через window.crypto.subtle прямо на вашем устройстве. Закрытые ключи никогда не покидают браузер.",
  "pageText.4cc18af6": "В каком формате экспортируются ключи?",
  "pageText.26a068ea": "Открытые ключи экспортируются в SPKI PEM (-----BEGIN PUBLIC KEY-----), закрытые — в PKCS#8 PEM (-----BEGIN PRIVATE KEY-----).",
  "pageText.14b643ed": "Какой алгоритм рекомендуется для .htpasswd в рабочей среде?",
  "pageText.e63436c8": "Bcrypt ($2y$) настоятельно рекомендуется для рабочей среды, обеспечивая надёжную защиту от полного перебора и словарных атак.",
  "pageText.438a3aaa": "Пароль в открытом виде отправляется на какой-либо сервер?",
  "pageText.71f70564": "Нет. Хеширование полностью выполняется локально в браузере через Web Crypto API. Пароли никогда не попадают на сервер.",
  "pageText.c83dd430": "Как работает одноразовый пароль на основе времени TOTP?",
  "pageText.682b1360": "TOTP (RFC 6238) рассчитывает шестизначный код проверки через подпись HMAC-SHA1 с общим секретом Base32 и текущим 30-секундным интервалом времени Unix.",
  "pageText.2c69c124": "Совместимо ли это с Google Authenticator, Authy и 1Password?",
  "pageText.9e7b7687": "Да, созданные секретные ключи и URI otpauth:// следуют открытому стандарту, поддерживаемому Google Authenticator, Microsoft Authenticator, 1Password и Bitwarden.",
  "pageText.84c27538": "Безопасно ли проверять здесь пароли?",
  "pageText.004d56b7": "Да. Вся криптографическая проверка полностью выполняется локально в браузере. Пароли в открытом виде и хеши никогда не передаются на сервер.",
  "pageText.a32149fa": "Какие версии Bcrypt поддерживаются?",
  "pageText.c4c394d4": "Поддерживаются стандартные строки Bcrypt Modular Crypt Format с префиксами $2a$, $2b$ и $2y$ и любым коэффициентом стоимости от 4 до 31.",
  "pageText.78492a05": "Какие алгоритмы подписи HMAC поддерживаются?",
  "pageText.3bff48a8": "Поддерживаются HS256 (HMAC-SHA256), HS384 (HMAC-SHA384) и HS512 (HMAC-SHA512) через встроенный Web Cryptography API браузера.",
  "pageText.59a40ee3": "Защищены ли мои секреты для подписи?",
  "pageText.e7d3f45b": "Да! Вся криптографическая генерация подписей полностью выполняется локально в браузере. Секреты и данные полезной нагрузки никогда не отправляются на сервер.",
  "pageText.546b483c": "Что такое энтропия пароля?",
  "pageText.843a4831": "Энтропия пароля — математическая мера непредсказуемой информации в битах на основе размера набора символов и длины пароля.",
  "pageText.090cc30f": "Безопасно ли вводить здесь пароль?",
  "pageText.d27c1402": "Да. Анализ полностью вычисляется локально в браузере на JavaScript и никогда не передаётся через интернет.",
  "pageText.842979bb": "Что такое regex?",
  "pageText.bf8dc030": "Регулярные выражения (regex) — шаблоны сопоставления сочетаний символов в строках. Они используются для поиска, замены и проверки текста.",
  "pageText.aa2308ec": "Какой диалект regex поддерживается?",
  "pageText.e2719d0a": "Тестер использует JavaScript RegExp и поддерживает синтаксис ECMAScript и флаги, доступные в браузере. Некорректные шаблоны отображаются как ошибки синтаксиса.",
  "pageText.b74b7f86": "Какие флаги regex можно проверить?",
  "pageText.cf4c1cc1": "Можно проверять стандартные флаги JavaScript, поддерживаемые браузером, включая глобальный, без учёта регистра, многострочный, dotAll, Unicode и sticky.",
  "pageText.7f047dab": "Что делает тестер регулярных выражений JavaScript",
  "pageText.dc90d609": "Тестер компилирует шаблон и флаги через JavaScript RegExp браузера, применяет к тексту, выделяет каждое совпадение и сообщает начальный индекс и группы захвата. Введите исходный шаблон без окружающих косых черт. Добавьте g для всех совпадений; без него JavaScript возвращает только первое. По числу и индексам совпадений проверяйте ожидаемые места повторного поиска.",
  "pageText.abd7f336": "Типичные применения",
  "pageText.9dc106a2": "Создать прототип правил проверки идентификаторов, дат, строк журнала или другого ограниченного текста.",
  "pageText.1d045840": "Извлечь повторяющиеся значения, похожие на адреса почты, номера заявок или именованные поля.",
  "pageText.6220ec6f": "Сравнить поведение с учётом и без учёта регистра через i или якоря строк через m.",
  "pageText.f40aadec": "Изучить группы захвата перед переносом шаблона в JavaScript или TypeScript.",
  "pageText.1908e453": "Разобранный пример",
  "pageText.d2821f39": "Шаблон: \\b([A-Za-z0-9._%+-]+)@([A-Za-z0-9.-]+\\.[A-Za-z]{2,})\\b. Флаги: gi. Текст: \"Contact Ada at ada@example.com or SUPPORT@EXAMPLE.ORG.\" Результат — два выделенных совпадения. Группа 1 содержит локальную часть каждого адреса, группа 2 — домен. Флаг g продолжает после первого совпадения, а i игнорирует регистр букв.",
  "pageText.d1106dba": "Инструмент следует синтаксису регулярных выражений ECMAScript, доступному в текущем браузере; конструкции PCRE, Python, .NET и Java могут не работать или вести себя иначе. Успешное совпадение доказывает лишь соответствие шаблону, а не семантическую корректность адреса почты, URL, даты или другого значения. Неоднозначные вложенные квантификаторы могут вызывать дорогие возвраты на длинном вводе. Шаблон и тестовый текст остаются в браузере; избегайте конфиденциальных рабочих данных на общих устройствах.",
  "pageText.17c97676": "Зачем экранировать символы regex?",
  "pageText.c7a9a784": "Символы ., *, +, ?, (, ), [, ], {, }, ^, $, | и обратная косая черта имеют структурный смысл в регулярных выражениях. Обратная косая черта перед ними заставляет созданный фрагмент сопоставлять их буквально.",
  "pageText.b46e6b9b": "Когда следует использовать инструмент?",
  "pageText.bbf26d2d": "Перед вставкой доверенного или недоверенного буквального текста в более крупное регулярное выражение JavaScript. Экранирование предотвращает изменение структуры шаблона вставленным текстом, но окружающее выражение всё ещё может быть неэффективным или неверным.",
  "pageText.6df59a98": "Интерпретирует ли снятие экранирования \\n или \\d?",
  "pageText.9a3e444a": "Нет. Оно обращает только экранирование метасимволов и косой черты, созданное этим инструментом. Токены regex и строковые escape-последовательности с возможным иным смыслом намеренно сохраняются.",
  "pageText.f457f978": "Что создаёт экранирование Regex",
  "pageText.6ac46463": "Операция ставит обратную косую черту перед метасимволами регулярных выражений JavaScript и экранирует / для удобного использования в литерале /pattern/. Например, price (USD) + tax? становится price \\(USD\\) \\+ tax\\?. Результат — фрагмент шаблона; флаги, якоря, группы захвата и окружающее выражение остаются вашей задачей.",
  "pageText.00aef4ad": "Границы безопасности динамических шаблонов",
  "pageText.dcb7c0ee": "Экранируйте только буквальную часть. Не экранируйте намеренно добавляемые вокруг операторы ^, $ или группу захвата.",
  "pageText.3f76d13b": "Экранирование предотвращает внедрение синтаксиса regex из фрагмента, но не катастрофические возвраты, созданные в других частях конечного шаблона.",
  "pageText.c4d0eb41": "Синтаксис JavaScript RegExp отличается от PCRE, Python, .NET, Java и других движков; проверяйте конечный шаблон в той же среде, где он будет выполняться.",
  "pageText.8dd960d4": "Если шаблон помещается в строку JavaScript, экранирование строки исходного кода — отдельный дополнительный слой.",
  "pageText.90550320": "Снятие экранирования и ограничения конфиденциальности",
  "pageText.ccd0ec75": "Снятие экранирования намеренно осторожно: оно удаляет обратную косую черту только перед пунктуацией, обработанной операцией экранирования. Оно не разбирает полное регулярное выражение и не превращает \\d, \\b, \\n или Unicode-последовательности в текст. Обработка остаётся в браузере, а буфер обмена и дальнейшее использование кода — вне инструмента.",
  "pageText.a0a4fe42": "Как работает сравнение текста?",
  "pageText.e1159d8d": "Оно построчно сравнивает два ввода, отмечает добавления, удаления и изменённые строки, затем выделяет меньшие изменения внутри изменённых строк.",
  "pageText.e5a7ece5": "Можно ли сравнивать код?",
  "pageText.4f90c315": "Да. Вставьте код, конфигурацию или обычный текст в два редактора. Используйте игнорирование пробелов или регистра, если эти различия не важны.",
  "pageText.74bef405": "Можно ли сравнить два файла?",
  "pageText.c6806514": "Откройте каждый файл в редакторе, скопируйте содержимое и вставьте в панели оригинала и изменённого текста. Сравнение работает с текстом, поэтому подходит любой текстовый формат: JSON, YAML, CSV и исходный код.",
  "pageText.e1647322": "Игнорирование пробелов также игнорирует пустые строки?",
  "pageText.88417b29": "Нет. Оно сжимает последовательности пробелов и табуляций и обрезает края каждой строки перед сравнением, поэтому отступы и конечные пробелы не считаются изменениями, но добавленная или удалённая пустая строка всё ещё отмечается.",
  "pageText.80c2c0e8": "Чем это отличается от git diff?",
  "pageText.612015ce": "Оба находят максимальный общий набор неизменённых строк. Этот инструмент также объединяет похожие удалённые и добавленные строки в изменения и выделяет точные изменённые символы, что удобнее для коротких правок. Для коммитов и патчей git diff остаётся источником истины.",
  "pageText.083d5e45": "Мой текст загружается на сервер?",
  "pageText.5e441495": "Нет. Сравнение выполняется в браузере, ни один ввод не отправляется на сервер.",
  "pageText.8ab4cd08": "Сравнение двух строк или длинных документов",
  "pageText.19e9243c": "Вставьте исходный текст слева, изменённый справа; сравнение обновляется при редактировании любого ввода. Раздельный вид ставит соответствующие строки рядом и прокручивает панели вместе. Объединённый вид даёт непрерывное сравнение: после каждой удалённой строки идёт замена. Если ввод вставлен в неверном порядке, кнопка обмена меняет его местами.",
  "pageText.06dc44b8": "Как обнаруживаются изменения",
  "pageText.40ccc1ca": "Сначала инструмент находит максимальную общую подпоследовательность строк и отмечает каждую как неизменённую, добавленную или удалённую. В каждом блоке изменений достаточно похожие удалённые и добавленные строки объединяются в изменённые, чтобы правка выглядела как одно изменение, а не удаление плюс вставка. Затем они сравниваются подробно: строки короче 80 символов — посимвольно, длинные — по словам, если не включено принудительное посимвольное сравнение. Сводка считает добавления, удаления, изменения и неизменённые строки.",
  "pageText.3ba03012": "Параметры для сравнения с лишними различиями",
  "pageText.fa1650de": "Игнорирование пробелов сжимает пробелы и табуляции и обрезает края строк, поэтому новые отступы и конечные пробелы не считаются изменениями. Оно не считает a b и ab одинаковыми.",
  "pageText.40e7b499": "Игнорирование регистра сравнивает строки без учёта буквенного регистра, что полезно для ключевых слов SQL или имён переменных окружения.",
  "pageText.6c540dae": "«Только изменения» скрывает неизменённые строки, а переносы сохраняют читаемость длинных строк без горизонтальной прокрутки.",
  "pageText.15884c41": "Текст из файлов Windows может содержать возврат каретки в конце каждой строки. Если внешне одинаковые строки считаются изменёнными, включите игнорирование пробелов.",
  "pageText.4010b374": "Просмотр и передача различий",
  "pageText.796a0a49": "Копирование различий даёт обычный текст: неизменённые строки начинаются с двух пробелов, удалённые — с -, добавленные — с +.",
  "pageText.97594ef5": "Копирование следует текущему виду, поэтому при «Только изменения» копируются лишь изменённые строки.",
  "pageText.314e11fa": "Различия, скрытые игнорированием регистра или пробелов, не включаются, поэтому проверьте настройки перед передачей результата.",
  "pageText.5b3a3d4f": "Что такое Markdown?",
  "pageText.d5d009f0": "Markdown — компактный язык разметки для создания форматированного текста в обычном редакторе. Он широко используется для документации, файлов README и написания содержимого.",
  "pageText.bde3ab4d": "Можно ли экспортировать HTML?",
  "pageText.ed93a679": "Да. Можно скопировать очищенный фрагмент или скачать самостоятельный HTML-документ с базовыми адаптивными стилями. Проверьте разметку и ссылки перед публикацией в другом контексте безопасности.",
  "pageText.0098beeb": "Безопасен ли предпросмотр исходного HTML в Markdown?",
  "pageText.1737e56a": "Результат очищается DOMPurify. Скрипты, формы, iframe, атрибуты стиля и другие рискованные элементы удаляются. Изображения по ссылкам заблокированы по умолчанию; их включение может связаться с хостами, а переход по ссылке всё равно обращается к адресу назначения.",
  "pageText.bee7691f": "Что поддерживает предпросмотр Markdown",
  "pageText.441669ae": "Обработчик использует GitHub Flavored Markdown с поддержкой явных переносов строк. Заголовки, выделения, ссылки, изображения, нумерованные и ненумерованные списки, задачи, таблицы, цитаты, встроенный код, блоки кода, зачёркивание и горизонтальные линии показываются при вводе. Вид HTML показывает созданный очищенный фрагмент вместо выполнения Markdown как кода.",
  "pageText.03de3ac0": "Очистка и границы публикации",
  "pageText.a8213d5f": "DOMPurify удаляет скрипты, формы, фреймы, встроенные объекты, элементы и атрибуты стиля и другую запрещённую разметку до предпросмотра или экспорта.",
  "pageText.1e94d374": "Очистка зависит от контекста. Повторно очистите или безопасно отобразите результат, если другое приложение меняет его, объединяет с шаблонами или помещает вне HTML-контекста.",
  "pageText.c384685e": "Подсветка синтаксиса не применяется; метки языка блоков кода сохраняются лишь как подсказки разметки.",
  "pageText.7f8e5143": "Изображения по ссылкам заменяются видимой заглушкой, пока вы явно их не разрешите. Относительные ссылки и другие ресурсы разрешаются согласно странице открытия экспортированного HTML.",
  "pageText.9ab93c5c": "Конфиденциальность и внешние ресурсы",
  "pageText.da04b65a": "Разбор и очистка Markdown локальны; текст не загружается этим инструментом. Изображения по ссылкам блокируются по умолчанию. Если включить их, браузер может обращаться к хостам и раскрывать метаданные соединения, например IP; предпросмотр задаёт no-referrer и ленивую загрузку. Переходы по ссылкам, история буфера обмена, скачанные файлы, расширения и место публикации HTML — отдельные пути данных.",
  "pageText.fd136c59": "Какие виды регистра поддерживаются?",
  "pageText.972118df": "Поддерживаются camelCase, PascalCase, kebab-case, snake_case, CONSTANT_CASE, space case и dot.case.",
  "pageText.8e8d253c": "Что такое camelCase?",
  "pageText.0c0fc023": "camelCase соединяет слова без разделителей, начинает со строчной буквы и делает прописной первую букву следующих слов, как userProfileId. Это обычный стиль переменных JavaScript и Java.",
  "pageText.fab0fc0e": "Чем отличаются snake_case и kebab-case?",
  "pageText.ffa6d712": "Оба используют строчные буквы. snake_case разделяет слова подчёркиванием (user_profile_id) и распространён в Python и SQL. kebab-case использует дефисы (user-profile-id) и распространён в URL и CSS, но не подходит именам переменных большинства языков, поскольку - означает минус.",
  "pageText.83ad6918": "Почему текст В ВЕРХНЕМ РЕГИСТРЕ странно преобразуется в camelCase?",
  "pageText.20a709bd": "camelCase и PascalCase сохраняют существующие прописные буквы, поэтому HELLO_WORLD становится hELLOWORLD. Сначала преобразуйте в snake_case или space case (hello_world), затем результат в camelCase для helloWorld.",
  "pageText.8b5b532b": "Какой регистр использовать для переменных окружения?",
  "pageText.d1aa7699": "CONSTANT_CASE, например DATABASE_URL. Прописные буквы, цифры и подчёркивания — переносимое соглашение для имён переменных окружения в Unix-подобных системах.",
  "pageText.45c5778c": "Какой регистр лучше для URL?",
  "pageText.a79aed09": "kebab-case. Строчные слова через дефис легко читать; Google рекомендует дефисы, а не подчёркивания, для разделения слов в URL.",
  "pageText.05244f1a": "Соглашения об именах и их применение",
  "pageText.a6b96046": "camelCase (userProfileId): переменные и функции JavaScript и Java, ключи JSON во многих API.",
  "pageText.fdfeef9a": "PascalCase (UserProfileId): имена классов, типы TypeScript, компоненты React и члены C#.",
  "pageText.664a685d": "snake_case (user_profile_id): переменные и функции Python и Ruby, имена столбцов SQL.",
  "pageText.88ba7528": "CONSTANT_CASE (USER_PROFILE_ID): константы и переменные окружения.",
  "pageText.d95625b3": "kebab-case (user-profile-id): слаги URL, имена классов CSS, атрибуты HTML и флаги командной строки.",
  "pageText.0eab35c7": "dot.case (user.profile.id): ключи конфигурации и ID сообщений перевода.",
  "pageText.6428569e": "space case (user profile id): обычные строчные слова для подписей или дальнейшего редактирования.",
  "pageText.a1ccbb20": "Как определяются слова",
  "pageText.eb52946f": "Конвертер разделяет слова по пробелам, дефисам, подчёркиваниям, точкам и там, где за строчной буквой следует прописная. Поэтому user_profile-id, userProfileId и User Profile Id дают один snake_case: user_profile_id. Цифры остаются с соседним словом, поэтому api-v2 response становится apiV2Response в camelCase и api_v2_response в snake_case.",
  "pageText.3ec8336a": "Граничные случаи для проверки",
  "pageText.7af4b6f9": "Последовательность прописных считается одним словом: XMLHttpRequest становится xmlhttp-request, а не xml-http-request. Добавьте разделители (XML Http Request), если сокращение нужно разделить.",
  "pageText.ac6701e0": "camelCase и PascalCase сохраняют существующие прописные, поэтому сначала преобразуйте ALL-CAPS в snake_case, затем в camelCase.",
  "pageText.4ac21c06": "Пунктуация кроме - _ . и пробелов сохраняется: Hello World! становится helloWorld! в camelCase. Удалите недопустимые в идентификаторах символы.",
  "pageText.0bc340ed": "Переводы строк считаются пробельными символами, поэтому многострочный ввод соединяется в один идентификатор. Преобразуйте по одному имени.",
  "pageText.83b3cb6b": "Границами прописных слов считаются только A-Z, поэтому прописная с диакритикой, например É внутри слова, не начинает новое слово.",
  "pageText.c7cb896c": "Преобразование имён в коде",
  "pageText.e93e8bdd": "JavaScript: lodash предлагает camelCase, kebabCase и snakeCase. Lodash сначала переводит каждое слово в нижний регистр, поэтому camelCase('HELLO_WORLD') возвращает helloWorld.",
  "pageText.2245868e": "API: вместо ручного переименования ключей используйте сопоставление сериализатора, например Jackson PropertyNamingStrategies.SNAKE_CASE в Java или генератор псевдонимов Pydantic.",
  "pageText.30d85b7e": "Рефакторинг: переименовывайте идентификаторы командой редактора вместо поиска и замены, чтобы обновлялись ссылки в других файлах.",
  "pageText.a7bd2d40": "Что подсчитывается?",
  "pageText.51bef002": "Слова, символы с пробелами и без, строки, предложения и абзацы, а также примерное время чтения. Всё обновляется при вводе.",
  "pageText.051f4a91": "Как рассчитывается время чтения?",
  "pageText.87fbca18": "Количество слов делится на среднюю скорость 200 слов в минуту и округляется вверх до целой минуты, поэтому 450 слов показываются как 3 минуты.",
  "pageText.b3ed5e8b": "Включает ли число символов пробелы?",
  "pageText.b1bd314d": "Показатель символов включает пробелы, табуляции и переводы строк. Символы без пробелов исключают все пробельные символы. Перед сокращением текста проверьте, какой показатель имеет в виду форма или руководство по стилю.",
  "pageText.1dd1b66b": "Почему эмодзи считается двумя символами?",
  "pageText.75918985": "Символы считаются как длина строки JavaScript — в кодовых единицах UTF-16. Большинство эмодзи и некоторые редкие знаки используют две единицы и прибавляют 2; составные семейные эмодзи или флаги могут прибавлять больше.",
  "pageText.d65fcd89": "Почему число предложений выше ожидаемого?",
  "pageText.2fc1b39a": "Предложения разделяются по ., ! и ?. Сокращения e.g. или Dr., десятичные числа вроде 3.14 и URL добавляют разрывы, поэтому число предложений — оценка.",
  "pageText.1a163ec9": "Мой текст сохраняется или загружается?",
  "pageText.0fef5a83": "Нет. Подсчёт происходит в браузере, ничего не отправляется на сервер и текст не сохраняется после ухода со страницы.",
  "pageText.b58e5ca1": "Как рассчитывается каждый показатель",
  "pageText.27c1e98e": "Слова: группы символов через пробельные символы. Слова с дефисом и сокращения вроде well-known или don't считаются одним словом; отдельное число или тире тоже считается словом.",
  "pageText.b7cde3d8": "Символы: каждый символ, включая пробелы и переводы строк. Символы без пробелов исключают все пробельные символы, включая табуляции и переводы строк.",
  "pageText.ac4f81d6": "Строки: число переводов строки плюс один, включая пустые строки.",
  "pageText.dccbe9b3": "Предложения: сегменты текста, заканчивающиеся ., ! или ?. Сокращения и десятичные числа добавляют разрывы.",
  "pageText.ac9536dd": "Абзацы: блоки текста, разделённые хотя бы одной пустой строкой. Один перевод строки не начинает новый абзац.",
  "pageText.c2e627fb": "Время чтения: слова, делённые на 200, с округлением вверх до целой минуты.",
  "pageText.817a0ebe": "Почему показатели разных инструментов отличаются",
  "pageText.ddc50b04": "Текстовые редакторы и сайты не имеют общего определения слова или символа. Некоторые разделяют сложные слова с дефисом, игнорируют числа или считают длинное тире между словами разделителем. Пределы символов различаются ещё больше: здесь используется длина строки JavaScript, где большинство эмодзи — два символа. Системы, считающие байты, например некоторые столбцы баз, или кодовые точки Unicode дадут другой итог. В языках без пробелов, например китайском и японском, одна группа без пробелов считается одним словом, поэтому ориентируйтесь на символы. Пробелы по краям не добавляют слов, но добавляют символы.",
  "pageText.8d394a34": "Проверка распространённых ограничений текста",
  "pageText.14f2e128": "SMS: один сегмент содержит 160 символов алфавита GSM-7 или 70, если есть символы вне него, например эмодзи.",
  "pageText.3ea61033": "Поисковые фрагменты: title обычно держат примерно до 60 символов, а метаописания — около 150–160, поскольку поисковые системы обрезают длинный текст по ширине отображения.",
  "pageText.b63f3eaf": "Публикации соцсетей: платформы вроде X используют свои правила, например веса ссылок и эмодзи; проверяйте окончательную длину в редакторе платформы.",
  "pageText.9eea4352": "Эссе и статьи: предел слов обычно относится к основному тексту; проверьте включение заголовков, источников и сносок.",
  "pageText.2ad739ba": "Как работает обнаружение повторов?",
  "pageText.a0e337c4": "Инструмент сравнивает каждую строку и оставляет только первое вхождение. Можно переключать учёт регистра и обрезку пробелов.",
  "pageText.465a3722": "Что происходит с пустыми строками?",
  "pageText.818a7fb1": "Пустые строки сохраняются на исходных местах.",
  "pageText.ee732984": "Как работает сортировка?",
  "pageText.05cacbdc": "Строки сортируются по алфавиту через сравнение символов Unicode. Можно выбрать порядок по возрастанию или убыванию.",
  "pageText.f14a257f": "Учитывается ли регистр при сортировке?",
  "pageText.5bc0fcf2": "По умолчанию регистр не учитывается. Учёт регистра можно включить в настройках.",
  "pageText.e0ce4b55": "Почему число байтов UTF-8 отличается от числа символов?",
  "pageText.cea04185": "Стандартные символы ASCII используют по 1 байту, буквы с диакритикой вроде é, ç — 2 байта, а эмодзи вроде 🚀, 🎉 — 4 байта UTF-8.",
  "pageText.58a712ea": "Как работает проверка ограничения столбца базы данных?",
  "pageText.41e8b156": "Можно выбрать типы VARCHAR(64), VARCHAR(255) или TEXT и увидеть оставшееся число байтов до превышения ограничений строки базы данных.",
  "pageText.ae565f86": "Правильно ли Title Case обрабатывает короткие английские предлоги?",
  "pageText.24671ad1": "Да. Слова «to», «a», «an», «the», «in», «for», «and» при необходимости остаются строчными по правилам Chicago Manual of Style.",
  "pageText.979a2e10": "Какие невидимые символы обнаруживаются?",
  "pageText.1c5cc230": "Пробелы нулевой ширины (U+200B), соединители (U+200D), разъединители (U+200C), метки порядка байтов (U+FEFF), мягкие переносы (U+00AD) и метки направления.",
  "pageText.07f01c24": "Что делает конвертер cURL в Axios?",
  "pageText.d549d86a": "Он преобразует терминальные команды cURL в аккуратные фрагменты JavaScript или TypeScript Axios.",
  "pageText.9968e572": "Да, всё преобразование полностью происходит локально в браузере.",
  "pageText.6d5cdf50": "Как преобразовать Fetch в cURL?",
  "pageText.daf0662a": "Вставьте фрагмент fetch(), и инструмент автоматически выдаст отформатированную команду cURL.",
  "pageText.5847b1ec": "Поддерживаются ли заголовки и тела POST?",
  "pageText.5ad9f567": "Да, заголовки, HTTP-методы и тела JSON полностью разбираются и сохраняются.",
  "pageText.8215376e": "Как работает преобразование JSON в XML?",
  "pageText.92a5e19e": "Оно рекурсивно преобразует ключи и значения JSON в корректные элементы и атрибуты XML.",
  "pageText.5ed08f30": "Можно ли настроить корневой тег XML?",
  "pageText.4df315df": "Да, можно задать любое имя корневого тега и тега элемента массива.",
  "pageText.293797b5": "Можно ли вставлять напрямую из Excel или Google Sheets?",
  "pageText.168c9958": "Да, скопируйте ячейки таблицы и вставьте их прямо в редактор.",
  "pageText.e63c6336": "Числа и логические значения распознаются автоматически?",
  "pageText.e46b649e": "Да, числовые значения и true/false автоматически преобразуются в собственные типы JSON.",
  "pageText.a6ffb0f2": "Поддерживаются ли вложенные объекты JSON?",
  "pageText.9c66d528": "Да, вложенные объекты автоматически преобразуются в плоские с ключами в точечной записи.",
  "pageText.8faf9499": "Можно ли экспортировать CSV или TSV?",
  "pageText.ee9682fe": "Да, выберите значения с разделением запятой, табуляцией или точкой с запятой.",
  "pageText.a1264c1a": "Безопасно ли преобразовывать личные фотографии?",
  "pageText.fba7c3f6": "Да, вся обработка изображений локальна в браузере через HTML5 Canvas. Фотографии никогда не покидают устройство.",
  "pageText.2192ee7b": "Какие форматы поддерживаются?",
  "pageText.893d1681": "PNG, JPEG, WebP, AVIF, BMP и ICO.",
  "pageText.7ae5d66d": "Можно ли поменять порядок изображений до создания PDF?",
  "pageText.c48f2df7": "Да, используйте кнопки со стрелками на миниатюрах для изменения порядка страниц.",
  "pageText.1028470b": "Мои изображения загружаются на сервер?",
  "pageText.43031004": "Нет, создание PDF полностью выполняется в браузере.",
  "pageText.cafd399d": "Это то же, что генератор структур Golang из JSON?",
  "pageText.60309daa": "Да. Go часто называют Golang; этот единый инструмент создаёт определения структур с тегами json из любого образца JSON, включая вложенные объекты и массивы.",
  "pageText.02bd6e0d": "Можно ли выбрать имя корневой модели?",
  "pageText.53e10075": "Да. Задайте имя над редактором. Вложенные объекты именуются по ключам JSON, а массив объектов верхнего уровня моделируется по первому элементу.",
  "pageText.5a4c5407": "Включает ли результат макросы serde derive?",
  "pageText.fa083659": "Да. Каждая структура получает Serialize и Deserialize, а также Debug, Clone и Default, и атрибуты serde rename для исходных ключей JSON. Добавьте пакеты serde и serde_json в проект.",
  "pageText.9c425ac2": "Генератор создаёт структуры или классы?",
  "pageText.7fc8b986": "Структуры. Каждый объект JSON становится структурой с Codable и Identifiable, вложенные объекты — вложенными типами структур. Проверьте имена свойств и необязательность перед использованием в приложении.",
  "pageText.8f6dab1d": "На какую библиотеку сериализации Kotlin рассчитан результат?",
  "pageText.57ebd790": "На kotlinx.serialization. Каждый класс данных имеет @Serializable, а каждое свойство — @SerialName для сохранения имён полей JSON.",
  "pageText.cce3877b": "Можно ли создавать записи C# вместо классов?",
  "pageText.d0862846": "Да. Переключите стиль на Record для позиционных записей с [property: JsonPropertyName] либо оставьте Class для изменяемых классов со свойствами get и set. Вложенные объекты становятся отдельными типами в обоих стилях.",
  "pageText.ffb3fe14": "Создаёт ли конвертер ресурсы Ingress или ConfigMap?",
  "pageText.cd91ea98": "Нет. Для каждого обнаруженного сервиса Compose он создаёт начальный Deployment и ClusterIP Service с тегами-заглушками образов и портом 80. Настройте образы, порты, окружение и тома, самостоятельно добавьте Ingress, ConfigMap, Secret, проверки и ограничения ресурсов до применения в кластере.",
  "pageText.9eac6229": "Что такое временная метка Unix?",
  "pageText.1487701c": "Это число секунд, прошедших с 1 января 1970 года UTC — эпохи Unix.",
  "pageText.0789772f": "Использовать секунды или миллисекунды?",
  "pageText.a0e3b7cc": "Утилиты Unix и многие серверные API обычно используют секунды, а JavaScript Date.now() возвращает миллисекунды. Текущее значение имеет около 10 цифр в секундах и 13 в миллисекундах; явно выбирайте единицу вместо угадывания по цифрам.",
  "pageText.2eb9e432": "Как обрабатываются часовые пояса?",
  "pageText.3d5ad092": "Время показывается в UTC ISO 8601 и местном формате часового пояса браузера. При преобразовании текста включайте Z или явное смещение, если момент должен быть однозначным.",
  "pageText.1bc9c5b5": "Как работает преобразование времени Unix",
  "pageText.0fe51e8a": "Временная метка Unix задаёт момент относительно 1970-01-01T00:00:00Z. Конвертер принимает целое число в выбранных секундах или миллисекундах, превращает в строку UTC ISO 8601 и форматирует тот же момент в местном поясе браузера. Обратное преобразование разбирает строку даты и возвращает выбранную единицу эпохи.",
  "pageText.2dc0bf0f": "Пример секунд и миллисекунд",
  "pageText.aae8bcfb": "1704110400 секунд и 1704110400000 миллисекунд представляют один момент: 2024-01-01T12:00:00.000Z. Неверная единица сильно сдвигает дату или делает её некорректной. Отрицательные метки могут представлять поддерживаемые даты до эпохи Unix.",
  "pageText.eee856bc": "Ограничения разбора и точности",
  "pageText.6d9f9cca": "Временная метка должна быть знаковым безопасным целым JavaScript. Дроби, экспоненциальная запись и целые вне безопасного диапазона отклоняются.",
  "pageText.38a39d56": "Строки дат без Z или явного числового смещения могут трактоваться в местном поясе браузера; для воспроизводимости указывайте смещение.",
  "pageText.8673caf8": "JavaScript Date следует поддерживаемому календарному диапазону и не моделирует високосные секунды.",
  "pageText.77f27ab3": "Преобразование локально. Местное время зависит от настроек часового пояса устройства и исторических правил, доступных браузеру.",
  "pageText.9dce9428": "Что такое цвет HEX?",
  "pageText.808cc6b3": "HEX записывает красный, зелёный и синий каналы тремя парами шестнадцатеричных цифр после #, каждая от 00 до FF. #FF5733 означает красный 255, зелёный 87, синий 51.",
  "pageText.e9871c7d": "Чем отличаются RGB и HSL?",
  "pageText.33296696": "RGB определяет цвет количеством красного, зелёного и синего света. HSL описывает тот же цвет углом тона, процентами насыщенности и светлоты, упрощая создание светлых, тёмных и приглушённых вариантов.",
  "pageText.e28100f8": "Как преобразовать HEX в RGB?",
  "pageText.fe0c27b9": "Разделите шесть цифр на пары и преобразуйте каждую из основания 16: первая цифра × 16 плюс вторая. #1E90FF даёт 1E = 30, 90 = 144, FF = 255, то есть rgb(30, 144, 255).",
  "pageText.84f954db": "Почему #FFF не принимается?",
  "pageText.ee7c794e": "Поле HEX ожидает шесть цифр. Разверните сокращённую запись из трёх удвоением каждой: #FFF становится #FFFFFF, #0AF — #00AAFF.",
  "pageText.b67270be": "Можно ли преобразовывать цвета с прозрачностью?",
  "pageText.4f6be07c": "Не этим инструментом. Он преобразует непрозрачные цвета, поэтому HEX из 8 цифр, rgba() и hsla() не поддерживаются. Преобразуйте цветовую часть и добавьте альфа-значение самостоятельно, например rgb(59 130 246 / 50%).",
  "pageText.9ce1a868": "Что такое дополнительный цвет?",
  "pageText.086acf39": "Противоположный на цветовом круге: те же насыщенность и светлота с поворотом тона на 180 градусов. Палитра создаёт его вместе с аналоговыми, триадными и раздельно-дополнительными вариантами.",
  "pageText.e95a3278": "Как связаны HEX, RGB и HSL",
  "pageText.b8e6ba16": "Все три описывают одинаковые цвета sRGB. RGB задаёт красный, зелёный и синий каналы от 0 до 255. HEX записывает их парами HEX-цифр, поэтому #3B82F6 — rgb(59, 130, 246): 3B = 59, 82 = 130, F6 = 246. HSL описывает цвет тоном (угол 0–360 на цветовом круге), насыщенностью 0–100% и светлотой 0–100%; тот же синий — hsl(217, 91%, 60%). HSL удобен для вариантов: сохраняйте тон и насыщенность, меняйте лишь светлоту для более светлого или тёмного оттенка.",
  "pageText.9bb0180e": "Ручное преобразование форматов",
  "pageText.20dfb288": "Для HEX в RGB разделите шесть цифр на три пары и переведите каждую из основания 16. Для #FF5733: FF = 15 x 16 + 15 = 255, 57 = 5 x 16 + 7 = 87, 33 = 3 x 16 + 3 = 51, то есть rgb(255, 87, 51). Для RGB в HEX преобразуйте каждый канал в HEX и дополните одиночную цифру нулём: rgb(0, 128, 255) становится #0080FF. HSL требует больше арифметики, где конвертер экономит время.",
  "pageText.c627f2e0": "Округление и обратное преобразование",
  "pageText.9f7b1c2c": "HSL округляется до целых, а каждый канал RGB имеет лишь 256 уровней, поэтому несколько близких HSL соответствуют одному RGB. Преобразование HSL в RGB и обратно может сдвинуть значение на единицу. Для точных значений считайте HEX или RGB источником истины: их рисует браузер.",
  "pageText.d798a9e9": "Поддерживаемые ввод и вывод",
  "pageText.b62d0366": "Ввод HEX требует шесть цифр с начальным # или без него.",
  "pageText.809bb2a0": "Поля RGB и HSL принимают целые и ограничивают их допустимыми диапазонами.",
  "pageText.9800df6a": "Альфа-каналы, именованные цвета вроде rebeccapurple, CMYK и новые пространства CSS вроде oklch() не преобразуются.",
  "pageText.34fe3200": "Копируемые значения имеют синтаксис CSS, например #3B82F6, rgb(59, 130, 246), hsl(217, 91%, 60%), и сразу подходят таблице стилей.",
  "pageText.03fd111c": "Образцы палитры вращают тон: дополнительный на 180 градусов, аналоговые на ±30, триадные на 120 и 240, раздельно-дополнительные на 150 и 210. Нажмите образец для копирования и загрузки его HEX.",
  "pageText.ad112684": "Каков диапазон?",
  "pageText.3ed8b237": "Римские цифры представляют числа от 1 до 3999. За пределами диапазона нужна специальная запись.",
  "pageText.646816d5": "Как образуются числа?",
  "pageText.2ae173d7": "Римские числа используют сложение (VI = 6) и вычитание (IV = 4) с буквами I, V, X, L, C, D, M.",
  "pageText.4c9566cb": "Принимает ли конвертер IIII или IC?",
  "pageText.7dbeba2f": "Нет. Декодировщик принимает каноническую римскую запись, поэтому 4 должно быть IV, 99 — XCIX. Нестандартные или некорректные формы дают ошибку проверки.",
  "pageText.661774c4": "Как работает конвертер римских чисел?",
  "pageText.a2601719": "Режим числа в римскую запись сопоставляет целое десятичное число стандартным символам с обычными вычитательными парами IV, IX, XL, XC, CD и CM. Обратный режим читает символы, считает значение и перед результатом проверяет каноничность записи этого значения.",
  "pageText.3ab2deeb": "Примеры преобразования римских чисел",
  "pageText.0cd38bbc": "4 становится IV, 49 — XLIX, 1994 — MCMXCIV, 2026 — MMXXVI. В обратном режиме те же записи дают 4, 49, 1994 и 2026.",
  "pageText.e190ddca": "Вычитательная запись ставит меньший символ перед большим в разрешённых парах. IX означает 9, CM — 900. Другие значения образуются сложением: VIII — 5 + 1 + 1 + 1, то есть 8.",
  "pageText.f97dd159": "Диапазон и правила проверки",
  "pageText.0edecea6": "Конвертер поддерживает целые от 1 до 3999 — обычный диапазон без надчёркиваний или расширенной записи. Ноль, отрицательные, дробные и числа выше 3999 отклоняются вместо нестандартного результата.",
  "pageText.8e949328": "Римский ввод нечувствителен к регистру, но требует стандартной канонической формы. Некорректные повторы и сокращения IIII или IC отклоняются. Строгая проверка отличает распознанное римское число от строки, лишь содержащей римские буквы.",
  "pageText.bcefa6b3": "Какие системы счисления поддерживаются?",
  "pageText.7414cdc4": "Десятичная (основание 10), шестнадцатеричная (16), восьмеричная (8) и двоичная (2).",
  "pageText.b72bd2ab": "Как использовать префиксы?",
  "pageText.0e908091": "Можно использовать 0x для HEX, 0o для восьмеричной и 0b для двоичной записи. Они обрабатываются автоматически.",
  "pageText.fc1aa399": "Можно ли преобразовывать целые больше Number.MAX_SAFE_INTEGER?",
  "pageText.1a04613d": "Да. Преобразование использует BigInt и проверяет весь ввод, сохраняя большие целые без округления. Ввод ограничен 10 000 цифр для отзывчивости браузера; дроби намеренно не поддерживаются.",
  "pageText.6c46d667": "Можно ли разбирать URL без протокола?",
  "pageText.211d4985": "Да. При отсутствии протокола инструмент пытается разобрать ввод, предполагая HTTPS.",
  "pageText.a249117f": "Поддерживаются ли повторяющиеся параметры запроса?",
  "pageText.3fa7bebe": "Да. Они сохраняются и возвращаются массивами.",
  "pageText.974f66ef": "Можно ли разобрать полный URL?",
  "pageText.d840a415": "Да. Вставьте полный URL, и инструмент извлечёт и разберёт строку запроса.",
  "pageText.de982fa1": "Поддерживаются ли повторяющиеся ключи?",
  "pageText.aacf5366": "Да. При разборе повторяющиеся ключи сохраняются массивами.",
  "pageText.5ec1335a": "Всегда ли значения .env являются строками?",
  "pageText.f1c07be7": "На границе процесса переменные окружения — строки. Необязательное определение типов удобно для JSON и преобразует лишь явные логические значения, числа в стиле JSON и null; оставьте его выключенным для точного сохранения строк.",
  "pageText.a47731b1": "Что происходит при повторном определении ключа?",
  "pageText.683572e4": "Побеждает последнее определение, как обычно в dotenv; конвертер показывает предупреждение с обоими номерами строк, чтобы повтор не был скрыт.",
  "pageText.837b99bd": "Разворачивает ли инструмент переменные вроде ${HOST}?",
  "pageText.40d37465": "Нет. Он разбирает значения, но намеренно не подставляет переменные, не выполняет выражения оболочки, не читает файлы и не обращается к серверу. Подстановка различается между загрузчиками dotenv и должна проверяться в целевой среде.",
  "pageText.2c76582a": "Что поддерживает конвертер .env и JSON",
  "pageText.4f2d45bf": "В режиме .env в JSON парсер принимает пустые строки, комментарии, необязательные префиксы export, обычные имена переменных, значения без кавычек и в одинарных, двойных или обратных кавычках. Декодируются экранированные перевод строки, возврат каретки, табуляция, кавычка и обратная косая черта в двойных кавычках. Значения в кавычках могут занимать несколько строк, а комментарии вне кавычек удаляются.",
  "pageText.c5c8e5b3": "Определение типов и обработка повторов",
  "pageText.1f8452da": "По умолчанию каждое значение окружения остаётся строкой, как операционные системы предоставляют переменные процесса.",
  "pageText.6b7c8875": "Необязательное определение преобразует true, false, null и однозначные числа в стиле JSON; значения вроде 0012 остаются строками для сохранения ведущих нулей.",
  "pageText.49af1e34": "При повторе ключа выводится последнее значение, а предупреждение указывает повторные определения.",
  "pageText.108380d1": "Вывод JSON использует словарь с безопасным прототипом, поэтому особые имена __proto__ остаются обычными ключами данных.",
  "pageText.f9bf5831": "Как JSON записывается в dotenv",
  "pageText.7723ffc4": "Режим JSON в .env требует объект верхнего уровня с допустимыми именами переменных окружения в ключах. Строки заключаются в двойные кавычки и экранируются, числа и логические значения записываются литералами, null становится пустой строкой с предупреждением, массивы и вложенные объекты — строками JSON в кавычках. Проверьте структурированные значения: принимающее приложение решает, разбирать ли их повторно и как.",
  "pageText.601a8514": "Конфиденциальность и различия диалектов",
  "pageText.232534d5": "Преобразование выполняется в браузере без загрузки значений полей. Dotenv — соглашение с различиями реализаций: подстановка переменных и команд, обработка export и экранирование могут различаться в Node.js, Docker, оболочках и загрузчиках фреймворков. Проверьте файл в точной среде его потребления и предпочитайте обезличенные примеры рабочим учётным данным.",
  "pageText.5de3368a": "Как обрабатываются атрибуты SVG в React?",
  "pageText.cff1c703": "Все HTML/SVG-атрибуты с дефисами, например stroke-width, fill-rule, clip-path, преобразуются в допустимый React camelCase: strokeWidth, fillRule, clipPath, а class — в className.",
  "pageText.8b4e6d97": "Поддерживаются ли TypeScript и forwardRef?",
  "pageText.a1b09414": "Да! Одним нажатием можно переключать интерфейсы TypeScript, оболочки forwardRef и стандартный spread свойств.",
  "pageText.354d5c2b": "Как работает CSS clamp()?",
  "pageText.b2935b68": "Функция clamp(min, preferred, max) задаёт желаемое значение по ширине экрана (vw), ограниченное минимумом и максимумом.",
  "pageText.b872cb54": "Зачем плавная типографика?",
  "pageText.4477ab71": "Она плавно масштабирует текст по размерам экрана без резких скачков между фиксированными точками медиазапросов.",
  "pageText.5025653d": "Какие флаги docker run поддерживаются?",
  "pageText.1aff160c": "Конвертер разбирает -p/--publish, -v/--volume, -e/--env, --name, --restart, --network, -w/--workdir, -u/--user, --privileged и аргументы команды контейнера.",
  "pageText.edeb7b4c": "Подходит ли результат современному Docker Compose?",
  "pageText.34af0ae3": "Да, созданный YAML следует формату современной спецификации Docker Compose.",
  "pageText.657d05ae": "Какие диалекты SQL поддерживаются?",
  "pageText.9519e5df": "Поддерживаются PostgreSQL, MySQL, SQLite и Microsoft SQL Server.",
  "pageText.81282e94": "Как определяются типы данных?",
  "pageText.35a0c93d": "Числа, логические значения, строки дат ISO, объекты и длины текста анализируются по всем строкам для определения подходящих типов столбцов.",
  "pageText.7abbc1c1": "Каков стандартный базовый размер шрифта для REM?",
  "pageText.6b49dd1e": "Корневой размер браузера по умолчанию — 16px (1rem = 16px). Базу можно настроить, если CSS задаёт html { font-size: 62.5%; } (база 10px) или другие шкалы.",
  "pageText.3ea4c69b": "Чем отличаются REM и EM?",
  "pageText.f8a454cb": "REM (Root EM) относится к font-size корневого <html>, а EM — к размеру шрифта непосредственного родительского контейнера.",
  "pageText.2d5d624d": "Поддерживает ли инструмент TSV с разделителем-табуляцией?",
  "pageText.8dd82b44": "Да. Можно вставлять данные с запятыми или табуляциями прямо из табличных приложений Excel или Google Sheets.",
  "pageText.6e30c9b1": "Можно ли преобразовать таблицы Markdown обратно в CSV?",
  "pageText.e858f5f7": "Да, нажмите «Синхронизировать MD ➔ CSV» для разбора таблицы Markdown обратно в стандартный формат с запятыми.",
  "pageText.ccff8026": "Как определяются заголовки таблицы?",
  "pageText.d4655a54": "Конвертер автоматически использует первую строку элементов <th> или <td> как ключи итоговых объектов JSON.",
  "pageText.79df7ff1": "Можно ли вывести простой двумерный массив вместо объектов?",
  "pageText.9dd05233": "Да, выберите формат «Двумерный массив (строки и столбцы)», чтобы получить матрицу без именованных ключей.",
  "pageText.939b6803": "Поддерживаются ли инструкции INSERT с несколькими строками?",
  "pageText.0495ce61": "Да. Конвертер обрабатывает многострочные INSERT INTO table (col1, col2) VALUES (a, b), (c, d).",
  "pageText.444bfcdc": "Сохраняются ли типы: числа, логические значения, NULL?",
  "pageText.b9a181b3": "Да. Числа, логические литералы TRUE/FALSE и NULL автоматически разбираются и приводятся к собственным типам JSON.",
  "pageText.40323ee8": "Как упрощается соотношение сторон?",
  "pageText.cdbef1c9": "Калькулятор определяет наибольший общий делитель ширины и высоты для простейшего целочисленного отношения, например 1920×1080 сокращается до 16:9.",
  "pageText.bc6781c7": "Как использовать пропорциональное изменение размера?",
  "pageText.b80cad0b": "Введите исходную ширину и высоту, затем новую целевую ширину для автоматического расчёта точной пропорциональной высоты.",
  "pageText.4b28a4e9": "Какие элементы HTML поддерживаются?",
  "pageText.276d9f0c": "Конвертер поддерживает заголовки <h1>-<h6>, жирный текст <strong>/<b>, курсив <em>/<i>, ссылки <a>, изображения <img>, цитаты <blockquote>, списки <ul>/<ol>/<li>, блоки <code>/ <pre> и горизонтальные линии <hr>.",
  "pageText.6e1afb74": "Декодируются ли HTML-сущности?",
  "pageText.ba39602f": "Да, распространённые &amp;, &lt;, &gt;, &quot; и &#39; преобразуются в обычные символы.",
  "pageText.3799edfe": "Сохраняются ли теги языка кода?",
  "pageText.c2365433": "Да. Блоки (```javascript ... ```) преобразуются в <pre><code class=\"language-javascript\"> с корректным экранированием символов.",
  "pageText.8708ffd7": "Можно ли скачать созданный HTML?",
  "pageText.c459e434": "Да, нажмите значок скачивания для сохранения документа файлом .html.",
  "pageText.be3a3c63": "Насколько точен расчёт разницы дат?",
  "pageText.d3b0d64f": "Расчёты точны до миллисекунды на основе JavaScript Date API и стандартных временных меток UTC.",
  "pageText.af8c07b0": "Можно ли преобразовывать единицы времени, например часы в секунды?",
  "pageText.8b865303": "Да. Интерактивный раздел позволяет одновременно преобразовать любое количество между миллисекундами, секундами, минутами, часами и днями.",
  "pageText.a9fedf31": "Как атрибуты XML преобразуются в JSON?",
  "pageText.1c4c4809": "Атрибуты получают префикс «@» в объекте JSON, например @id=\"101\", для точного сохранения при обратном преобразовании в XML.",
  "pageText.fa379db8": "Можно ли сменить направление на JSON в XML?",
  "pageText.994016b7": "Да, нажмите «Переключить на JSON ➔ XML» для преобразования корректного объекта JSON в отформатированный XML-документ.",
  "pageText.8d1c8c14": "Экранирует ли инструмент внутренние одинарные кавычки?",
  "pageText.d9f1c9ca": "Да. Внутренние одинарные кавычки, например O'Connor, автоматически удваиваются ('' в стандартном SQL) для предотвращения ошибок синтаксиса.",
  "pageText.3f01da3d": "Можно ли форматировать списки чисел без кавычек?",
  "pageText.4b94fcb9": "Да! Выберите «Без кавычек (числа / ID)» в списке стиля кавычек для целочисленных и числовых списков.",
  "pageText.3d22bc27": "Поддерживаются ли прозрачные фоны?",
  "pageText.41464a2f": "Да! PNG и WebP поддерживают полную альфа-прозрачность. Также можно выбрать сплошной белый или чёрный фон.",
  "pageText.c16e4c4a": "Как работают масштабы разрешения 2x и 4x?",
  "pageText.e151b8c5": "Векторный SVG рисуется прямо на масштабированном HTML5 Canvas, обеспечивая чёткий, попиксельно точный результат высокого DPI без пикселизации.",
  "pageText.b2fcc05a": "Мои PDF-документы загружаются на какой-либо сервер?",
  "pageText.aea89d9c": "Нет! Декодирование и отрисовка полностью локальны в браузере через Blob URL и изолированные HTML5 iframe.",
  "pageText.2a1e46ea": "Поддерживаются ли префиксы data:application/pdf;base64?",
  "pageText.28866c6e": "Да. Конвертер автоматически обнаруживает и удаляет префиксы URI данных и лишние пробелы из Base64.",
  "pageText.9c3e5e8b": "Какие атрибуты HTML преобразуются?",
  "pageText.5c0146bd": "`class` преобразуется в `className`, `for` — в `htmlFor`, встроенные стили — в объектный синтаксис (`style={{ width: \"100px\" }}`), а SVG-атрибуты вроде `stroke-width` — в `strokeWidth`.",
  "pageText.1636cff7": "Какие диалекты баз данных поддерживаются?",
  "pageText.1763f21a": "PostgreSQL с идентификаторами в двойных кавычках, MySQL с обратными кавычками и общий стандартный SQL.",
  "pageText.bc4069b3": "Как обрабатываются вложенные объекты в GraphQL?",
  "pageText.38249950": "Вложенные объекты JSON извлекаются в отдельные определения GraphQL `type` и автоматически связываются по имени поля.",
  "pageText.d1268a9b": "Распознаёт ли инструмент числа и логические значения в TSV?",
  "pageText.657e3a11": "Да. Числовые значения и строки true/false автоматически становятся собственными примитивами JSON.",
  "pageText.ab767ca9": "Чем NDJSON отличается от JSON?",
  "pageText.ac640a73": "NDJSON содержит по одному корректному объекту JSON на строку без окружающих скобок массива, что удобно для потоковой передачи больших журналов.",
  "pageText.d53f6e6d": "Что такое Punycode?",
  "pageText.932ba104": "Punycode — синтаксис кодирования по RFC 3492, переводящий символы Unicode в ASCII-последовательности с префиксом «xn--», чтобы неанглийские домены работали со старыми DNS-системами.",
  "pageText.749281f3": "Воспроизводится ли настоящий звук азбуки Морзе?",
  "pageText.80d0a9ba": "Да! Через Web Audio API инструмент прямо в браузере синтезирует стандартные синусоидальные сигналы 650 Гц с точным временем точек и тире.",
  "pageText.5e8710c7": "Какие директивы Apache поддерживаются?",
  "pageText.883d775d": "RewriteRule с флагами R=301, L, Redirect 301, DirectoryIndex и Header set.",
  "pageText.e91fd411": "Насколько большим может быть CSV-файл?",
  "pageText.55e80dd0": "Поскольку обработка локальна в памяти браузера, инструмент может обрабатывать тысячи строк без задержки.",
  "pageText.948016f8": "Как типы SQL сопоставляются с TypeScript?",
  "pageText.73d3bf81": "INTEGER/FLOAT/DECIMAL становятся number, VARCHAR/TEXT/UUID — string, BOOLEAN — boolean, TIMESTAMP/DATE — Date | string.",
  "pageText.b445da7f": "Как вложенные объекты превращаются в ключи .env?",
  "pageText.6c4dff36": "Вложенные ключи соединяются подчёркиваниями в верхнем регистре, например `{ database: { host: \"...\" } }` становится `DATABASE_HOST=\"...\"`.",
  "pageText.a7ac2f25": "Обрабатываются ли запятые и кавычки внутри ячеек?",
  "pageText.ad06bce3": "Да. Ячейки с запятыми или специальными символами корректно экранируются двойными кавычками по RFC 4180.",
  "pageText.c0439e2b": "Какие диалекты SQL поддерживаются?",
  "pageText.9c661bd6": "Стандартный SQL, MySQL, MariaDB, PostgreSQL, SQLite, SQL Server (T-SQL), Oracle PL/SQL, BigQuery, Snowflake и Trino/Presto. Выберите целевой диалект запроса для распознавания его особого синтаксиса.",
  "pageText.898566a5": "Можно ли минифицировать SQL?",
  "pageText.bf763dfa": "Да. Минификация сжимает пробельные символы до одного пробела и убирает пробелы вокруг запятых, скобок, = и точек с запятой. Комментарии не удаляются, поэтому сначала удалите --: иначе всё после такого комментария в одной строке будет закомментировано.",
  "pageText.17bb729b": "Меняет ли форматирование поведение запроса?",
  "pageText.dfdbf373": "Нет. Оно меняет лишь пробельные символы и регистр ключевых слов. Идентификаторы, строковые литералы и порядок условий сохраняются; запрос не выполняется.",
  "pageText.e673de04": "Почему появляется ошибка разбора?",
  "pageText.f3989307": "Выбранный диалект не распознаёт часть синтаксиса либо кавычки или скобки не сбалансированы. Выберите диалект, для которого написан запрос. Шаблонный синтаксис {{ }} из dbt или Jinja может не разбираться.",
  "pageText.34719ea5": "Можно ли использовать табуляцию для отступов?",
  "pageText.81ba983d": "Результат всегда использует пробелы. Доступны 2 пробела, 4 пробела или ширина табуляции в 8 пробелов.",
  "pageText.568926d9": "Мой SQL отправляется на сервер?",
  "pageText.4517bb93": "Нет. Форматирование выполняется в браузере библиотекой JavaScript sql-formatter, без подключения к базе данных.",
  "pageText.9945834b": "Что меняет форматировщик",
  "pageText.0cac9d90": "Форматировщик разбивает SQL на токены выбранного диалекта и перестраивает вид. Основные части SELECT, FROM, JOIN, WHERE, GROUP BY, ORDER BY, LIMIT начинаются с отдельных строк, списки столбцов и условия получают отступы, несколько инструкций разделяются пустыми строками. Например, select id, name from users where active = 1 order by name становится запросом с SELECT, FROM, WHERE и ORDER BY отдельно и id, name с отступом под SELECT. Ключевые слова имеют выбранный верхний или нижний регистр. Идентификаторы, литералы и порядок частей не меняются, схема базы не проверяется.",
  "pageText.679a0218": "Выбор правильного диалекта",
  "pageText.0dad3f3a": "Диалекты различаются кавычками, операторами и параметрами; форматировщик распознаёт только выбранный синтаксис. При ошибке или неверном результате сначала проверьте соответствие диалекта базе. Примеры особенностей:",
  "pageText.94b6656c": "PostgreSQL: приведения ::, позиционные параметры $1 и тела функций в долларовых кавычках.",
  "pageText.2c576f60": "SQL Server (T-SQL): [идентификаторы в скобках], TOP и @variables.",
  "pageText.8af13c1a": "MySQL и MariaDB: идентификаторы в обратных кавычках (`backtick`).",
  "pageText.ea0458f2": "BigQuery: имена project.dataset.table в обратных кавычках и типы STRUCT или ARRAY.",
  "pageText.3fb5a202": "Минификация — текстовое преобразование",
  "pageText.fcad398d": "Минификация сжимает каждую последовательность пробельных символов до одного пробела и убирает пробелы вокруг запятых, скобок, = и точек с запятой. Она работает с текстом, а не разобранным SQL, что имеет два последствия. Во-первых, комментарии не удаляются: поскольку -- длится до конца строки, перевод всего запроса в одну строку может закомментировать всё после него; удалите -- или замените на /* */ до минификации. Во-вторых, повторяющиеся пробелы внутри строковых литералов тоже сжимаются; сравните с оригиналом, если они важны.",
  "pageText.1191c370": "Комментарии и несколько инструкций",
  "pageText.3cf0e67e": "При форматировании комментарий -- в конце строки кода остаётся там, а целые строки комментариев сохраняются на месте. Инструкции через точку с запятой форматируются последовательно с пустыми строками между ними, поэтому можно вставить весь сценарий миграции или наполнения и проверять по инструкциям.",
  "pageText.367d147f": "Насколько можно уменьшить CSS?",
  "pageText.62ddee05": "Зависит от таблицы стилей. Удалите комментарии и лишние пробелы, затем сравните показанные размеры оригинала и результата. Уже компактный CSS может измениться мало.",
  "pageText.95c1ec0d": "Корректен ли минифицированный CSS?",
  "pageText.5857bc9f": "Минификация использует CSS-парсер с отключённой перестройкой правил, но перед развёртыванием проверьте результат на своих страницах.",
  "pageText.ed466d2a": "Меняет ли минификация поведение CSS?",
  "pageText.d268f9c7": "Не должна. Перестройка правил отключена: селекторы не объединяются, порядок правил не меняется, каскад сохраняется. Используются лишь более короткие эквиваленты, например #fff вместо #ffffff.",
  "pageText.0f9b8560": "Сохранятся ли комментарии лицензии?",
  "pageText.3a2460c3": "Только при отключённом удалении комментариев. Если оно включено, удаляются все комментарии, включая баннеры лицензий /*! */. Если выключено, все сохраняются на месте.",
  "pageText.f6ab050a": "Можно ли развернуть минифицированный CSS?",
  "pageText.f9981fd3": "Используйте форматирование для добавления переносов и отступов. Исходные комментарии и точное форматирование после удаления восстановить нельзя.",
  "pageText.e39c55b7": "Мой CSS загружается на сервер?",
  "pageText.5c9957b9": "Нет. CSSO выполняется в браузере, минифицируя стили на устройстве без отправки на сервер.",
  "pageText.9649813f": "Минификация CSS без изменения сборки",
  "pageText.de9a37b9": "Вставьте стили, решите, удалять ли комментарии, и выберите минификацию. CSSO разбирает CSS в синтаксическое дерево и компактно печатает обратно вместо удаления символов регулярными выражениями. Перестройка правил отключена: селекторы не объединяются, правила не перемещаются. Показанное уменьшение сравнивает символы, поэтому это оценка сэкономленного текста, а не размер сжатой сетевой передачи.",
  "pageText.67066e30": "Что уменьшается",
  "pageText.05d17ac2": "Удаляются пробельные символы, переводы строк и отступы между токенами.",
  "pageText.190686bf": "Удаляется последняя точка с запятой в блоках: .a { color: red; } становится .a{color:red}.",
  "pageText.c6a90a1b": "Цвета записываются более коротким эквивалентом, если он существует: #ffffff становится #fff.",
  "pageText.5abe9013": "Единицы убираются у нулевых длин: margin: 0px 0px становится margin:0 0.",
  "pageText.8fb6a9bc": "При включённом удалении комментариев удаляются все, включая баннеры лицензий /*! */.",
  "pageText.354dff68": "Остальные селекторы и значения сохраняются как написано. Неиспользуемые правила не обнаруживаются и не удаляются: минификатор не видит использующий стили HTML.",
  "pageText.704bf1fa": "Безопасное использование результата",
  "pageText.2ebe9c56": "Скопируйте минифицированный CSS в тестовую сборку и проверьте затронутые страницы при нужных размерах экрана.",
  "pageText.ab5ace02": "Для сохранения обязательных комментариев лицензий отключите удаление комментариев до минификации.",
  "pageText.889b86fa": "Используйте форматирование как помощь чтению; проверяйте сложный CSS после него, поскольку оно отдельно от минификации на основе парсера.",
  "pageText.4040b973": "Минификация работает вместе с серверным сжатием, не заменяя его: gzip или Brotli ещё уменьшают файл при передаче.",
  "pageText.8111e866": "Когда использовать сборщик",
  "pageText.4d2afabc": "Если проект уже использует сборщик или фреймворк, минификация CSS обычно настроена там через Lightning CSS, cssnano или esbuild и выполняется при каждой сборке. Инструмент подходит отдельным стилям, файлам CMS и тем, CSS для стороннего виджета и быстрому анализу минификации конкретного правила. Стили в head блокируют отрисовку до загрузки, поэтому меньшие файлы ускоряют первый показ на медленных соединениях, хотя удаление неиспользуемых правил часто экономит больше одной минификации.",
  "pageText.d083d747": "Какие оптимизации применяются?",
  "pageText.e796e2d2": "Terser удаляет пробелы, необязательные точки с запятой и комментарии, сворачивает константные выражения, удаляет недостижимый код и упрощает условия. Дополнительные настройки удаляют console.* и debugger и сокращают true, false до !0, !1.",
  "pageText.6feece85": "Использовать ли это для рабочей среды?",
  "pageText.f02032e4": "Инструмент использует Terser для минификации JavaScript на основе парсера. В рабочих сборках минификацию всё равно следует интегрировать в Webpack, Rollup или esbuild.",
  "pageText.9996cfd4": "Сломает ли минификация код?",
  "pageText.1d35f0cc": "Terser применяет только преобразования, сохраняющие поведение корректного JavaScript. Проблемы обычно возникают у кода, изучающего собственный источник через Function.prototype.toString(), или при удалении console-вызовов с реальной работой. Проверьте результат перед развёртыванием.",
  "pageText.a33aea1e": "Как удалить console.log из JavaScript?",
  "pageText.851f8ba7": "Включите «Удалить console.*» и минифицируйте. Удаляются все вызовы методов console, включая console.error и console.warn, вместе с аргументами. В сборке задайте compress.drop_console в настройках Terser.",
  "pageText.e005a375": "Почему имена переменных не сокращаются?",
  "pageText.1c73417a": "Переименование отключено, поэтому результат сохраняет читаемые идентификаторы для отладки без source maps. Сборщики обычно включают переименование для рабочей среды, экономя больше байтов.",
  "pageText.a4388952": "Можно ли минифицировать TypeScript или JSX?",
  "pageText.8bff2c76": "Нет. Terser разбирает только JavaScript; аннотации типов и JSX дают ошибку синтаксиса. Сначала скомпилируйте через tsc, esbuild, Babel или SWC, затем минифицируйте JavaScript.",
  "pageText.56b9f99f": "Что минификатор делает с кодом",
  "pageText.55103bdf": "Terser разбирает код в синтаксическое дерево, применяет сжатие и печатает без лишних пробелов. Сжатие сворачивает константы, удаляет недостижимый код и неиспользуемые локальные переменные, сокращает условия и безопасно соединяет инструкции. Поскольку код разбирается, а не редактируется regex, строки, регулярные выражения и шаблонные литералы сохраняются. Например, function add(a, b) { return a + b; } // sum становится function add(a,b){return a+b}, а const ok = true; — const ok=!0; при сокращении логических значений.",
  "pageText.0ee8f397": "Объяснение настроек",
  "pageText.0a5da22e": "Удаление комментариев: удаляет все комментарии, включая баннеры лицензий /*! */. Отключите для сохранения всех, например если лицензия требует уведомления вместе с кодом.",
  "pageText.3fbd5c3f": "Удаление console.*: убирает console.log, console.warn, console.error вместе с аргументами; не полагайтесь на побочные эффекты внутри этих вызовов.",
  "pageText.d5ef0e31": "Удаление debugger: убирает инструкции debugger.",
  "pageText.0f7a6693": "Сокращение логических значений: переписывает true, false как !0, !1 и упрощает логические выражения.",
  "pageText.281f8120": "Чего инструмент не делает",
  "pageText.c178c0f1": "Он не переименовывает переменные, поэтому результат больше обычной рабочей сборки, но проще для отладки.",
  "pageText.c4a6b403": "Он не создаёт source maps и не собирает импорты других файлов.",
  "pageText.d46a72e1": "Он принимает только JavaScript; TypeScript и JSX нужно сначала скомпилировать.",
  "pageText.059e3a00": "Он не преобразует современный синтаксис для старых браузеров. Optional chaining, поля классов и подобные возможности сохраняются; при необходимости используйте Babel или esbuild с целевой средой.",
  "pageText.f406cb39": "Форматирование — простая переразметка с переносами после скобок и точек с запятой. Оно для быстрого чтения, может неверно обработать комментарии и регулярные выражения и не заменяет Prettier.",
  "pageText.853950f8": "Как читать статистику размера",
  "pageText.07b3482d": "Исходный и минифицированный размеры — число символов текста; процент уменьшения их сравнивает. Реальная экономия передачи обычно меньше: серверы обычно отправляют JavaScript с gzip или Brotli, уже уменьшающими пробелы и повторяющиеся идентификаторы. Для точных чисел измеряйте сжатый размер собранного файла.",
  "pageText.c9a86f33": "Что делает форматировщик?",
  "pageText.7b99d384": "Он разбивает теги, комментарии и текст на токены, затем добавляет отступы и переносы вокруг распознанных блоков. Это помощь чтению, а не HTML-парсер, валидатор, очиститель или движок браузера.",
  "pageText.8c60e5e5": "Можно ли выбрать размер отступа?",
  "pageText.f45f1451": "Да! Можно выбрать 2, 4 или 8 пробелов.",
  "pageText.b5dc2f5c": "Исправляет ли форматирование некорректный или опасный HTML?",
  "pageText.6bd5634a": "Нет. Оно не исправляет несовпадающие теги, не проверяет атрибуты, не удаляет скрипты и не доказывает безопасность разметки. Для корректности или недоверенного содержимого используйте HTML-валидатор и подходящий контексту очиститель.",
  "pageText.6853bf2a": "Что меняет форматировщик HTML",
  "pageText.59f55f70": "Он разносит обычные блочные теги по читаемым строкам, сохраняет известные встроенные элементы с окружающим текстом, сохраняет комментарии и задаёт вложенным структурам выбранный отступ. Панель результата сообщает число символов и строк для сравнения с вводом.",
  "pageText.5bc49953": "Форматировщик, парсер и валидатор",
  "pageText.28eb81f1": "Форматирование меняет пробелы и расположение; оно не строит DOM браузера и не применяет алгоритм разбора HTML.",
  "pageText.a285b9fa": "Несовпадающие, пропущенные или повреждённые теги не исправляются и могут дать неверные отступы.",
  "pageText.506549f7": "Скрипты, атрибуты обработчиков событий, опасные URL и другое активное содержимое сохраняются текстом. Форматирование не является очисткой.",
  "pageText.525714f9": "Встроенные script, style, template, SVG или атрибуты с угловыми скобками могут выходить за возможности простого токенизатора и требуют инструмента с парсером.",
  "pageText.4a57b0bb": "Ограничения пробелов и конфиденциальности",
  "pageText.3ede26b8": "Пробелы могут быть значимы в форматированном тексте, встроенных потоках, шаблонах, письмах и директивах фреймворков. Сравните поведение целевого браузера или шаблонизатора до замены рабочего источника. Форматирование локально; редактор не выполняет вставленный HTML, но история буфера обмена, расширения и дальнейшее место использования — отдельные пути раскрытия.",
  "pageText.bbd35cbf": "Минификатор удаляет комментарии HTML и сжимает пробелы. Можно выбрать применяемые настройки.",
  "pageText.f78988ed": "Насколько можно уменьшить HTML?",
  "pageText.de2adbe4": "Минификация обычно уменьшает размер HTML на 10–30% в зависимости от исходного форматирования и числа комментариев.",
  "pageText.dc1d729a": "Какие возможности XML поддерживаются?",
  "pageText.aa014daa": "Токенизатор распознаёт обычные и самозакрывающиеся теги, комментарии, CDATA, инструкции обработки и простые DOCTYPE. Он не разрешает схемы, пространства имён, сущности или внешние ресурсы DTD.",
  "pageText.e249844a": "Проверяется ли корректность структуры XML?",
  "pageText.c291f4c2": "Нет. Он форматирует похожую на токены разметку без соответствующего стандарту разбора XML. Используйте XML-парсер или валидатор для несовпадений тегов, недопустимых имён, ошибок сущностей, схем и пространств имён.",
  "pageText.40d2ec46": "Что меняет форматировщик XML",
  "pageText.ac2829ba": "Он проходит распознаваемые теги и содержимое XML, уменьшает отступ перед закрывающим тегом, увеличивает после открывающего и сохраняет самозакрывающиеся теги, комментарии, CDATA, инструкции обработки и простые DOCTYPE. Можно выбрать два, четыре или восемь пробелов без отправки документа на сервер.",
  "pageText.df3aac91": "Форматирование не является проверкой XML",
  "pageText.54105db0": "Инструмент не проверяет единственный корень, совпадение имён тегов, допустимость атрибутов, привязки пространств имён, объявления сущностей, XSD, DTD или бизнес-правила.",
  "pageText.ebba6da6": "Отформатированный результат может остаться некорректным XML; проверьте его парсером и схемой системы назначения.",
  "pageText.53dced72": "Сложные внутренние подмножества DTD и необычная разметка с > внутри объявлений могут превышать возможности простого токенизатора.",
  "pageText.6dda43fb": "Внешние сущности не разрешаются, что исключает их загрузку, но не проверяет зависимую от них корректность.",
  "pageText.97f2bab3": "Смешанное содержимое, подписи и конфиденциальность",
  "pageText.14bd67e8": "Форматировщик обрезает текстовые токены и вставляет пробелы, поэтому документы со смешанным содержимым и значимыми пробелами требуют проверки. Не форматируйте канонизированный или подписанный XML: любое изменение байтов может нарушить подпись. Обработка локальна; история буфера обмена, расширения, общие устройства и место вставки остаются отдельными рисками.",
  "pageText.fe32a91d": "Насколько минификация уменьшает SVG?",
  "pageText.5d39171c": "В зависимости от метаданных редактора Adobe Illustrator, Inkscape и лишних комментариев файлы SVG часто уменьшаются на 30–70%.",
  "pageText.96ecd07b": "Влияет ли минификация на качество изображения?",
  "pageText.a917f319": "Нет. Минификатор сохраняет важные векторы и кривые, округляя избыточные многозначные десятичные числа для точной отрисовки.",
  "pageText.b7b3cc9a": "Какие метаданные удаляются при оптимизации?",
  "pageText.66896ba8": "Оптимизатор удаляет объявления XML, заголовки DOCTYPE, HTML/XML-комментарии и атрибуты редакторов Adobe Illustrator, Figma, Inkscape и Sketch.",
  "pageText.78172982": "Можно ли посмотреть оптимизированный SVG до скачивания?",
  "pageText.390681e1": "Да, под редактором отображается отрисованный SVG для проверки качества.",
  "pageText.0b1fe2c2": "Меняет ли минификация SQL логику или результаты запроса?",
  "pageText.e4ef1b07": "Нет. Она лишь удаляет невыполняемые комментарии и сжимает пробелы вокруг операторов и скобок.",
  "pageText.9b592f46": "Зачем минифицировать JSON?",
  "pageText.ed32b385": "Минифицированный JSON уменьшает передачу байтов на 20–50%, ускоряя ответы API и снижая стоимость хранения.",
  "pageText.c0fed95c": "Насколько можно уменьшить изображение?",
  "pageText.e029d2f5": "В зависимости от изображения и формата, например WebP, обычно можно сократить размер файла на 50–80%.",
  "pageText.9d6eb265": "Да! Всё обрабатывается локально в браузере без загрузки на сервер.",
  "pageText.9da1e25c": "Как работает извлечение палитры?",
  "pageText.6856aaf1": "Оно выбирает данные пикселей изображения и группирует цвета в преобладающие кластеры через быструю квантизацию цвета.",
  "pageText.a4364887": "Можно ли проверить отдельные пиксели?",
  "pageText.f7f9cfc5": "Да, нажмите в любом месте предпросмотра для выбора точного цвета пипеткой.",
  "pageText.a35b5925": "Безопасно ли объединять конфиденциальные PDF?",
  "pageText.05bdd01e": "Да, DevsTools полностью локально объединяет PDF в браузере через pdf-lib. Документы никогда не загружаются на сервер.",
  "pageText.61e14c97": "Можно ли изменить порядок объединяемых PDF?",
  "pageText.8d1a28fb": "Да, используйте стрелки вверх и вниз для упорядочения файлов до объединения.",
  "pageText.0d93721b": "Как указать диапазоны разделения страниц?",
  "pageText.a635c961": "Введите диапазоны «1-3, 5, 8-10» или используйте кнопки быстрых шаблонов.",
  "pageText.478026f0": "Влияет ли разделение на качество документа?",
  "pageText.343ad06a": "Нет, векторный текст, встроенные изображения и шрифты сохраняют исходное качество.",
  "pageText.3832da18": "Какие модели включены в сравнение?",
  "pageText.d5944039": "GPT-4o, GPT-4o-mini, o1, o3-mini, Claude 3.5 Sonnet/Haiku/Opus, Gemini 2.0 Flash, Gemini 1.5 Pro, DeepSeek V3/R1 и Llama 3.3.",
  "pageText.2c0b42c9": "Рассчитываются ли скидки кеширования промптов?",
  "pageText.1f24b0e5": "Да, настройте процент кеширования ползунком, чтобы увидеть сниженные цены входных токенов.",
  "pageText.b55124a7": "Поддерживает ли изолированная среда Tailwind CSS?",
  "pageText.3c96d97b": "Да, выберите шаблон Tailwind для автоматического подключения Tailwind CDN.",
  "pageText.eea9bb11": "Можно ли экспортировать проект изолированной среды?",
  "pageText.22043773": "Да, нажмите «Экспортировать HTML» для скачивания самостоятельного однофайлового документа.",
  "pageText.08df7b07": "Какой формат использует инструмент?",
  "pageText.d6dda949": "Числовой Cronie из 5 полей: минута (0–59), час (0–23), день месяца (1–31), месяц (1–12), день недели (0–7, где 0 и 7 — воскресенье). Имена месяцев и дней и случайные значения через тильду не поддерживаются.",
  "pageText.3ef8cae4": "Что означает */5 * * * *?",
  "pageText.8b55b7bf": "Запуск каждые пять минут: в :00, :05, :10 и так далее до :55 каждого часа ежедневно.",
  "pageText.14555971": "Как запускать cron ежедневно в полночь?",
  "pageText.555d6847": "Используйте 0 0 * * *. Первое поле — минута, второе — час, поэтому запуск происходит в 00:00 по часовому поясу компьютера с cron.",
  "pageText.ebbbedb4": "Почему задание запускается чаще ожидаемого по дням?",
  "pageText.dd287a29": "Если ограничены день месяца и день недели, cron запускает при совпадении любого. 0 9 1 * 1 запускается 1-го числа каждого месяца и каждый понедельник. Установите одно из двух полей в *, чтобы использовать только другое.",
  "pageText.4c325954": "Какой часовой пояс используют задания cron?",
  "pageText.1999379a": "Классический crontab использует системный пояс сервера, часто UTC. Kubernetes CronJob может задать spec.timeZone, расписания GitHub Actions работают в UTC. Инструмент показывает запуски в поясе браузера.",
  "pageText.05cc7746": "Поддерживаются ли @daily, секунды, L и W?",
  "pageText.df473d06": "Нет. Макросы @daily и @reboot, поле секунд или года и символы Quartz ?, L, W, # отклоняются. Запишите @daily как 0 0 * * *.",
  "pageText.1fd13551": "Чтение пяти полей cron",
  "pageText.33035464": "Стандартный crontab содержит пять полей через пробел: минута (0–59), час (0–23), день месяца (1–31), месяц (1–12), день недели (0–7, где 0 и 7 — воскресенье). Команда после расписания в строке crontab не входит в выражение, вставляйте только пять полей. Например, 30 2 * * 1 запускается в 02:30 по понедельникам, а 0 9 * * 1-5 — в 09:00 с понедельника по пятницу. Каждое поле принимает четыре оператора:",
  "pageText.016be4a0": "* совпадает с любым значением поля.",
  "pageText.0fb5d225": "Запятая создаёт список: 0,30 в поле минут запускает в :00 и :30.",
  "pageText.f7efe16b": "Дефис создаёт включительный диапазон: 9-17 в поле часов охватывает с 09:00 до 17:00.",
  "pageText.0745593a": "Косая черта добавляет шаг к * или диапазону: */15 — каждые 15 минут, 8-18/2 — каждый второй час от 8 до 18.",
  "pageText.1e8af08c": "День месяца и недели: правило ИЛИ",
  "pageText.71a25a12": "Если оба поля дней ограничены, cron запускается при совпадении любого, а не только обоих. Поэтому 0 0 13 * 5 запускается в полночь 13-го числа каждого месяца и по пятницам, а не лишь в пятницу 13-го. Если одно поле начинается с *, включая шаг */2, поля объединяются через И. Парсер следует правилу Cronie и Vixie cron, а список следующих запусков сразу показывает эффект.",
  "pageText.c0ab4e56": "Как рассчитываются следующие запуски",
  "pageText.79d9be29": "Пять следующих запусков рассчитываются в браузере по текущему часовому поясу устройства и показываются с сокращением пояса. Серверы обычно используют свой пояс, часто UTC, поэтому показанный здесь запуск в 09:00 может иметь другое местное время на сервере. Переход на летнее время может пропустить время, например 02:30 весной, или повторить осенью. Предпросмотр показывает каждое реальное местное вхождение; проверьте обработку переходов вашим cron.",
  "pageText.71055715": "Отклоняемый синтаксис",
  "pageText.941d3d4e": "Имена месяцев и дней, например JAN, MON; используйте числа 1–12 и 0–7.",
  "pageText.1155fe27": "Макросы @hourly, @daily и @reboot.",
  "pageText.aac0ad9e": "Расширения Quartz и Spring: поле секунд или года, ?, L, W, #.",
  "pageText.eb78245f": "Шаг на одном значении, например 5/10; используйте 5-59/10.",
  "pageText.a20b5d46": "Случайные значения H в стиле Jenkins или ~ некоторых версий cron.",
  "pageText.01e5036b": "Можно ли разбирать повторяющиеся заголовки?",
  "pageText.a5eb4734": "Да. Повторяющиеся ключи заголовков группируются массивами в JSON-результате.",
  "pageText.48b8738b": "Какой формат ввода ожидается?",
  "pageText.b75acdab": "По одному заголовку в строке в формате «Header-Name: value».",
  "pageText.3d8017de": "Что такое коды состояния HTTP?",
  "pageText.f49da83d": "Это стандартные ответы сервера, показывающие успех, ошибку или перенаправление запроса.",
  "pageText.09b5ad7b": "Какие классы кодов состояния существуют?",
  "pageText.ed562809": "1xx — информационные, 2xx — успех, 3xx — перенаправления, 4xx — ошибки клиента, 5xx — ошибки сервера.",
  "pageText.fc679ed8": "Насколько точен разбор UA?",
  "pageText.8d6134ab": "Инструмент использует встроенные правила UAParser.js 1.0.41, но результаты эвристические: строки User-Agent сообщаются самим клиентом, сокращаются и могут подделываться.",
  "pageText.14c11e52": "Можно ли обнаружить ботов?",
  "pageText.ac1e7ccc": "Он распознаёт распространённые именованные токены поисковых и ИИ-роботов и применяет резервную эвристику bot/crawler/spider. Неизвестный или замаскированный робот может быть пропущен.",
  "pageText.28488b1d": "Можно ли разобрать несколько User-Agent?",
  "pageText.f540646b": "Да. Включите пакетный режим и вставьте по одной строке User-Agent в строку для получения массива результатов JSON.",
  "pageText.964b16b5": "Что возвращает онлайн-парсер user-agent",
  "pageText.9d61821a": "Вставьте строку user-agent либо включите пакетный режим по одной строке для разбора имени и версии браузера, ОС, движка, производителя, модели и типа устройства, архитектуры CPU и признаков ботов. RFC 9110 определяет User-Agent как поле запроса с идентификаторами продуктов и необязательными комментариями о ПО отправителя. Инструмент читает сообщённые токены; он не обращается к устройству и не изучает отправивший их браузер.",
  "pageText.32c1543c": "Как работает распознавание",
  "pageText.080c4d60": "Встроенные правила UAParser.js 1.0.41 применяют в браузере регулярные выражения для браузера, движка, ОС, устройства и CPU.",
  "pageText.c680aa0e": "Результат показывает версии, производителя и модель, когда вставленная строка содержит достаточно сведений.",
  "pageText.954982d4": "Отдельный слой ботов распознаёт Googlebot, Bingbot, OAI-SearchBot, GPTBot, PerplexityBot, ClaudeBot и Applebot, затем применяет резервные ключевые слова роботов.",
  "pageText.ddc447f4": "«Использовать мой User-Agent» читает navigator.userAgent этого браузера; пакетный режим разбирает по одной вставленной строке.",
  "pageText.ef145930": "Точность и ограничения",
  "pageText.1f7dae65": "Считайте результат подсказкой, а не подтверждённой личностью. User-agent можно менять и подделывать, токены совместимости могут называть несколько браузеров, сокращённые строки — опускать версии и устройство. Неизвестные значения остаются Unknown, а нераспознанная немобильная строка получает Desktop. Боты тоже определяются эвристически: неизвестный или скрытый робот пропускается, а обычный продукт с ключевым словом робота может отмечаться. Client Hints и проверка возможностей дают иные или более полезные признаки, если вы управляете приложением.",
  "pageText.22aebc3c": "Конфиденциальность и безопасное применение",
  "pageText.2ae8ed4d": "Разбор выполняется в браузере при вводе. Данные не отправляются в API, но user-agent вместе с другими данными может участвовать в идентификации отпечатка. Не используйте результат как аутентификацию, авторизацию, доказательство мошенничества или замену проверке возможностей.",
  "pageText.0381d4bc": "Какие форматы ввода поддерживаются?",
  "pageText.e1375844": "Введите канонический IPv4 в десятичной записи с точками и префикс /24 либо непрерывную маску 255.255.255.0.",
  "pageText.245b4291": "Как обрабатываются сети /31 и /32?",
  "pageText.683e314e": "/31 показывается в трактовке RFC 3021 для соединения точка-точка: оба конца доступны, широковещательного адреса нет; подтвердите поддержку целевым соединением. /32 — маршрут одного узла, тоже без широковещательного адреса.",
  "pageText.c6d33e69": "Поддерживает ли калькулятор IPv6?",
  "pageText.a3da1f3e": "Нет. Эта версия намеренно проверяет лишь IPv4, чтобы смысл адресов и диапазонов узлов оставался явным.",
  "pageText.790f8f4a": "Что возвращает калькулятор IPv4 CIDR",
  "pageText.d1b4b69d": "CIDR объединяет адрес IPv4 с длиной префикса — числом начальных битов сети. Калькулятор нормализует ввод к канонической сети и показывает широковещательную границу, маску с точками, обратную маску, общее число адресов и диапазон доступных узлов.",
  "pageText.1d5581a7": "Строгий ввод и граничные случаи",
  "pageText.f2babb34": "IPv4 должен содержать четыре десятичных октета 0–255; неоднозначные ведущие нули и сокращённые формы отклоняются.",
  "pageText.de8ed2ff": "Поддерживаются префиксы /0–/32 и непрерывные маски в десятичной записи с точками.",
  "pageText.238148ff": "Для /0–/30 сеть и широковещательная граница исключаются из диапазона доступных узлов.",
  "pageText.678c186b": "Для /31 оба конца соединения точка-точка доступны по RFC 3021; /32 — маршрут одного узла.",
  "pageText.08e319a3": "Эксплуатационные границы",
  "pageText.16280f4e": "Результат описывает арифметику адресов, а не доступность маршрутизации, правила межсетевого экрана, выделение DHCP, резервы облачного провайдера, принадлежность VLAN или публичную маршрутизируемость. Перед выделением адресов применяйте правила целевой сетевой платформы.",
  "pageText.43b9f352": "Что означают 755 и 644?",
  "pageText.244efe25": "Каждая восьмеричная цифра объединяет чтение (4), запись (2) и выполнение (1). 755 — rwxr-xr-x, 644 — rw-r--r--.",
  "pageText.0a65a354": "Что такое биты setuid, setgid и sticky?",
  "pageText.3c3c8484": "Это особые биты режима в начальной восьмеричной цифре. Точное влияние на безопасность зависит от типа объекта, ОС, файловой системы, настроек монтирования и контекста выполнения.",
  "pageText.d9d32a1e": "Меняет ли инструмент файл?",
  "pageText.b0c7d669": "Нет. Он лишь рассчитывает и копирует запись разрешений; он не может читать или изменять файловую систему.",
  "pageText.ad18866f": "Как работает калькулятор chmod",
  "pageText.47cea64b": "Режимы разрешений Unix группируют биты чтения, записи и выполнения для владельца, группы и остальных. Сумма битов даёт восьмеричную цифру: чтение 4, запись 2, выполнение 1. Калькулятор синхронизирует восьмеричную запись, rwx и флажки.",
  "pageText.c281eef7": "Избегайте широких разрешений на запись, например 777, если конкретная модель угроз и среда не требуют их.",
  "pageText.81ae01d1": "Режим не показывает владельца файла, ACL, возможности capabilities, правила SELinux или AppArmor, флаги монтирования, сопоставления контейнеров и унаследованные политики.",
  "pageText.a50e1c4a": "Заглавная S или T означает, что специальный бит установлен, а соответствующий бит выполнения — нет.",
  "pageText.ba30cf48": "Проверьте целевой путь и владельца перед запуском любой скопированной команды chmod, особенно рекурсивной.",
  "pageText.57ae6fe2": "Чем отличаются no-cache и no-store?",
  "pageText.856cc543": "no-cache допускает хранение ответа, но требует проверки перед повторным использованием. no-store указывает кешам не хранить ответ. Эти директивы не взаимозаменяемы.",
  "pageText.a24540f5": "Что регулирует s-maxage?",
  "pageText.07c63451": "s-maxage задаёт срок актуальности для общих кешей и имеет в них приоритет над max-age. Поведение браузера и частного кеша при этом может отличаться.",
  "pageText.47165661": "Может ли этот инструмент гарантировать поведение CDN?",
  "pageText.4736a111": "Нет. Он проверяет синтаксис и отмечает распространённые конфликты, но фактическое поведение зависит от полного ответа, директив запроса, реализации кеша, политики CDN, настроек фреймворка по умолчанию и состояния аннулирования кеша.",
  "pageText.ca31e679": "Что проверяет инструмент Cache-Control",
  "pageText.7a512319": "Парсер разделяет директивы по запятым, не разбивая значения в кавычках, нормализует имена директив, удаляет повторяющиеся имена в форматированном выводе и предупреждает о распространённых конфликтах, например сочетании public с private или нечисловых значениях срока актуальности.",
  "pageText.be225eb9": "Ограничения при эксплуатации",
  "pageText.cd535d5c": "Семантика Cache-Control различается в запросах и ответах; готовые настройки служат примерами для ответов.",
  "pageText.ae842969": "Корректный заголовок не отменяет все правила CDN, заголовки суррогатного кеша, кеш фреймворка, сервис-воркер, эвристики браузера или явную очистку.",
  "pageText.12ea33ca": "immutable лучше всего подходит для версионированных ресурсов, URL которых меняется при каждом изменении содержимого.",
  "pageText.819756b2": "Не кешируйте персонализированные или конфиденциальные ответы в общедоступных кешах без полной проверки аутентификации, Vary, файлов cookie и поведения промежуточных узлов.",
  "pageText.8fc53dd8": "Может ли анализатор доказать безопасность CSP?",
  "pageText.6bdde330": "Нет. Он отмечает распространённые статические проблемы, но не способен учесть все сценарии приложения, поведение браузера, жизненный цикл nonce, сторонние интеграции, адреса отправки отчётов и способы обхода защиты в приложении.",
  "pageText.00ae173a": "Почему стоит начинать с режима Report-Only?",
  "pageText.487cd4a8": "Content-Security-Policy-Report-Only регистрирует нарушения, не применяя ограничения политики. Это помогает выявить необходимые ресурсы перед включением ограничений, хотя отчёты всё равно требуют внимательной проверки и могут содержать конфиденциальные URL.",
  "pageText.1828ef21": "Что происходит с повторяющимися директивами?",
  "pageText.b8228f81": "Браузеры используют первое вхождение и игнорируют последующие повторения директивы. Анализатор сообщает о повторах, а нормализованный вывод конструктора сохраняет одну явно заданную директиву.",
  "pageText.18b89636": "Что проверяет конструктор CSP",
  "pageText.c8f0e194": "Content Security Policy ограничивает источники, из которых документ может загружать или выполнять ресурсы. Инструмент разбирает директивы, разделённые точкой с запятой, нормализует их значения, выявляет повторы и отмечает распространённые риски, например слишком широкие источники скриптов, скрипты data:, 'unsafe-eval' и 'unsafe-inline' без nonce или хеша.",
  "pageText.8bc2d491": "Базовые директивы и выявленные проблемы",
  "pageText.6a15b338": "default-src задаёт резервное значение для директив загрузки ресурсов, которые не объявлены явно.",
  "pageText.aa0c2e7c": "object-src 'none' блокирует содержимое устаревших плагинов, если приложению оно не требуется.",
  "pageText.18e827de": "base-uri ограничивает изменения базового URL документа, а frame-ancestors определяет, какие родительские страницы могут встраивать эту страницу.",
  "pageText.4033496a": "Синтаксически корректная политика всё равно может нарушить работу в рабочей среде или разрешить небезопасный сценарий. Отдельно проверьте необходимые источники, nonce, хеши, воркеры, фреймы, формы и отправку отчётов.",
  "pageText.190ec910": "Порядок безопасного развёртывания",
  "pageText.ae9648e1": "Начните с проекта политики с минимальными привилегиями, разверните его как Content-Security-Policy-Report-Only, пройдите реальные сценарии приложения и изучите нарушения. Удалите случайные зависимости или добавьте самые узкие необходимые источники, затем включите проверенную политику. Храните заголовок в системе контроля версий и повторно проверяйте его при изменении фреймворков, CDN, аналитики, рекламы и сценариев аутентификации.",
  "pageText.d68c4d88": "Выполняет ли инструмент команду cURL?",
  "pageText.74f4df78": "Нет. Он только разбивает поддерживаемый ввод на токены и генерирует текст. Он никогда не запускает оболочку, не обращается к целевому URL и не отправляет заголовки или тело запроса.",
  "pageText.48e8b2e0": "Какие параметры cURL можно преобразовать?",
  "pageText.2aedeaa5": "Конвертер обрабатывает распространённые параметры запроса, включая метод, URL, заголовки и данные, а также безопасные флаги перенаправления и сжатия. Неподдерживаемые или неоднозначные возможности оболочки отклоняются, а не интерпретируются предположительно.",
  "pageText.159eff58": "Всегда ли cURL и fetch эквивалентны?",
  "pageText.dde74409": "Нет. Перенаправления, файлы cookie, TLS, прокси, сжатие, потоковая передача, CORS, запрещённые браузером заголовки, учётные данные и загрузка multipart могут работать по-разному. Проверьте и протестируйте сгенерированный код в его реальной среде выполнения.",
  "pageText.ec80b478": "Что делает конвертер cURL и fetch",
  "pageText.68449604": "Конструктор запроса преобразует структурированный ввод метода, URL, параметров запроса, заголовков и тела в команду cURL с экранированием для оболочки POSIX и пример JavaScript fetch. Конвертер разбивает поддерживаемую вставленную команду cURL на токены без выполнения, затем переводит данные запроса в синтаксис fetch.",
  "pageText.cee22a22": "Ограничения разбора и безопасности",
  "pageText.a46bfb45": "Подстановки оболочки, обратные кавычки, байты NUL, некорректные кавычки, внедрение CRLF в заголовки и неподдерживаемые параметры отклоняются.",
  "pageText.a46b5014": "Конфиденциальные значения Authorization, Cookie, авторизации прокси и ключей API можно скрыть в сгенерированном выводе; в интерфейсе они скрыты по умолчанию.",
  "pageText.b759e2e1": "Экранирование для оболочки POSIX отличается от экранирования PowerShell и Windows cmd. Учитывайте целевую оболочку перед запуском скопированного текста.",
  "pageText.d923e0c4": "Повторяющиеся заголовки запроса могут объединяться в Fetch Headers API; сгенерированный фрагмент отмечает повторяющиеся имена для ручной проверки.",
  "pageText.6518c723": "Инструмент не отправляет запросы, не проверяет удалённый сервер, не хранит учётные данные и не доказывает, что скопированные секреты защищены от расширений, скриптов страницы, истории буфера обмена или демонстрации экрана.",
  "pageText.a52cbc62": "Почему сгенерированный fetch может потребовать изменений",
  "pageText.a0b2fa3c": "Браузерный fetch применяет правила CORS и запрещённых заголовков, которые не действуют в клиенте curl командной строки. Серверный JavaScript использует другую среду файлов cookie, прокси и TLS. Загрузка форм multipart, потоковые тела запросов, клиентские сертификаты, собственное разрешение DNS и специфические повторные попытки curl требуют кода для конкретной среды выполнения сверх прямого преобразования.",
  "pageText.92e93e00": "Какие коэффициенты контрастности WCAG требует для текста?",
  "pageText.71cfc9b4": "Для большинства текстов AA требует не менее 4.5:1, а AAA — 7:1. Для крупного текста применяются 3:1 для AA и 4.5:1 для AAA. Крупным считается обычный текст размером не менее 18 пунктов или полужирный размером не менее 14 пунктов; обычно это приблизительно 24 пикселя CSS или около 18.66 пикселя CSS для полужирного текста.",
  "pageText.76601b6f": "Что означает результат для компонентов интерфейса?",
  "pageText.88ec1351": "Он применяет порог 3:1, обычно используемый для визуальной информации, необходимой для распознавания компонентов интерфейса и графических объектов. Применимость зависит от состояния, границ, соседних цветов и того, нужен ли этот визуальный элемент для понимания интерфейса или работы с ним.",
  "pageText.f6c937f8": "Делает ли достаточный коэффициент контрастности весь дизайн доступным?",
  "pageText.c55058e2": "Нет. Контрастность — лишь одно из требований. Толщина, размер и интервалы шрифта, состояния наведения и фокуса, градиенты, изображения, особенности цветового зрения, масштабирование, принудительные цвета и передача информации без цвета требуют отдельных проверок.",
  "pageText.bd34b3a3": "Как рассчитывается коэффициент контрастности",
  "pageText.93057296": "Каждый непрозрачный канал sRGB преобразуется из закодированного значения в линейный свет, объединяется с коэффициентами относительной яркости WCAG и сравнивается по формуле (lighter + 0.05) / (darker + 0.05). Коэффициент изменяется от 1:1 для одинаковой яркости до 21:1 для чёрного и белого. Перестановка цвета переднего плана и фона не меняет числовой коэффициент.",
  "pageText.587b353d": "AA, AAA и предпросмотр в реальном времени",
  "pageText.a7a29b7f": "Обычный текст соответствует AA при 4.5:1 и AAA при 7:1.",
  "pageText.4a22824d": "Крупный текст соответствует AA при 3:1 и AAA при 4.5:1.",
  "pageText.6232d70c": "Образец интерфейса показывает нетекстовый порог 3:1, не предполагая, что ему должна соответствовать каждая видимая граница.",
  "pageText.25adca33": "Рекомендация выбирает непрозрачный чёрный или белый цвет в зависимости от того, у какого из них выше коэффициент относительно текущего фона; она не сохраняет замысел фирменного оформления.",
  "pageText.3543a31e": "Предпросмотр помогает заметить очевидные проблемы читаемости, но не заменяет проверку отображаемого продукта при его реальных размерах и состояниях.",
  "pageText.1aad56b9": "Ограничения цвета и отображения",
  "pageText.e945b142": "Калькулятор принимает трёх- или шестизначные непрозрачные шестнадцатеричные цвета sRGB. Альфа-прозрачность, градиенты, изображения, режимы наложения, калибровка дисплея, сглаживание, цвета с широким охватом и текст поверх меняющегося содержимого требуют оценки итоговых составных пикселей. Обработка выполняется локально и не получает цвета с другой веб-страницы автоматически.",
  "pageText.23984f68": "Какие версии OpenAPI поддерживаются?",
  "pageText.a8bb0e10": "Структурный анализатор принимает строки версий OpenAPI 3.0, 3.1 и 3.2. Swagger 2.0 отмечается как неподдерживаемый, без автоматического преобразования.",
  "pageText.052ac5a9": "Загружаются ли внешние документы $ref?",
  "pageText.a9423d78": "Нет. Локальные ссылки на фрагменты, начинающиеся с #, разрешаются внутри вставленного документа. Ссылки на файлы и сетевые ресурсы перечисляются в предупреждениях, но никогда не загружаются, что сохраняет локальную обработку и исключает скрытые сетевые обращения.",
  "pageText.0aa9d75d": "Гарантирует ли корректный результат полное соответствие OpenAPI?",
  "pageText.66286acc": "Нет. Это специализированный структурный анализатор, а не официальная схема вместе со всеми семантическими правилами. Перед публикацией контракта API используйте в CI валидатор для конкретной версии и целевой генератор или шлюз.",
  "pageText.df996466": "Что проверяет структурный валидатор",
  "pageText.4c230715": "Парсер принимает JSON или YAML с ограничениями объёма, требует версию OpenAPI 3, название и версию в info и объект paths, затем собирает стандартные операции HTTP. Он сообщает об отсутствующих responses, повторяющихся идентификаторах операций, несопоставленных или необязательных параметрах шаблона пути, необычных ключах ответа, неразрешённых локальных ссылках, неподдерживаемых корневых версиях и неизвестных полях Path Item.",
  "pageText.c33b24c7": "Как обозреватель конечных точек описывает контракт",
  "pageText.bd67021b": "Каждая строка показывает метод, путь, краткое описание, operationId, ключи ответов, отметку устаревания и действующее состояние безопасности.",
  "pageText.af6d9ec9": "Настройки security на уровне операции переопределяют корневые настройки; пустой массив security отображается как явно общедоступный доступ.",
  "pageText.f6c0ea2a": "Поиск охватывает путь, краткое описание, operationId и теги, а выбор метода сужает список видимых операций.",
  "pageText.f6b3cb96": "Нормализованное представление JSON позволяет проверить результаты разбора YAML и объединённые псевдонимы.",
  "pageText.39b0dc9b": "Внешние ссылки подсчитываются и отображаются без каких-либо запросов из браузера.",
  "pageText.477e1f43": "Ограничения проверки и безопасности",
  "pageText.aa9a6db6": "Структурно корректный документ всё равно может содержать несовместимые схемы, неверные примеры, неработающие обратные вызовы, неправильные типы содержимого, расширения конкретного генератора, непригодные сценарии аутентификации или бизнес-поведение, не соответствующее реализации. Разрешение локальных $ref проверяет существование ссылок, но не полностью раскрывает их во всех семантических контекстах. Глубина YAML, псевдонимы, развёртывание слияний и общий размер ввода ограничены, чтобы сохранять отзывчивость браузера.",
  "pageText.e8aa500a": "Что такое SPF и зачем он нужен?",
  "pageText.3a448f2b": "SPF (Sender Policy Framework) — это запись DNS TXT, в которой перечислены почтовые серверы, уполномоченные отправлять письма от имени вашего домена.",
  "pageText.101baaa1": "Что такое DMARC?",
  "pageText.5c6e3f51": "DMARC (Domain-based Message Authentication, Reporting, and Conformance) использует SPF и DKIM, чтобы сообщить принимающим серверам, как обрабатывать письма, не прошедшие аутентификацию.",
  "pageText.db14ea51": "Какие языки программирования и библиотеки HTTP поддерживаются?",
  "pageText.cd3899b9": "Инструмент генерирует код для JavaScript (Fetch API и Axios), Python (библиотека Requests), Go (стандартный net/http), PHP (curl_init) и Rust (асинхронный reqwest).",
  "pageText.7db0a8b2": "Выполняет ли это мой запрос cURL или отправляет его через интернет?",
  "pageText.95abcd54": "Нет. Команда разбирается и разделяется на токены полностью локально в вашем браузере для генерации кода. Ничего не отправляется и не выполняется.",
  "pageText.125a50e9": "Что такое многоэтапная сборка Docker?",
  "pageText.7a608e37": "Многоэтапные сборки используют отдельные промежуточные контейнеры для компиляции и рабочей среды выполнения, значительно уменьшая размер итогового образа и исключая зависимости сборки из рабочей среды.",
  "pageText.c322990e": "Запускается ли сгенерированный Dockerfile от пользователя без прав root?",
  "pageText.585c03a7": "Да, где это применимо, сгенерированный Dockerfile настраивает отдельного пользователя без прав root (например, USER node или appuser) согласно рекомендациям по безопасности контейнеров.",
  "pageText.4adfa17f": "Какие свойства CSS создают эффект глассморфизма?",
  "pageText.cb13b4db": "Глассморфизм создаётся с помощью backdrop-filter: blur(), полупрозрачного фона (rgba), тонких белых границ (rgba) и теней box-shadow, придающих объём.",
  "pageText.78f35ba1": "Поддерживается ли backdrop-filter во всех современных браузерах?",
  "pageText.afdcf83f": "Да, backdrop-filter поддерживается во всех современных браузерах (Chrome, Edge, Safari, Firefox). Для максимальной совместимости добавляются префиксы поставщиков (-webkit-backdrop-filter).",
  "pageText.a0d9ac95": "Какие единицы можно использовать для столбцов и строк?",
  "pageText.0d74534d": "Можно задать гибкие дробные единицы (fr), точные размеры в пикселях (px) или проценты (%) для максимальной адаптивности макета.",
  "pageText.85a4a549": "Можно ли скопировать и CSS, и HTML?",
  "pageText.349f7349": "Да, CSS контейнера .parent с grid-template-columns и соответствующая структура HTML генерируются одновременно.",
  "pageText.db476089": "Для чего нужен robots.txt?",
  "pageText.c4e38da5": "Файл robots.txt указывает роботам поисковых систем (Googlebot, Bingbot), к каким URL и каталогам вашего сайта им разрешён или запрещён доступ.",
  "pageText.8f3b1cb2": "Где нужно размещать файл robots.txt?",
  "pageText.f8c6a14d": "Файл robots.txt всегда должен находиться в корне домена вашего сайта (например, https://example.com/robots.txt).",
  "pageText.dadb2232": "Какие теги входят в сгенерированный XML карты сайта?",
  "pageText.0acc8ea9": "Сгенерированный XML соответствует схеме sitemaps.org 0.9 и содержит элементы <url>, <loc>, <lastmod>, <changefreq> и <priority>.",
  "pageText.972e9d03": "Как отправить эту карту в Google Search Console?",
  "pageText.6bb374e1": "Скачайте сгенерированный sitemap.xml, загрузите его в корневой каталог сайта (https://example.com/sitemap.xml) и отправьте URL в Google Search Console.",
  "pageText.912a6605": "Чем отличаются event.key и event.code?",
  "pageText.5f3e9043": "event.key возвращает значение нажатой клавиши (с учётом Shift/Caps, например \"A\" или \"a\"), а event.code обозначает физическую клавишу в раскладке клавиатуры (например, \"KeyA\").",
  "pageText.d6886318": "Почему keyCode устарел в современном JavaScript?",
  "pageText.47c83a7e": "event.keyCode работал неодинаково в разных операционных системах и раскладках, отличных от QWERTY. Современная веб-разработка использует event.key и event.code как стандарт.",
  "pageText.44aec8dc": "Как работают треугольники на чистом CSS?",
  "pageText.178348f0": "Для треугольника CSS создаётся элемент с нулевой шириной и высотой, к которому применяются толстые границы: три стороны прозрачные, а одна окрашена.",
  "pageText.4e5692e9": "Можно ли создать диагональные угловые треугольники?",
  "pageText.0633b12d": "Да! Можно выбрать одно из 8 направлений: вверх, вниз, влево, вправо, вверх-влево, вверх-вправо, вниз-влево и вниз-вправо.",
  "pageText.376bbf44": "Предоставляет ли генератор и чистый CSS, и классы Tailwind?",
  "pageText.59dce7df": "Да. Стандартные правила CSS (display: flex, justify-content, align-items, gap) и служебные классы Tailwind генерируются в реальном времени.",
  "pageText.99e78b69": "Можно ли добавлять и удалять тестовые элементы flex в песочнице?",
  "pageText.b824b684": "Да, кнопками + и - можно менять число тестовых карточек в контейнере, чтобы увидеть поведение переноса и интервалов.",
  "pageText.b1a93891": "Какие социальные платформы имитирует предпросмотр?",
  "pageText.c1f4071a": "Можно переключаться между большой карточкой изображения Twitter/X, публикацией в ленте Facebook, ссылкой в LinkedIn и фрагментом результатов поиска Google.",
  "pageText.fb1820cd": "Какое разрешение изображения Open Graph рекомендуется?",
  "pageText.da87fb9a": "Стандартный рекомендуемый размер изображения для Twitter Cards и Facebook Open Graph — 1200 × 630 пикселей (соотношение сторон 1.91:1).",
  "pageText.5141dfd9": "Какие готовые анимации доступны?",
  "pageText.1033cd43": "Доступны отскок, пульсация, вращение, тряска, появление, 3D-переворот, покачивание и увеличение.",
  "pageText.96e7dd99": "Можно ли настроить функцию изменения скорости (easing)?",
  "pageText.0aa29a50": "Да. Можно выбрать ease, linear, ease-in, ease-out или ease-in-out, а также настроить длительность и задержку в секундах.",
  "pageText.2c0cc2c1": "Можно ли добавить тексту несколько слоёв тени?",
  "pageText.8175f838": "Да. Можно добавить столько наложенных слоёв text-shadow, сколько необходимо для реалистичной глубины 3D, разноцветных ретро-контуров и многослойного неонового свечения.",
  "pageText.9ec3072a": "Есть ли готовые стили?",
  "pageText.9e6ee7e1": "Да! Одним нажатием можно применить мягкую падающую тень, неоновое свечение, объёмный 3D-текст и ретро-контур.",
  "pageText.deb09314": "Какую информацию предоставляет калькулятор подсети?",
  "pageText.6e09390f": "Он вычисляет адрес сети, широковещательный адрес, маску подсети, обратную маску, первый и последний доступные IP-адреса узлов, общее число и число доступных узлов, класс IP и 32-битные двоичные представления.",
  "pageText.f6fb6409": "Поддерживаются ли все префиксы CIDR (от /0 до /32)?",
  "pageText.eb723f55": "Да. Поддерживаются все префиксы подсети от /0 до /32, включая специальные соединения точка-точка /31 (RFC 3021) и маски одиночного узла /32.",
  "pageText.7c278231": "Какие функции фильтров CSS поддерживаются?",
  "pageText.3027f78d": "Поддерживаются blur(), brightness(), contrast(), grayscale(), hue-rotate(), invert(), saturate(), sepia() и opacity().",
  "pageText.2666dde6": "Добавляются ли префиксы поставщиков в сгенерированный CSS?",
  "pageText.45bdde19": "Да. Для максимальной совместимости браузеров выводятся стандартное свойство `filter` и свойство `-webkit-filter`.",
  "pageText.4f32f1e3": "Как работает синтаксис CSS border-radius с 8 радиусами?",
  "pageText.c08c1dc8": "Косая черта (/) отделяет горизонтальные радиусы от вертикальных: `border-radius: [TL-h] [TR-h] [BR-h] [BL-h] / [TL-v] [TR-v] [BR-v] [BL-v]`, создавая плавные органические кривые, отличные от окружностей.",
  "pageText.8ed31f5b": "Можно ли выбирать единицы в процентах (%) и пикселях (px)?",
  "pageText.974f8f3e": "Да, переключайтесь между % и px с помощью переключателя единиц на панели управления.",
  "pageText.aff2e0e9": "Какие методы аутентификации поддерживаются?",
  "pageText.33b1ea50": "Поддерживаются токены Bearer (`-H \"Authorization: Bearer ...\"`) и базовая аутентификация (`-u \"user:pass\"`).",
  "pageText.f1fe0990": "Безопасно ли экранируются специальные символы и одинарные кавычки?",
  "pageText.cacf393b": "Да. JSON тела и строки заголовков правильно экранируются, чтобы не нарушать синтаксис оболочки в терминалах bash и zsh.",
  "pageText.5785e598": "Какие формы поверхности доступны?",
  "pageText.7e6f4277": "Поддерживаются плоская, вдавленная (внутренняя тень), вогнутая (градиентная кривизна) и выпуклая (обратная градиентная кривизна) поверхности.",
  "pageText.9f1d34df": "Как рассчитываются две тени?",
  "pageText.b74d0389": "Генератор автоматически рассчитывает соответствующий блик со стороны источника света и падающую тень с тёмной стороны на основе базового цвета и настроек интенсивности.",
  "pageText.65e43540": "Как работают сеточные градиенты CSS без canvas и SVG?",
  "pageText.19ca56b9": "Несколько слоёв `radial-gradient()` в разных позициях смешиваются на сплошном фоне с эффектами размытия backdrop/filter для очень быстрого отображения на GPU.",
  "pageText.49cc9737": "Можно ли добавлять и перемещать несколько цветовых узлов?",
  "pageText.f51bb3c6": "Да! Можно добавить до 6 собственных цветовых узлов и независимо задавать их координаты X/Y от 0% до 100%.",
  "pageText.51b04c8d": "Какие фигуры предусмотрены?",
  "pageText.f8a18c44": "Предусмотрены треугольники, трапеции, параллелограммы, ромбы, пятиугольники, шестиугольники, звёзды и облачка сообщений.",
  "pageText.27ea598c": "Поддерживаются ли Firefox и современные браузеры Chromium?",
  "pageText.a550ba24": "Да. Для поддержки всех браузеров генерируются современные стандартные свойства (`scrollbar-color` и `scrollbar-width`) и правила поставщика `::-webkit-scrollbar`.",
  "pageText.c0a0fbb0": "Нужны ли файлы изображений для отображения этих узоров?",
  "pageText.da49a542": "Нет. Все узоры генерируются функциями `radial-gradient` и `linear-gradient` на чистом CSS.",
  "pageText.3349cc09": "Можно ли вставлять необработанные HTML-теги <path>?",
  "pageText.bc6be089": "Да. Инструмент автоматически извлекает атрибут `d=\"...\"` из необработанных тегов SVG.",
  "pageText.b5c8f73b": "Чем отличаются ^ и ~ в npm?",
  "pageText.5e52dc36": "`^1.2.3` разрешает обновления, не изменяющие крайнюю левую ненулевую цифру (< 2.0.0), а `~1.2.3` разрешает только изменения уровня исправлений (< 1.3.0).",
  "pageText.0e286eaf": "Какой префикс подсети стандартен для локальных сетей IPv6?",
  "pageText.aa2aad9c": "Префикс /64 — стандартный размер подсети для сегментов локальных сетей IPv6 согласно RFC 4291.",
  "pageText.58ddddc2": "Какие поля составляют выражение cron из 5 частей?",
  "pageText.09710cdd": "Минута (0-59), час (0-23), день месяца (1-31), месяц (1-12) и день недели (0-6, воскресенье=0).",
  "pageText.d3c9a849": "Почему SPF важен для электронной почты домена?",
  "pageText.61b98659": "SPF (Sender Policy Framework) препятствует отправке спамерами неавторизованных писем с подделкой имени вашего домена, защищая репутацию домена и доставляемость почты."
};
